part of harvest_place_app;

// ============================================================================
// HPJ FARMER WORKSPACE
// Extracted from admin_screens.dart without changing Farmer UI/layout logic.
// The file remains part of the same `harvest_place_app` library, so private
// helpers and existing routes continue to work across part files.
// ============================================================================

class _FarmerAccessGateSnapshot {
  final MarketplaceProgramSettings settings;
  final FarmerProfile? profile;

  const _FarmerAccessGateSnapshot({
    required this.settings,
    required this.profile,
  });
}

Future<_FarmerAccessGateSnapshot> fetchFarmerAccessGateSnapshot() async {
  final values = await Future.wait<dynamic>([
    fetchMarketplaceProgramSettings(),
    fetchCurrentFarmerProfile(),
  ]);

  return _FarmerAccessGateSnapshot(
    settings: values[0] as MarketplaceProgramSettings,
    profile: values[1] as FarmerProfile?,
  );
}

PreferredSizeWidget _farmerWorkspaceAppBar(
  BuildContext context,
  String title,
) {
  if (hpjUseMobileAppPresentation(context)) {
    return hpjPortalUtilityAppBar(
      currentPortal: 'farmer',
      includeInbox: true,
    );
  }

  final navigator = Navigator.of(context);
  final canGoBack = navigator.canPop();

  return AppBar(
    automaticallyImplyLeading: false,
    leading: canGoBack
        ? IconButton(
            tooltip: 'Back',
            onPressed: () => navigator.maybePop(),
            icon: const Icon(Icons.arrow_back_rounded),
          )
        : null,
    title: Text(title),
    actions: [
      if (kIsWeb)
        IconButton(
          tooltip: 'Switch Workspace',
          onPressed: () {
            navigator.push(
              MaterialPageRoute<void>(
                builder: (_) => const OwnerWorkspaceSwitcherScreen(
                  currentWorkspace: 'farmer',
                ),
              ),
            );
          },
          icon: const Icon(Icons.apps_rounded),
        )
      else
        const Padding(
          padding: EdgeInsets.only(right: 8),
          child: HpjMobileAccountPortalButton(
            currentPortal: 'farmer',
            compact: true,
          ),
        ),
    ],
  );
}

class FarmerAccessGate extends StatefulWidget {
  final int initialTab;
  final String? initialRecordId;
  final bool bypassWorkspaceGate;

  const FarmerAccessGate({
    super.key,
    this.initialTab = 0,
    this.initialRecordId,
    this.bypassWorkspaceGate = false,
  });

  @override
  State<FarmerAccessGate> createState() => _FarmerAccessGateState();
}

class _FarmerAccessGateState extends State<FarmerAccessGate> {
  Future<_FarmerAccessGateSnapshot>? _accessFuture;

  @override
  void initState() {
    super.initState();
    // Do not start permission requests for a signed-out user.
    if (isLoggedIn && supabase.auth.currentUser != null) {
      _accessFuture = fetchFarmerAccessGateSnapshot();
    }
  }

  void _retryAccess(BuildContext context) {
    Navigator.of(context).pushReplacement(
      MaterialPageRoute<void>(
        builder: (_) => FarmerAccessGate(
          initialTab: widget.initialTab,
          initialRecordId: widget.initialRecordId,
          bypassWorkspaceGate: widget.bypassWorkspaceGate,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (!isLoggedIn || supabase.auth.currentUser == null) {
      return const GuestProtectedScreen(
        title: 'Farmer Partner',
        subtitle: 'Apply to sell with us',
        message: 'Sign in with your customer account to apply as a farmer.',
      );
    }

    return FutureBuilder<_FarmerAccessGateSnapshot>(
      future: _accessFuture ??= fetchFarmerAccessGateSnapshot(),
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting &&
            snapshot.data == null) {
          return Scaffold(
            backgroundColor: FarmColors.background,
            appBar: _farmerWorkspaceAppBar(context, 'Farmer Partner'),
            body: const Center(child: CircularProgressIndicator()),
          );
        }

        final data = snapshot.data;
        if (data == null) {
          return Scaffold(
            backgroundColor: FarmColors.background,
            appBar: _farmerWorkspaceAppBar(context, 'Farmer Partner'),
            body: FarmPage(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(18, 18, 18, 120),
                children: [
                  _MarketplaceProgramNotice(
                    icon: Icons.error_outline,
                    title: 'Could not load farmer access',
                    message:
                        'Please check your connection and try again.',
                    actionLabel: 'Try Again',
                    onAction: () => _retryAccess(context),
                  ),
                ],
              ),
            ),
          );
        }

        final profile = data.profile;
        final settings = data.settings;

        if (profile == null && !settings.farmerApplicationsEnabled) {
          return Scaffold(
            backgroundColor: FarmColors.background,
            appBar: _farmerWorkspaceAppBar(context, 'Farmer Partner'),
            body: FarmPage(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(18, 18, 18, 120),
                children: [
                  _MarketplaceProgramNotice(
                    icon: Icons.agriculture_outlined,
                    title: 'Farmer applications are paused',
                    message:
                        'You can continue shopping as a customer. Please check again when farmer applications reopen.',
                    actionLabel: 'Refresh Status',
                    onAction: () => _retryAccess(context),
                  ),
                ],
              ),
            ),
          );
        }

        if (profile == null) {
          return const FarmerPartnerIntroScreen();
        }

        if (!profile.isApproved) {
          final status =
              profile.verificationStatus.trim().toLowerCase();
          final rejected = status == 'rejected';

          return Scaffold(
            backgroundColor: FarmColors.background,
            appBar: _farmerWorkspaceAppBar(
              context,
              'Farmer Partner',
            ),
            body: FarmPage(
              child: ListView(
                padding: const EdgeInsets.fromLTRB(
                  18,
                  18,
                  18,
                  120,
                ),
                children: [
                  FarmerStatusCard(profile: profile),
                  const SizedBox(height: 14),
                  _MarketplaceProgramNotice(
                    icon: rejected
                        ? Icons.info_outline_rounded
                        : Icons.schedule_outlined,
                    title: rejected
                        ? 'Farmer application needs attention'
                        : 'Farmer application under review',
                    message: rejected
                        ? 'Your Farmer workspace is not active. Review your application details or contact HPJ Support if you need help before trying again.'
                        : 'HPJ is reviewing your Farmer application. Supply, collections, payouts and Farmer market-demand tools will unlock after approval.',
                    actionLabel: 'Refresh Status',
                    onAction: () => _retryAccess(context),
                  ),
                ],
              ),
            ),
          );
        }

        final farmerMode = settings.farmerWorkspaceMode;
        if ((!settings.farmerWorkspaceEnabled ||
                !hpjWorkspaceModeIsLive(farmerMode)) &&
            !widget.bypassWorkspaceGate) {
          return HpjWorkspaceAvailabilityScreen(
            workspace: 'farmer',
            mode: farmerMode,
            message: settings.farmerMaintenanceMessage,
            returnNote: settings.farmerReturnNote,
            currentPortal: 'farmer',
            onRefresh: () => _retryAccess(context),
            onOwnerBypass: () {
              Navigator.of(context).pushReplacement(
                MaterialPageRoute<void>(
                  builder: (_) => FarmerAccessGate(
                    initialTab: widget.initialTab,
                    initialRecordId: widget.initialRecordId,
                    bypassWorkspaceGate: true,
                  ),
                ),
              );
            },
          );
        }

        return FarmerMarketplaceShell(
          profile: profile,
          initialIndex: widget.initialTab,
          initialRecordId: widget.initialRecordId,
        );
      },
    );
  }
}

