class FarmerMarketplaceShell extends StatefulWidget {
  final FarmerProfile profile;
  final int initialIndex;
  final String? initialRecordId;

  const FarmerMarketplaceShell({
    super.key,
    required this.profile,
    this.initialIndex = 0,
    this.initialRecordId,
  });

  @override
  State<FarmerMarketplaceShell> createState() => _FarmerMarketplaceShellState();
}

class _FarmerMarketplaceShellState extends State<FarmerMarketplaceShell>
    with WidgetsBindingObserver {
  int selectedIndex = 0;
  int mobileSectionIndex = 0;
  int desktopSectionIndex = 0;
  int refreshKey = 0;
  late FarmerProfile currentProfile;
  StreamSubscription<AuthState>? _authBoundarySubscription;
  String? _authBoundaryUserId;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    selectedIndex = widget.initialIndex.clamp(0, 4).toInt();
    mobileSectionIndex = _mobileSectionForLegacyIndex(selectedIndex);
    desktopSectionIndex = _desktopSectionForNativeIndex(selectedIndex);
    currentProfile = widget.profile;
    _authBoundaryUserId =
        supabase.auth.currentUser?.id.trim();

    _authBoundarySubscription =
        supabase.auth.onAuthStateChange.listen((authState) {
      if (!mounted) return;

      final rawUserId =
          authState.session?.user.id.trim() ?? '';
      final nextUserId =
          rawUserId.isEmpty ? null : rawUserId;
      final previousUserId = _authBoundaryUserId;

      if (nextUserId == previousUserId) return;

      _authBoundaryUserId = nextUserId;
      clearHpjPrivateAccountMemory();

      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        Navigator.of(context).pushAndRemoveUntil(
          MaterialPageRoute<void>(
            builder: (_) => nextUserId == null || !kIsWeb
                ? const AuthGate()
                : const OwnerWorkspaceSwitcherScreen(
                    showCloseButton: false,
                  ),
          ),
          (route) => false,
        );
      });
    });

    unawaited(
      saveHpjNavigationPreference(
        workspace: 'farmer',
        tab: selectedIndex,
      ),
    );
  }

  Future<void> _reloadProfile() async {
    final operationBoundary =
        captureHpjPrivateOperationBoundary();

    final latest = await fetchCurrentFarmerProfile();

    if (!mounted ||
        latest == null ||
        !isHpjPrivateOperationBoundaryCurrent(operationBoundary)) {
      return;
    }

    setState(() {
      currentProfile = latest;
      refreshKey++;
    });
  }

  Future<void> _revalidateFarmerWorkspace() async {
    if (!mounted) return;

    final operationBoundary =
        captureHpjPrivateOperationBoundary();

    if (!isLoggedIn || supabase.auth.currentUser == null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        Navigator.of(context).pushAndRemoveUntil(
          MaterialPageRoute<void>(
            builder: (_) => const AuthGate(),
          ),
          (route) => false,
        );
      });
      return;
    }

    try {
      final access = await fetchOwnerWorkspaceAccessSnapshot();

      if (!mounted ||
          !isHpjPrivateOperationBoundaryCurrent(operationBoundary)) {
        return;
      }

      final latest = access.farmerProfile;
      final active = latest != null &&
          latest.isApproved &&
          access.programSettings.farmerWorkspaceEnabled;

      if (!active) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          Navigator.of(context).pushAndRemoveUntil(
            MaterialPageRoute<void>(
              builder: (_) => const FarmerAccessGate(
                initialTab: 0,
              ),
            ),
            (route) => false,
          );
        });
        return;
      }

      setState(() {
        currentProfile = latest;
        refreshKey++;
      });
    } catch (error) {
      farmDebugLog(
        'Farmer workspace resume validation skipped: $error',
      );
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state != AppLifecycleState.resumed) return;
    unawaited(_revalidateFarmerWorkspace());
  }

  @override
  void dispose() {
    _authBoundarySubscription?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  static const _pageTitles = <String>[
    'My Farm',
    'My Supply',
    'Operations',
    'My Payments',
    'Account',
  ];

  void refresh() => setState(() => refreshKey++);

  int _mobileSectionForLegacyIndex(int index) {
    switch (index) {
      case 0:
        return 0; // Home
      case 1:
        return 1; // My Crops
      case 2:
      case 3:
        return 3; // Operations / Payments
      case 4:
      default:
        return 4; // Account
    }
  }

  Future<void> _showFarmerMobileOperationsMenu() async {
    if (!mounted) return;

    await showModalBottomSheet<void>(
      context: context,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return SafeArea(
          top: false,
          child: Container(
            margin: const EdgeInsets.all(12),
            padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(22),
              border: Border.all(color: const Color(0xFFDCE7D9)),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 38,
                  height: 4,
                  margin: const EdgeInsets.only(bottom: 8),
                  decoration: BoxDecoration(
                    color: const Color(0xFFD7DDD5),
                    borderRadius: BorderRadius.circular(99),
                  ),
                ),
                ListTile(
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                  leading: const Icon(
                    Icons.local_shipping_outlined,
                    color: FarmColors.deepGreen,
                  ),
                  title: const Text(
                    'Operations',
                    style: TextStyle(fontWeight: FontWeight.w900),
                  ),
                  subtitle: const Text(
                    'Orders, collections and receiving',
                  ),
                  trailing: const Icon(Icons.chevron_right_rounded),
                  onTap: () {
                    Navigator.of(sheetContext).pop();
                    _selectFarmerTab(2);
                  },
                ),
                const Divider(height: 1),
                ListTile(
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(14),
                  ),
                  leading: const Icon(
                    Icons.account_balance_wallet_outlined,
                    color: FarmColors.deepGreen,
                  ),
                  title: const Text(
                    'Earnings',
                    style: TextStyle(fontWeight: FontWeight.w900),
                  ),
                  subtitle: const Text(
                    'Payouts, pending money and history',
                  ),
                  trailing: const Icon(Icons.chevron_right_rounded),
                  onTap: () {
                    Navigator.of(sheetContext).pop();
                    _selectFarmerTab(3);
                  },
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  void _selectFarmerMobileSection(int index) {
    if (!mounted) return;

    final safe = index.clamp(0, 4).toInt();

    // Simple surface:
    // Home | My Crops | Demand | Operations | Account
    if (safe == 0) {
      _selectFarmerTab(0);
      return;
    }

    if (safe == 1) {
      _selectFarmerTab(1);
      return;
    }

    if (safe == 2) {
      setState(() {
        mobileSectionIndex = 2;
        selectedIndex = 0;
      });

      unawaited(
        saveHpjNavigationPreference(
          workspace: 'farmer',
          tab: 0,
        ),
      );
      return;
    }

    if (safe == 3) {
      // Operations is now a direct primary destination.
      // Payments/Earnings remains available inside Operations and
      // through legacy notification/deep-link routes.
      _selectFarmerTab(2);
      return;
    }

    _selectFarmerTab(4);
  }

  int _desktopSectionForNativeIndex(int index) {
    switch (index) {
      case 0:
        return 0;
      case 1:
        return 1;
      case 2:
        return 4;
      case 3:
        return 5;
      case 4:
      default:
        return 8;
    }
  }

  void _selectFarmerTab(int index) {
    if (!mounted) return;
    final safeIndex = index.clamp(0, 4).toInt();
    final desktopFarmer = HpjWebUi.isDesktop(context);

    setState(() {
      selectedIndex = safeIndex;

      if (hpjUseMobileAppPresentation(context)) {
        mobileSectionIndex = _mobileSectionForLegacyIndex(safeIndex);
      }

      if (desktopFarmer) {
        desktopSectionIndex = _desktopSectionForNativeIndex(safeIndex);
      }
    });

    unawaited(
      saveHpjNavigationPreference(
        workspace: 'farmer',
        tab: safeIndex,
      ),
    );
  }

  int get _farmerBottomIndex {
    switch (selectedIndex) {
      case 0:
        return 0; // Home
      case 1:
        return 1; // My Crops
      case 2:
      case 3:
        return 3; // Operations / Payments
      case 4:
      default:
        return 4; // Account
    }
  }

  int get _farmerMobileBottomIndex => mobileSectionIndex.clamp(0, 4).toInt();

  void _selectFarmerBottomOption(int index) {
    switch (index) {
      case 0:
        _selectFarmerTab(0);
        return;
      case 1:
        _selectFarmerTab(1);
        return;
      case 2:
        Navigator.of(context).push<void>(
          MaterialPageRoute<void>(
            builder: (_) => HpjFarmerDemandBoardMvpScreen(
              profile: currentProfile,
            ),
          ),
        );
        return;
      case 3:
        _selectFarmerTab(2);
        return;
      case 4:
        _selectFarmerTab(4);
        return;
      default:
        _selectFarmerTab(0);
    }
  }

  void _switchWorkspace() {
    if (!kIsWeb) {
      unawaited(
        showHpjMobileAccountPortalSheet(
          context,
          currentPortal: 'farmer',
        ),
      );
      return;
    }

    Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => const OwnerWorkspaceSwitcherScreen(
          currentWorkspace: 'farmer',
        ),
      ),
    );
  }

  int get _farmerDesktopRailIndex => desktopSectionIndex;

  void _selectFarmerDesktopSection(int index) {
    if (!mounted) return;
    final safeIndex = index.clamp(0, 8).toInt();
    setState(() => desktopSectionIndex = safeIndex);
  }

  Future<void> _openFarmerPublicPageManager() async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => FarmerPublicProfileEditorScreen(
          farmer: currentProfile,
        ),
      ),
    );

    if (!mounted) return;
    setState(() => refreshKey++);
  }

  void _selectFarmerDesktopOption(int index) {
    switch (index) {
      case 0:
        _selectFarmerTab(0);
        return;
      case 1:
        _selectFarmerTab(1);
        return;
      case 2:
        _selectFarmerDesktopSection(2);
        return;
      case 3:
        _selectFarmerDesktopSection(3);
        return;
      case 4:
        _selectFarmerTab(2);
        return;
      case 5:
        _selectFarmerTab(3);
        return;
      case 6:
        _selectFarmerDesktopSection(6);
        return;
      case 7:
        _selectFarmerDesktopSection(7);
        return;
      case 8:
        _selectFarmerTab(4);
        return;
      default:
        _selectFarmerTab(0);
    }
  }

  @override
  Widget build(BuildContext context) {
    final profile = currentProfile;
    final desktopFarmer = HpjWebUi.isDesktop(context);
    final mobileFarmerPresentation =
        hpjUseMobileAppPresentation(context) && !desktopFarmer;

    final pages = [
      FarmerDashboardScreen(
        profile: profile,
        refreshKey: refreshKey,
        onOpenSupply: () {
          Navigator.of(context).push<void>(
            MaterialPageRoute<void>(
              builder: (_) => FarmerSupplyScreen(
                profile: profile,
                refreshKey: refreshKey,
              ),
            ),
          );
        },
        onOpenOrders: () => _selectFarmerTab(2),
        onOpenPayments: () => _selectFarmerTab(3),
        onOpenAccount: () => _selectFarmerTab(4),
        onRefreshFeed: refresh,
        onOpenDemand: () {
          if (mobileFarmerPresentation) {
            _selectFarmerMobileSection(2);
            return;
          }

          if (desktopFarmer) {
            _selectFarmerDesktopSection(2);
            return;
          }

          Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => HpjFarmerDemandBoardMvpScreen(profile: profile),
            ),
          );
        },
        onOpenCollections: () {
          Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => FarmerCollectionScheduleScreen(profile: profile),
            ),
          );
        },
      ),
      // Internal Manage Produce route retained for notifications,
      // "See all", Add Produce and legacy deep links.
      FarmerSupplyScreen(
        profile: profile,
        refreshKey: refreshKey,
        initialSupplyId: selectedIndex == 1
            ? widget.initialRecordId
            : null,
      ),
      FarmerOperationsScreen(
        profile: profile,
        refreshKey: refreshKey,
      ),
      // Legacy hidden payment route retained only for existing payment
      // notifications / remembered deep links. The visible Operations tab
      // now opens Operations directly; Payments is managed from that page.
      FarmerEarningsScreen(
        profile: profile,
        refreshKey: refreshKey,
        initialPayoutId: selectedIndex == 3
            ? widget.initialRecordId
            : null,
      ),
      FarmerAccountScreen(
        profile: profile,
        onProfileChanged: _reloadProfile,
      ),
    ];

    final desktopPages = <Widget>[
      pages[0],
      pages[1],
      HpjFarmerDemandBoardMvpScreen(
        profile: profile,
        embedded: true,
      ),
      _FarmerWebMyFarmSection(
        profile: profile,
        onEdit: () => unawaited(_openFarmerPublicPageManager()),
      ),
      pages[2],
      pages[3],
      const SupportScreen(
        embedded: true,
      ),
      _FarmerWebResourcesScreen(
        profile: profile,
        onOpenDemand: () => _selectFarmerDesktopSection(2),
        onOpenSupply: () => _selectFarmerTab(1),
        onOpenCollections: () {
          Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => FarmerCollectionScheduleScreen(
                profile: profile,
              ),
            ),
          );
        },
        onOpenProducts: () {
          Navigator.of(context).push(
            MaterialPageRoute<void>(
              builder: (_) => _FarmerPartnerToolShell(
                title: 'My Products',
                child: FarmerProductsScreen(
                  profile: profile,
                  refreshKey: 0,
                  onChanged: () {},
                ),
              ),
            ),
          );
        },
      ),
      pages[4],
    ];

    final destinations = desktopFarmer
        ? <FarmBottomOption>[
            const FarmBottomOption(
              icon: Icon(Icons.home_outlined),
              selectedIcon: Icon(Icons.home_rounded),
              label: 'Home',
            ),
            const FarmBottomOption(
              icon: Icon(Icons.agriculture_outlined),
              selectedIcon: Icon(Icons.agriculture),
              label: 'My Crops',
            ),
            const FarmBottomOption(
              icon: Icon(Icons.bar_chart_outlined),
              selectedIcon: Icon(Icons.bar_chart_rounded),
              label: 'Produce in Demand',
            ),
            const FarmBottomOption(
              icon: Icon(Icons.eco_outlined),
              selectedIcon: Icon(Icons.eco_rounded),
              label: 'My Farm',
            ),
            const FarmBottomOption(
              icon: Icon(Icons.local_shipping_outlined),
              selectedIcon: Icon(Icons.local_shipping_rounded),
              label: 'Orders & Deliveries',
            ),
            const FarmBottomOption(
              icon: Icon(Icons.account_balance_wallet_outlined),
              selectedIcon: Icon(Icons.account_balance_wallet_rounded),
              label: 'Payments',
            ),
            const FarmBottomOption(
              icon: Icon(Icons.chat_bubble_outline_rounded),
              selectedIcon: Icon(Icons.chat_bubble_rounded),
              label: 'Messages',
            ),
            const FarmBottomOption(
              icon: Icon(Icons.menu_book_outlined),
              selectedIcon: Icon(Icons.menu_book_rounded),
              label: 'Resources',
            ),
            const FarmBottomOption(
              icon: Icon(Icons.person_outline),
              selectedIcon: Icon(Icons.person),
              label: 'Account',
            ),
          ]
        : mobileFarmerPresentation
            ? <FarmBottomOption>[
                const FarmBottomOption(
                  icon: Icon(Icons.home_outlined),
                  selectedIcon: Icon(Icons.home_rounded),
                  label: 'Home',
                ),
                const FarmBottomOption(
                  icon: Icon(Icons.eco_outlined),
                  selectedIcon: Icon(Icons.eco_rounded),
                  label: 'My Crops',
                ),
                const FarmBottomOption(
                  icon: Icon(Icons.bar_chart_outlined),
                  selectedIcon: Icon(Icons.bar_chart_rounded),
                  label: 'Market',
                ),
                const FarmBottomOption(
                  icon: Icon(Icons.local_shipping_outlined),
                  selectedIcon: Icon(Icons.local_shipping_rounded),
                  label: 'Operations',
                ),
                const FarmBottomOption(
                  icon: Icon(Icons.person_outline),
                  selectedIcon: Icon(Icons.person),
                  label: 'Account',
                ),
              ]
            : <FarmBottomOption>[
                const FarmBottomOption(
                  icon: Icon(Icons.home_outlined),
                  selectedIcon: Icon(Icons.home_rounded),
                  label: 'Home',
                ),
                const FarmBottomOption(
                  icon: Icon(Icons.eco_outlined),
                  selectedIcon: Icon(Icons.eco_rounded),
                  label: 'My Crops',
                ),
                const FarmBottomOption(
                  icon: Icon(Icons.bar_chart_outlined),
                  selectedIcon: Icon(Icons.bar_chart_rounded),
                  label: 'Market',
                ),
                const FarmBottomOption(
                  icon: Icon(Icons.dashboard_customize_outlined),
                  selectedIcon: Icon(Icons.dashboard_customize_rounded),
                  label: 'Operations',
                ),
                const FarmBottomOption(
                  icon: Icon(Icons.person_outline),
                  selectedIcon: Icon(Icons.person),
                  label: 'Account',
                ),
              ];

    final scaffoldSelectedIndex = desktopFarmer
        ? _farmerDesktopRailIndex
        : mobileFarmerPresentation
            ? _farmerMobileBottomIndex
            : _farmerBottomIndex;

    return PopScope(
      canPop: false,
      onPopInvokedWithResult: (didPop, result) {
        if (didPop || !mounted) return;

        if (mobileFarmerPresentation && mobileSectionIndex != 0) {
          _selectFarmerTab(0);
          return;
        }

        if (selectedIndex != 0) {
          _selectFarmerTab(0);
        }
        // Farmer Home is the workspace root. Portal changes are available
        // from the signed-in account control.
      },
       child: HpjResponsiveWorkspaceScaffold(
        workspaceLabel: desktopFarmer ? 'Farmer Portal' : 'Farmer',
        desktopMaxContentWidth: desktopFarmer ? 1480 : 1180,
        backgroundColor: FarmColors.background,
        appBar: hpjUseMobileAppPresentation(context)
            ? hpjPortalUtilityAppBar(
                currentPortal: 'farmer',
                includeInbox: true,
              )
            : desktopFarmer
            ? _FarmerWebPortalTopBar(
                profile: profile,
                onHome: () => _selectFarmerTab(0),
                onAccount: () => _selectFarmerTab(4),
                onSwitchWorkspace: _switchWorkspace,
              )
            : AppBar(
          automaticallyImplyLeading: false,
          backgroundColor: const Color(0xFFF8F5EF),
          surfaceTintColor: Colors.transparent,
          leadingWidth: !kIsWeb || selectedIndex == 0 ? 58 : null,
          leading: !kIsWeb || selectedIndex == 0
              ? Padding(
                  padding: const EdgeInsets.only(left: 12, top: 7, bottom: 7),
                  child: Container(
                    padding: const EdgeInsets.all(5),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(14),
                      border: Border.all(color: const Color(0xFFE5E1D8)),
                    ),
                    child: Image.asset(
                      'lib/assets/images/logo.png',
                      fit: BoxFit.contain,
                      errorBuilder: (_, __, ___) => const Icon(
                        Icons.agriculture_rounded,
                        color: FarmColors.deepGreen,
                        size: 23,
                      ),
                    ),
                  ),
                )
              : IconButton(
                  tooltip: 'Back to Farmer Home',
                  onPressed: () => _selectFarmerTab(0),
                  icon: const Icon(Icons.arrow_back_rounded),
                ),
          title: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                !kIsWeb && mobileSectionIndex == 2
                    ? 'Market'
                    : _pageTitles[selectedIndex],
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: FarmColors.deepGreen,
                  fontWeight: FontWeight.w900,
                  letterSpacing: -0.4,
                ),
              ),
              if (!kIsWeb || selectedIndex == 0)
                Text(
                  profile.farmName.trim().isEmpty
                      ? 'Farmer Portal'
                      : profile.farmName.trim(),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                    color: FarmColors.mutedText,
                    fontSize: 10.5,
                    fontWeight: FontWeight.w700,
                  ),
                ),
            ],
          ),
          actions: [
            const HpjInboxActionButton(),
            if (kIsWeb)
              IconButton(
                tooltip: 'Switch Workspace',
                onPressed: _switchWorkspace,
                icon: const Icon(Icons.apps_rounded),
              )
            else
              const Padding(
                padding: EdgeInsets.only(left: 2, right: 6),
                child: HpjMobileAccountPortalButton(
                  currentPortal: 'farmer',
                  compact: false,
                ),
              ),
            const SizedBox(width: 4),
          ],
        ),
        body: desktopFarmer
            ? desktopPages[desktopSectionIndex]
            : mobileFarmerPresentation && mobileSectionIndex == 2
                ? HpjFarmerDemandBoardMvpScreen(
                    profile: profile,
                    embedded: true,
                  )
                : pages[selectedIndex],
        selectedIndex: scaffoldSelectedIndex,
        destinations: destinations,
        onSelected: desktopFarmer
            ? _selectFarmerDesktopOption
            : mobileFarmerPresentation
                ? _selectFarmerMobileSection
                : _selectFarmerBottomOption,
      ),
    );
  }
}


class _FarmerWebPortalTopBar extends StatelessWidget
    implements PreferredSizeWidget {
  final FarmerProfile profile;
  final VoidCallback onHome;
  final VoidCallback onAccount;
  final VoidCallback onSwitchWorkspace;

  const _FarmerWebPortalTopBar({
    required this.profile,
    required this.onHome,
    required this.onAccount,
    required this.onSwitchWorkspace,
  });

  @override
  Size get preferredSize => const Size.fromHeight(66);

  Widget _navButton(
    BuildContext context, {
    required String label,
    required VoidCallback onTap,
    bool active = false,
  }) {
    return TextButton(
      onPressed: onTap,
      style: TextButton.styleFrom(
        foregroundColor:
            active ? FarmColors.primary : FarmColors.deepGreen,
        padding: const EdgeInsets.symmetric(
          horizontal: 7,
          vertical: 10,
        ),
        textStyle: TextStyle(
          fontSize: 10.8,
          fontWeight: active ? FontWeight.w900 : FontWeight.w800,
        ),
      ),
      child: Text(label),
    );
  }

  void _openShop(BuildContext context) {
    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => const MainNavigation(
          initialIndex: 1,
        ),
      ),
    );
  }

  String get _farmerLabel {
    final clean = profile.farmerName.trim();
    return clean.isEmpty ? 'Farmer' : clean;
  }

  String get _farmerInitials {
    final parts = _farmerLabel
        .split(RegExp(r'\s+'))
        .where((part) => part.isNotEmpty)
        .toList();
    if (parts.isEmpty) return 'F';
    if (parts.length == 1) {
      return parts.first.substring(0, 1).toUpperCase();
    }
    return '${parts.first.substring(0, 1)}${parts.last.substring(0, 1)}'
        .toUpperCase();
  }

  @override
  Widget build(BuildContext context) {
    return Material(
      color: const Color(0xFFFFFEFC),
      child: Container(
        height: preferredSize.height,
        padding: const EdgeInsets.symmetric(
          horizontal: 18,
        ),
