// =====================================================
// HPJ FARMER ELITE MVP — RESPONSIVE WEBSITE + APP HOME
// Approved visual target:
// - Website: farm hero, 5 KPI cards, featured demand, supply, activity,
//   collections, payments and alerts.
// - App: compact farm hero, horizontal KPIs, featured demand, supply/activity,
//   payment CTA and existing 5-tab farmer navigation.
// All data/actions reuse the existing Farmer services and routes.
// =====================================================

class _FarmerEliteMvpHome extends StatefulWidget {
  final FarmerProfile profile;
  final List<FarmerSupplyForecast> activeSupplies;
  final List<FarmerSupplyForecast> suppliesNeedingReview;
  final List<FarmerMarketDemandOpportunity> opportunities;
  final Set<String> matchingDemandKeys;
  final List<FarmerCollectionScheduleItem> upcomingCollections;
  final List<FarmerPayout> payouts;
  final List<_FarmerTodayNotification> notifications;
  final UserExperiencePreferences preferences;
  final int refreshKey;
  final HpjAgricultureFeedAction onAgricultureAction;
  final VoidCallback onOpenSupply;
  final VoidCallback onOpenDemand;
  final VoidCallback onOpenCollections;
  final VoidCallback onOpenOrders;
  final VoidCallback onOpenPayments;
  final VoidCallback onOpenAccount;
  final VoidCallback onRefresh;

  const _FarmerEliteMvpHome({
    required this.profile,
    required this.activeSupplies,
    required this.suppliesNeedingReview,
    required this.opportunities,
    required this.matchingDemandKeys,
    required this.upcomingCollections,
    required this.payouts,
    required this.notifications,
    required this.preferences,
    required this.refreshKey,
    required this.onAgricultureAction,
    required this.onOpenSupply,
    required this.onOpenDemand,
    required this.onOpenCollections,
    required this.onOpenOrders,
    required this.onOpenPayments,
    required this.onOpenAccount,
    required this.onRefresh,
  });

  @override
  State<_FarmerEliteMvpHome> createState() => _FarmerEliteMvpHomeState();
}

class _FarmerEliteMvpHomeState extends State<_FarmerEliteMvpHome> {
  String filter = 'All';

  bool _urgent(FarmerMarketDemandOpportunity item) =>
      item.demandSignal == 'urgent' ||
      item.demandSignal == 'committed_need';

  bool _thisWeek(FarmerMarketDemandOpportunity item) {
    final date = item.nextNeedBy;
    if (date == null) return false;
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final target = DateTime(date.year, date.month, date.day);
    final days = target.difference(today).inDays;
    return days >= 0 && days <= 7;
  }

  bool _matches(FarmerMarketDemandOpportunity item) {
    final demandName = hpjSmartNormalizeSearch(item.productName);
    if (demandName.isEmpty) return false;

    for (final supply in widget.activeSupplies) {
      final cropName = hpjSmartNormalizeSearch(supply.cropName);
      if (cropName.isEmpty) continue;

      final sameName = cropName == demandName;
      final closeName = cropName.contains(demandName) ||
          demandName.contains(cropName);

      if (sameName || closeName) {
        return true;
      }
    }

    return widget.matchingDemandKeys.contains(
      hpjFarmerDemandWatchKey(item.productName, item.unit),
    );
  }

  List<FarmerMarketDemandOpportunity> get _filteredDemand {
    final rows = List<FarmerMarketDemandOpportunity>.from(widget.opportunities);
    switch (filter) {
      case 'Urgent':
        return rows.where(_urgent).toList();
      case 'This week':
        return rows.where(_thisWeek).toList();
      case 'My crops':
        return rows.where(_matches).toList();
      case 'Best match':
        rows.sort((a, b) {
          final aMatch = _matches(a) ? 1 : 0;
          final bMatch = _matches(b) ? 1 : 0;
          if (aMatch != bMatch) return bMatch.compareTo(aMatch);
          final aUrgent = _urgent(a) ? 1 : 0;
          final bUrgent = _urgent(b) ? 1 : 0;
          if (aUrgent != bUrgent) return bUrgent.compareTo(aUrgent);
          return b.opportunityGap.compareTo(a.opportunityGap);
        });
        return rows;
      default:
        return rows;
    }
  }

  int get _urgentCount => widget.opportunities.where(_urgent).length;

  double get _pendingPayments {
    return widget.payouts
        .where((item) => item.payoutStatus == 'pending')
        .fold<double>(0, (sum, item) => sum + item.netAmount);
  }

  double get _earnedThisMonth {
    final now = DateTime.now();
    return widget.payouts.where((item) {
      final created = item.createdAt?.toLocal();
      return created != null &&
          created.year == now.year &&
          created.month == now.month;
    }).fold<double>(0, (sum, item) => sum + item.grossAmount);
  }

  double _supplyQuantity(FarmerSupplyForecast supply) {
    final values = <double>[
      supply.harvestedQuantity ?? 0,
      supply.expectedQuantity ?? 0,
      supply.quantityGrowing ?? 0,
    ];
    var best = 0.0;
    for (final value in values) {
      if (value.isFinite && value > best) best = value;
    }
    return best;
  }

  FarmerMarketDemandOpportunity? get _featuredDemand {
    final rows = _filteredDemand;
    return rows.isEmpty ? null : rows.first;
  }

  bool get _hasFarmerSocialFeed =>
      widget.preferences.showFreshReels ||
      widget.preferences.showAgricultureNews;

  Widget _farmerSocialFeed(BuildContext context) {
    final preferences = widget.preferences;
    if (!_hasFarmerSocialFeed) return const SizedBox.shrink();

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (preferences.showFreshReels) ...[
          FreshReelFeedPreviewCard(
            preferences: preferences,
            audience: 'farmer',
            placement: freshReelPlacementFarmerFeed,
            refreshKey: widget.refreshKey,
          ),
          if (preferences.showAgricultureNews)
            const SizedBox(height: 12),
        ],
        if (preferences.showAgricultureNews)
          HpjAgricultureUpdatesSection(
            audience: 'farmer',
            workspace: 'farmer',
            limit: 3,
            refreshKey: widget.refreshKey,
            title: 'Farmer notices & news',
            subtitle:
                'HPJ notices, Jamaican agriculture news and useful updates selected for your farm.',
            socialStyle: true,
            showImages: preferences.showFeedImages,
            onAction: widget.onAgricultureAction,
          ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final desktop = HpjWebUi.isDesktop(context);

    if (!desktop) {
      return _HpjFarmerApprovedHome(
        profile: widget.profile,
        supplies: widget.activeSupplies,
        demand: widget.opportunities,
        collections: widget.upcomingCollections,
        notifications: widget.notifications,
        preferences: widget.preferences,
        refreshKey: widget.refreshKey,
        matches: _matches,
        quantityFor: _supplyQuantity,
        onOpenSupply: widget.onOpenSupply,
        onOpenDemand: widget.onOpenDemand,
        onOpenCollections: widget.onOpenCollections,
        onOpenOrders: widget.onOpenOrders,
        onAgricultureAction: widget.onAgricultureAction,
        onRefresh: widget.onRefresh,
      );
    }

    final demand = _HpjFarmerV3Demand(
      opportunities: widget.opportunities,
      total: widget.opportunities.length,
      onOpen: widget.onOpenDemand,
    );

    final supply = _HpjFarmerV3Supply(
      supplies: widget.activeSupplies,
      quantityFor: _supplyQuantity,
      onOpen: widget.onOpenSupply,
    );

    final matches = _HpjFarmerV3Matches(
      opportunities: widget.opportunities,
      matches: _matches,
      onOpen: widget.onOpenDemand,
    );

    final collection = _HpjFarmerV3Collection(
      profile: widget.profile,
      next: widget.upcomingCollections.isEmpty
          ? null
          : widget.upcomingCollections.first,
      onOpen: widget.onOpenCollections,
    );

    final matchCount = widget.opportunities.where(_matches).length;
    final pickupCount = widget.upcomingCollections.length;

    return RefreshIndicator(
      onRefresh: () async {
        widget.onRefresh();
        await Future<void>.delayed(const Duration(milliseconds: 140));
      },
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        padding: EdgeInsets.fromLTRB(
          desktop ? 18 : 12,
          desktop ? 16 : 10,
          desktop ? 18 : 12,
          desktop ? 90 : 116,
        ),
        children: [
          _FarmerEliteHero(
            profile: widget.profile,
            desktop: desktop,
            onAddSupply: widget.onOpenSupply,
          ),
          const SizedBox(height: 10),
          _HpjFarmerMvpSummaryStrip(
            cropCount: widget.activeSupplies.length,
            matchCount: matchCount,
            pickupCount: pickupCount,
          ),
          const SizedBox(height: 10),

          // HOME-FIRST COMMUNICATION
          // Reels + farmer notices now sit near the top of Home so farmers
          // see updates before moving into supply and demand workflows.
          if (_hasFarmerSocialFeed) ...[
            _farmerSocialFeed(context),
            const SizedBox(height: 10),
          ],

          _FarmerEliteAlertsPanel(
            desktop: desktop,
            notifications: widget.notifications,
            reviewCount: widget.suppliesNeedingReview.length,
            onOpenSupply: widget.onOpenSupply,
            onOpenDemand: widget.onOpenDemand,
          ),
          const SizedBox(height: 10),

          // MVP operating flow:
          // demand -> supply -> matched opportunities -> collection.
          demand,
          const SizedBox(height: 10),
          supply,
          const SizedBox(height: 10),
          matches,
          const SizedBox(height: 10),
          collection,

          // Earnings intentionally stays off Home. It is accessed from
          // the Operations toolbar/menu instead.
        ],
      ),
    );
  }

  Widget _buildMobileDashboard() {
    final demand = _HpjFarmerV3Demand(
      opportunities: widget.opportunities,
      total: widget.opportunities.length,
      onOpen: widget.onOpenDemand,
    );
    final supply = _HpjFarmerV3Supply(
      supplies: widget.activeSupplies,
      quantityFor: _supplyQuantity,
      onOpen: widget.onOpenSupply,
    );
    final money = _HpjFarmerV3Money(
      gross: _earnedThisMonth,
      pending: _pendingPayments,
      onOpen: widget.onOpenPayments,
    );
    final collection = _HpjFarmerV3Collection(
      profile: widget.profile,
      next: widget.upcomingCollections.isEmpty
          ? null : widget.upcomingCollections.first,
      onOpen: widget.onOpenCollections,
    );
    final tools = _HpjFarmerV3Tools(
      onSupply: widget.onOpenSupply,
      onCollection: widget.onOpenCollections,
      onOrders: widget.onOpenOrders,
      onProfile: widget.onOpenAccount,
    );
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        LayoutBuilder(builder: (context, layout) {
          if (layout.maxWidth < 650) {
            return Column(children: [
              demand, const SizedBox(height: 12), supply,
            ]);
          }
          return Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Expanded(child: demand), const SizedBox(width: 12),
            Expanded(child: supply),
          ]);
        }),
        const SizedBox(height: 12),
        LayoutBuilder(builder: (context, layout) {
          if (layout.maxWidth >= 760) {
            return Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Expanded(child: money), const SizedBox(width: 10),
              Expanded(child: collection), const SizedBox(width: 10),
              Expanded(child: tools),
            ]);
          }
          if (layout.maxWidth >= 350) {
            return Column(children: [
              Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Expanded(child: money), const SizedBox(width: 10),
                Expanded(child: collection),
              ]),
              const SizedBox(height: 12), tools,
            ]);
          }
          return Column(children: [
            money, const SizedBox(height: 12), collection,
            const SizedBox(height: 12), tools,
          ]);
        }),
        const SizedBox(height: 12),
        _HpjFarmerV3StoryBanner(profile: widget.profile),
        const SizedBox(height: 12),
        _FarmerEliteActivityPanel(
          desktop: false,
          notifications: widget.notifications,
          opportunities: widget.opportunities,
          matches: _matches,
          onSeeAll: widget.onOpenDemand,
        ),
        const SizedBox(height: 12),
        _HpjFarmerSuperMarketInsight(
          opportunity: widget.opportunities.isEmpty
              ? null : widget.opportunities.first,
          onOpenDemand: widget.onOpenDemand,
        ),
        const SizedBox(height: 12),
        _FarmerMobileGrowthNetworkCard(profile: widget.profile),
      ],
    );
  }

}




