class _HpjFarmerApprovedHome extends StatelessWidget {
  final FarmerProfile profile;
  final List<FarmerSupplyForecast> supplies;
  final List<FarmerMarketDemandOpportunity> demand;
  final List<FarmerCollectionScheduleItem> collections;
  final List<_FarmerTodayNotification> notifications;
  final UserExperiencePreferences preferences;
  final int refreshKey;
  final bool Function(FarmerMarketDemandOpportunity) matches;
  final double Function(FarmerSupplyForecast) quantityFor;
  final VoidCallback onOpenSupply;
  final VoidCallback onOpenDemand;
  final VoidCallback onOpenCollections;
  final VoidCallback onOpenOrders;
  final HpjAgricultureFeedAction onAgricultureAction;
  final VoidCallback onRefresh;

  const _HpjFarmerApprovedHome({
    required this.profile,
    required this.supplies,
    required this.demand,
    required this.collections,
    required this.notifications,
    required this.preferences,
    required this.refreshKey,
    required this.matches,
    required this.quantityFor,
    required this.onOpenSupply,
    required this.onOpenDemand,
    required this.onOpenCollections,
    required this.onOpenOrders,
    required this.onAgricultureAction,
    required this.onRefresh,
  });

  void _open(BuildContext context, Widget screen) {
    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(builder: (_) => screen),
    );
  }

  void _openFarmEditor(BuildContext context) {
    _open(
      context,
      FarmerPublicProfileEditorScreen(
        farmer: profile,
      ),
    );
  }

  void _openReels(BuildContext context) {
    _open(
      context,
      FarmerFreshReelsHubScreen(
        profile: profile,
      ),
    );
  }

  void _openStories(BuildContext context) {
    _open(
      context,
      HpjFarmerStoriesScreen(
        profile: profile,
      ),
    );
  }

  String _number(num value) {
    final d = value.toDouble();
    if (d == d.roundToDouble()) return d.toInt().toString();
    return d.toStringAsFixed(1);
  }

  String _date(DateTime? value) {
    if (value == null) return 'Date to be confirmed';
    const months = <String>[
      'Jan','Feb','Mar','Apr','May','Jun',
      'Jul','Aug','Sep','Oct','Nov','Dec',
    ];
    return '${months[value.month - 1]} ${value.day}, ${value.year}';
  }

  double _supplyQty(FarmerSupplyForecast item) {
    final values = <double>[
      item.harvestedQuantity ?? 0,
      item.expectedQuantity ?? 0,
      item.quantityGrowing ?? 0,
    ];
    return values.fold<double>(0, (a, b) => b > a ? b : a);
  }

  BoxDecoration _surface({double radius = 22}) {
    return BoxDecoration(
      color: Colors.white,
      borderRadius: BorderRadius.circular(radius),
      border: Border.all(color: const Color(0xFFDCE6D9)),
      boxShadow: [
        BoxShadow(
          color: const Color(0xFF0D4B32).withOpacity(.035),
          blurRadius: 16,
          offset: const Offset(0, 5),
        ),
      ],
    );
  }

  Widget _sectionTitle({
    required IconData icon,
    required String title,
    required String subtitle,
    required VoidCallback onTap,
    Color iconColor = const Color(0xFF19713F),
    Color iconBackground = const Color(0xFFE7F4E5),
  }) {
    return Row(
