  Widget _farmHero(BuildContext context) {
    final fallbackName = profile.farmName.trim().isNotEmpty
        ? profile.farmName.trim()
        : profile.farmerName.trim().isNotEmpty
            ? '${profile.farmerName.trim()} Farm'
            : 'My Farm';

    return FutureBuilder<FarmPublicProfileRecord?>(
      future: fetchFarmPublicProfile(
        profile.id,
        includeUnpublished: true,
      ),
      builder: (context, snapshot) {
        final farm = snapshot.data;
        final cover = cleanHostedImageUrl(farm?.coverImageUrl);
        final logo = cleanHostedImageUrl(farm?.logoImageUrl);
        final farmName = (farm?.publicName.trim().isNotEmpty ?? false)
            ? farm!.publicName.trim()
            : fallbackName;
        final community = farm?.community.trim() ?? '';
        final parish = (farm?.parish.trim().isNotEmpty ?? false)
            ? farm!.parish.trim()
            : profile.parish.trim();
        final location = <String>[
          if (community.isNotEmpty) community,
          if (parish.isNotEmpty) parish,
        ].join(' • ');
        final verified = farm?.hpjVerified == true;

        return Container(
          clipBehavior: Clip.antiAlias,
          decoration: _surface(radius: 23),
          child: Column(
            children: [
              SizedBox(
                height: 176,
                width: double.infinity,
                child: cover == null
                    ? const DecoratedBox(
                        decoration: BoxDecoration(
                          gradient: LinearGradient(
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                            colors: [
                              Color(0xFFDDEED7),
                              Color(0xFF9DC18A),
                              Color(0xFF356C49),
                            ],
                          ),
                        ),
                        child: Center(
                          child: Icon(
                            Icons.landscape_rounded,
                            size: 68,
                            color: Colors.white70,
                          ),
                        ),
                      )
                    : Image.network(
                        cover,
                        fit: BoxFit.cover,
                        errorBuilder: (_, __, ___) => const DecoratedBox(
                          decoration: BoxDecoration(
                            gradient: LinearGradient(
                              colors: [
                                Color(0xFFDDEED7),
                                Color(0xFF75A56D),
                              ],
                            ),
                          ),
                        ),
                      ),
              ),
              Padding(
                padding: const EdgeInsets.fromLTRB(14, 12, 14, 14),
                child: Column(
                  children: [
                      Row(
                        crossAxisAlignment: CrossAxisAlignment.end,
                        children: [
                          Container(
                            width: 70,
                            height: 70,
                            padding: const EdgeInsets.all(3),
                            decoration: BoxDecoration(
                              color: Colors.white,
                              shape: BoxShape.circle,
                              border: Border.all(
                                color: const Color(0xFFE8D7A0),
                                width: 2,
                              ),
                              boxShadow: [
                                BoxShadow(
                                  color: Colors.black.withOpacity(.08),
                                  blurRadius: 10,
                                  offset: const Offset(0, 4),
                                ),
                              ],
                            ),
                            child: ClipOval(
                              child: logo == null
                                  ? const ColoredBox(
                                      color: Color(0xFFF2F7ED),
                                      child: Icon(
                                        Icons.agriculture_rounded,
                                        size: 38,
                                        color: FarmColors.deepGreen,
                                      ),
                                    )
                                  : Image.network(
                                      logo,
                                      fit: BoxFit.cover,
                                      errorBuilder: (_, __, ___) =>
                                          const Icon(
                                        Icons.agriculture_rounded,
                                        color: FarmColors.deepGreen,
                                      ),
                                    ),
                            ),
                          ),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Padding(
                              padding: const EdgeInsets.only(bottom: 4),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    farmName,
                                    maxLines: 2,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(
                                      color: FarmColors.ink,
                                      fontSize: 21,
                                      height: 1.05,
                                      fontWeight: FontWeight.w900,
                                      letterSpacing: -.4,
                                    ),
                                  ),
                                  if (verified) ...[
                                    const SizedBox(height: 5),
                                    const Row(
                                      children: [
                                        Icon(
                                          Icons.verified_rounded,
                                          color: FarmColors.primary,
                                          size: 17,
                                        ),
                                        SizedBox(width: 5),
                                        Text(
                                          'HPJ Verified Farmer',
                                          style: TextStyle(
                                            color: FarmColors.primary,
                                            fontSize: 10.5,
                                            fontWeight: FontWeight.w900,
                                          ),
                                        ),
                                      ],
                                    ),
                                  ],
                                  if (location.isNotEmpty) ...[
                                    const SizedBox(height: 5),
                                    Row(
                                      children: [
                                        const Icon(
                                          Icons.location_on_rounded,
                                          color: FarmColors.mutedText,
                                          size: 16,
                                        ),
                                        const SizedBox(width: 4),
                                        Expanded(
                                          child: Text(
                                            location,
                                            maxLines: 1,
                                            overflow: TextOverflow.ellipsis,
                                            style: const TextStyle(
                                              color: FarmColors.mutedText,
                                              fontSize: 10.5,
                                              fontWeight: FontWeight.w600,
                                            ),
                                          ),
                                        ),
                                      ],
                                    ),
                                  ],
                                ],
                              ),
                            ),
                          ),
                          const SizedBox(width: 4),
                          IconButton(
                            tooltip: 'Edit Farm',
                            onPressed: () => _openFarmEditor(context),
                            style: IconButton.styleFrom(
                              foregroundColor: FarmColors.deepGreen,
                              backgroundColor: const Color(0xFFF6FBF4),
                              side: const BorderSide(
                                color: Color(0xFFC9DCC4),
                              ),
                            ),
                            icon: const Icon(Icons.edit_rounded, size: 18),
                          ),
                        ],
                      ),
                      const SizedBox(height: 10),
                      const Wrap(
                        spacing: 7,
                        runSpacing: 7,
                        children: [
                          _HpjHomeIdentityChip(
                            icon: Icons.eco_rounded,
                            label: 'Local',
                          ),
                          _HpjHomeIdentityChip(
                            icon: Icons.grass_rounded,
                            label: 'Open Field',
                          ),
                          _HpjHomeIdentityChip(
                            icon: Icons.storefront_rounded,
                            label: 'Fresh Produce',
                          ),
                        ],
                      ),
                    ],
                  ),
              ),
            ],
          ),
        );
      },
    );
  }

