  void _openMarketNeedDetails(
    BuildContext context,
    FarmerMarketDemandOpportunity item,
  ) {
    final gap = item.opportunityGap < 0 ? 0 : item.opportunityGap;
    final isMatch = matches(item);

    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => DraggableScrollableSheet(
        initialChildSize: .72,
        minChildSize: .52,
        maxChildSize: .92,
        expand: false,
        builder: (context, controller) => Container(
          decoration: const BoxDecoration(
            color: Color(0xFFF8FAF6),
            borderRadius: BorderRadius.vertical(top: Radius.circular(26)),
          ),
          child: ListView(
            controller: controller,
            padding: const EdgeInsets.fromLTRB(14, 10, 14, 28),
            children: [
              Center(
                child: Container(
                  width: 42,
                  height: 4,
                  decoration: BoxDecoration(
                    color: const Color(0xFFD2D9CF),
                    borderRadius: BorderRadius.circular(999),
                  ),
                ),
              ),
              const SizedBox(height: 14),
              ClipRRect(
                borderRadius: BorderRadius.circular(20),
                child: SizedBox(
                  height: 190,
                  child: HpjProductThumb(
                    productName: item.productName,
                    size: 220,
                    radius: 0,
                  ),
                ),
              ),
              const SizedBox(height: 14),
              Row(
                children: [
                  Expanded(
                    child: Text(
                      item.productName,
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 24,
                        height: 1,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                  const _HpjLivePill(),
                ],
              ),
              const SizedBox(height: 6),
              Text(
                item.demandSignal == 'urgent' ||
                        item.demandSignal == 'committed_need'
                    ? 'Strong market need'
                    : 'Open market need',
                style: const TextStyle(
                  color: Color(0xFFA66A00),
                  fontSize: 10.5,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 14),
              Container(
                padding: const EdgeInsets.all(12),
                decoration: _surface(radius: 18),
                child: Column(
                  children: [
                    _HpjHomeDetailRow(
                      icon: Icons.inventory_2_outlined,
                      label: 'Needed now',
                      value: '${_number(item.visibleDemand)} ${item.unit}',
                    ),
                    const Divider(height: 20),
                    _HpjHomeDetailRow(
                      icon: Icons.trending_up_rounded,
                      label: 'Still needed',
                      value: '${_number(gap)} ${item.unit}',
                    ),
                    const Divider(height: 20),
                    _HpjHomeDetailRow(
                      icon: Icons.event_outlined,
                      label: 'Needed by',
                      value: _date(item.nextNeedBy),
                    ),
                    const Divider(height: 20),
                    _HpjHomeDetailRow(
                      icon: Icons.link_rounded,
                      label: 'Your match',
                      value: isMatch ? 'Matches your crops' : 'Open to supply',
                    ),
                    if (item.myReportedSupply > 0) ...[
                      const Divider(height: 20),
                      _HpjHomeDetailRow(
                        icon: Icons.eco_outlined,
                        label: 'You reported',
                        value:
                            '${_number(item.myReportedSupply)} ${item.unit}',
                      ),
                    ],
                    if (item.myHpjConfirmedSupply > 0) ...[
                      const Divider(height: 20),
                      _HpjHomeDetailRow(
                        icon: Icons.verified_rounded,
                        label: 'HPJ confirmed',
                        value:
                            '${_number(item.myHpjConfirmedSupply)} ${item.unit}',
                      ),
                    ],
                  ],
                ),
              ),
              const SizedBox(height: 12),
              OutlinedButton.icon(
                onPressed: () {
                  Navigator.of(sheetContext).pop();
                  _showHpjFarmerCropGuide(
                    context,
                    item.productName,
                    demand: item,
                  );
                },
                icon: const Icon(Icons.menu_book_rounded),
                label: const Text('View crop guide'),
              ),
              const SizedBox(height: 8),
              FilledButton.icon(
                onPressed: () {
                  Navigator.of(sheetContext).pop();
                  onOpenDemand();
                },
                icon: const Icon(Icons.handshake_outlined),
                label: const Text(
                  'I can supply this',
                  style: TextStyle(fontWeight: FontWeight.w900),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  void _openProduceDetails(
    BuildContext context,
