    final status = review
        ? 'Needs Review'
        : supply.isHpjConfirmed
            ? 'Live in Shop'
            : 'Coming Soon';

    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => DraggableScrollableSheet(
        initialChildSize: .68,
        minChildSize: .50,
        maxChildSize: .90,
        expand: false,
        builder: (context, controller) => Container(
          decoration: const BoxDecoration(
            color: Color(0xFFF8FAF6),
            borderRadius: BorderRadius.vertical(top: Radius.circular(26)),
          ),
          child: ListView(
            controller: controller,
            padding: const EdgeInsets.fromLTRB(14, 10, 14, 28),
            children: [
              Center(
                child: Container(
                  width: 42,
                  height: 4,
                  decoration: BoxDecoration(
                    color: const Color(0xFFD2D9CF),
                    borderRadius: BorderRadius.circular(999),
                  ),
                ),
              ),
              const SizedBox(height: 14),
              ClipRRect(
                borderRadius: BorderRadius.circular(20),
                child: SizedBox(
                  height: 190,
                  child: HpjProductThumb(
                    productName: supply.cropName,
                    size: 220,
                    radius: 0,
                  ),
                ),
              ),
              const SizedBox(height: 14),
              Row(
                children: [
                  Expanded(
                    child: Text(
                      supply.cropName,
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 24,
                        height: 1,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                  _HpjStatusPill(
                    label: status,
                    active: supply.isHpjConfirmed && !review,
                    warning: !supply.isHpjConfirmed && !review,
                  ),
                ],
              ),
              const SizedBox(height: 14),
              Container(
                padding: const EdgeInsets.all(12),
                decoration: _surface(radius: 18),
                child: Column(
                  children: [
                    _HpjHomeDetailRow(
                      icon: Icons.inventory_2_outlined,
                      label: 'Available',
                      value:
                          '${_number(_supplyQty(supply))} ${supply.unit}',
                    ),
                    const Divider(height: 20),
                    _HpjHomeDetailRow(
                      icon: Icons.event_available_outlined,
                      label: 'Ready date',
                      value: _date(supply.expectedHarvestDate),
                    ),
                    const Divider(height: 20),
                    _HpjHomeDetailRow(
                      icon: Icons.storefront_outlined,
                      label: 'Shop status',
                      value: status,
                    ),
                  ],
                ),
              ),
              const SizedBox(height: 12),
              OutlinedButton.icon(
                onPressed: () {
                  Navigator.of(sheetContext).pop();
                  _showHpjFarmerCropGuide(
                    context,
                    supply.cropName,
                    supply: supply,
                  );
                },
                icon: const Icon(Icons.menu_book_rounded),
                label: const Text('View crop guide'),
              ),
              const SizedBox(height: 8),
              FilledButton.icon(
                onPressed: () {
                  Navigator.of(sheetContext).pop();
                  onOpenSupply();
                },
                icon: const Icon(Icons.edit_rounded),
                label: const Text(
                  'Edit crop',
                  style: TextStyle(fontWeight: FontWeight.w900),
                ),
              ),
            ],
          ),
        ),
      ),
    );
