  Future<void> _openHomeSponsor(
    BuildContext context,
    HpjSponsorCampaign campaign,
  ) async {
    if (campaign.ctaType == 'farm') {
      final farmerId = campaign.targetFarmerId.trim();
      if (farmerId.isEmpty) return;
      await Navigator.of(context).push<void>(
        MaterialPageRoute<void>(
          builder: (_) => PublicFarmProfileScreen(
            farmerId: farmerId,
            sourceWorkspace: 'farmer',
          ),
        ),
      );
      return;
    }

    if (campaign.ctaType == 'external' &&
        campaign.ctaUrl.trim().isNotEmpty) {
      final opened = await openExternalShareUrl(campaign.ctaUrl.trim());
      if (!opened && context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Could not open this link.')),
        );
      }
      return;
    }

    if (context.mounted) {
      await showHpjMobileAccountPortalSheet(
        context,
        currentPortal: 'farmer',
      );
    }
  }

