Future<bool> _showFarmerRepostProduceSheet(
  BuildContext context,
  FarmerSupplyForecast supply,
) async {
  double bestQuantity() {
    final values = <double>[
      supply.harvestedQuantity ?? 0,
      supply.expectedQuantity ?? 0,
      supply.quantityGrowing ?? 0,
    ];

    var best = 0.0;
    for (final value in values) {
      if (value.isFinite && value > best) {
        best = value;
      }
    }
    return best;
  }

  final originalQuantity = bestQuantity();
  final quantityController = TextEditingController(
    text: originalQuantity > 0
        ? _farmerPartnerNumber(originalQuantity)
        : '',
  );

  final now = DateTime.now();
  final today = DateTime(now.year, now.month, now.day);

  var readyDate = supply.expectedHarvestDate;
  if (readyDate == null ||
      DateTime(
        readyDate.year,
        readyDate.month,
        readyDate.day,
      ).isBefore(today)) {
    readyDate = today.add(const Duration(days: 7));
  }

  String dateLabel(DateTime value) {
    const months = <String>[
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];

    return '${value.day} ${months[value.month - 1]} ${value.year}';
  }

  try {
    final result = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        var saving = false;

        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            Future<void> pickDate() async {
              final picked = await showDatePicker(
                context: sheetContext,
                initialDate: readyDate!,
                firstDate: today,
                lastDate: today.add(const Duration(days: 730)),
              );

              if (picked != null) {
                setSheetState(() => readyDate = picked);
              }
            }

            Future<void> repost() async {
              final quantity = double.tryParse(
                quantityController.text
                    .trim()
                    .replaceAll(',', ''),
              );

              if (quantity == null ||
                  quantity <= 0 ||
                  quantity.isNaN ||
                  quantity.isInfinite) {
                ScaffoldMessenger.of(sheetContext).showSnackBar(
                  const SnackBar(
                    content: Text(
                      'Enter the quantity available.',
                    ),
                  ),
                );
                return;
              }

              setSheetState(() => saving = true);

              try {
                final selectedDate = readyDate!;
                final cleanDate = DateTime(
                  selectedDate.year,
                  selectedDate.month,
                  selectedDate.day,
                );

                await createFarmerSupplyForecast(
                  cropName: supply.cropName,
                  category: supply.category,
                  quantityGrowing: quantity,
                  expectedQuantity: quantity,
                  unit: supply.unit.trim().isEmpty
                      ? 'each'
                      : supply.unit.trim(),
                  expectedHarvestDate: selectedDate,
                  status: cleanDate.isAfter(today)
                      ? 'growing'
                      : 'harvest_ready',
                  notes: supply.notes,
                );

                if (!sheetContext.mounted) return;
                Navigator.of(sheetContext).pop(true);
              } catch (error) {
                if (!sheetContext.mounted) return;

                setSheetState(() => saving = false);
                ScaffoldMessenger.of(sheetContext).showSnackBar(
                  SnackBar(
                    content: Text(
                      friendlyAppError(error),
                    ),
                  ),
                );
              }
            }

            return SafeArea(
              top: false,
              child: Padding(
                padding: EdgeInsets.only(
                  bottom:
                      MediaQuery.of(sheetContext).viewInsets.bottom,
                ),
                child: Container(
                  decoration: const BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.vertical(
                      top: Radius.circular(26),
                    ),
                  ),
                  child: SingleChildScrollView(
                    padding: const EdgeInsets.fromLTRB(
                      18,
                      12,
                      18,
                      22,
                    ),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      crossAxisAlignment:
                          CrossAxisAlignment.start,
                      children: [
                        Center(
                          child: Container(
                            width: 42,
                            height: 4,
                            decoration: BoxDecoration(
                              color: const Color(0xFFD8DDD5),
                              borderRadius:
                                  BorderRadius.circular(99),
                            ),
                          ),
                        ),
                        const SizedBox(height: 15),

                        Row(
                          children: [
                            HpjProductThumb(
                              productName: supply.cropName,
                              size: 70,
                              radius: 16,
                            ),
                            const SizedBox(width: 12),
                            Expanded(
                              child: Column(
                                crossAxisAlignment:
                                    CrossAxisAlignment.start,
                                children: [
                                  const Text(
                                    'POST AGAIN',
                                    style: TextStyle(
                                      color: FarmColors.primary,
                                      fontSize: 8.5,
                                      fontWeight:
                                          FontWeight.w900,
                                      letterSpacing: 1,
                                    ),
                                  ),
                                  const SizedBox(height: 4),
                                  Text(
                                    supply.cropName,
                                    maxLines: 1,
                                    overflow:
                                        TextOverflow.ellipsis,
                                    style: const TextStyle(
                                      color: FarmColors.ink,
                                      fontSize: 19,
                                      fontWeight:
                                          FontWeight.w900,
                                    ),
                                  ),
                                  const SizedBox(height: 3),
                                  const Text(
                                    'Reuse this produce post. Change only what is different.',
                                    style: TextStyle(
                                      color:
                                          FarmColors.mutedText,
                                      fontSize: 9.2,
                                      height: 1.3,
                                      fontWeight:
                                          FontWeight.w600,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ],
                        ),

                        const SizedBox(height: 16),

                        TextField(
                          controller: quantityController,
                          keyboardType:
                              const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          decoration: InputDecoration(
                            labelText: 'Quantity available',
                            prefixIcon: const Icon(
                              Icons.inventory_2_outlined,
                            ),
                            suffixText:
                                supply.unit.trim().isEmpty
                                    ? 'each'
                                    : supply.unit.trim(),
                          ),
                        ),

                        const SizedBox(height: 11),

                        Material(
                          color: const Color(0xFFF7FAF6),
                          borderRadius:
                              BorderRadius.circular(15),
                          child: InkWell(
                            onTap: saving ? null : pickDate,
                            borderRadius:
                                BorderRadius.circular(15),
                            child: Padding(
                              padding:
                                  const EdgeInsets.symmetric(
                                horizontal: 13,
                                vertical: 12,
                              ),
                              child: Row(
                                children: [
                                  const Icon(
                                    Icons
                                        .calendar_month_outlined,
                                    color: FarmColors.primary,
                                    size: 20,
                                  ),
                                  const SizedBox(width: 10),
                                  const Expanded(
                                    child: Text(
                                      'Ready date',
                                      style: TextStyle(
                                        color: FarmColors
                                            .mutedText,
                                        fontSize: 9.5,
                                        fontWeight:
                                            FontWeight.w700,
                                      ),
                                    ),
                                  ),
                                  Text(
                                    dateLabel(readyDate!),
                                    style: const TextStyle(
                                      color: FarmColors.ink,
                                      fontSize: 10.5,
                                      fontWeight:
                                          FontWeight.w900,
                                    ),
                                  ),
                                  const SizedBox(width: 3),
                                  const Icon(
                                    Icons.chevron_right_rounded,
                                    size: 18,
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ),

                        const SizedBox(height: 12),

                        Container(
                          width: double.infinity,
                          padding: const EdgeInsets.all(11),
                          decoration: BoxDecoration(
                            color: const Color(0xFFF3F8F1),
                            borderRadius:
                                BorderRadius.circular(14),
                          ),
                          child: const Row(
                            crossAxisAlignment:
                                CrossAxisAlignment.start,
                            children: [
                              Icon(
                                Icons.repeat_rounded,
                                color: FarmColors.primary,
                                size: 18,
                              ),
                              SizedBox(width: 8),
                              Expanded(
                                child: Text(
                                  'Crop name, category, unit and notes are reused automatically. The old post stays in history.',
                                  style: TextStyle(
                                    color:
                                        FarmColors.mutedText,
                                    fontSize: 8.8,
                                    height: 1.35,
                                    fontWeight:
                                        FontWeight.w600,
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ),

                        const SizedBox(height: 15),

                        SizedBox(
                          width: double.infinity,
                          height: 48,
                          child: FilledButton.icon(
                            onPressed:
                                saving ? null : repost,
                            icon: saving
                                ? const SizedBox(
                                    width: 17,
                                    height: 17,
                                    child:
                                        CircularProgressIndicator(
                                      strokeWidth: 2,
                                      color: Colors.white,
                                    ),
                                  )
                                : const Icon(
                                    Icons.repeat_rounded,
                                  ),
                            label: Text(
                              saving
                                  ? 'Posting...'
                                  : 'Post again',
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            );
          },
        );
      },
    );

    return result == true;
  } finally {
    quantityController.dispose();
  }
}


class _HpjFarmerReferenceCropsPage extends StatefulWidget {
  final FarmerProfile profile;
  final List<FarmerSupplyForecast> supplies;
  final List<FarmerSupplyForecast> active;
  final List<FarmerSupplyForecast> needsUpdate;
  final VoidCallback onAdd;
  final VoidCallback onCalendar;
  final VoidCallback onChanged;
  final Future<void> Function(FarmerSupplyForecast) onOpenSupply;

  const _HpjFarmerReferenceCropsPage({
    required this.profile,
    required this.supplies,
    required this.active,
    required this.needsUpdate,
    required this.onAdd,
    required this.onCalendar,
    required this.onChanged,
    required this.onOpenSupply,
  });

  @override
  State<_HpjFarmerReferenceCropsPage> createState() =>
      _HpjFarmerReferenceCropsPageState();
}

class _HpjFarmerReferenceCropsPageState
    extends State<_HpjFarmerReferenceCropsPage> {
  String _query = '';
  String _filter = 'All';

  Future<void> _confirmStillAvailable(
    FarmerSupplyForecast item,
  ) async {
    try {
      // Refresh availability without resubmitting the current status.
      // HPJ-confirmed supply uses an admin-only status, so sending it back from
      // a farmer action causes the secure update RPC to reject the request.
      await updateFarmerSupplyForecast(
        forecastId: item.id,
        cropName: item.cropName,
        quantityGrowing: item.quantityGrowing,
        expectedQuantity: item.expectedQuantity,
        harvestedQuantity: item.harvestedQuantity,
      );

      widget.onChanged();

      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${item.cropName} confirmed as still available.',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(friendlyAppError(error)),
        ),
      );
    }
  }

  double _qty(FarmerSupplyForecast s) {
    final values = <double>[
      s.harvestedQuantity ?? 0,
      s.expectedQuantity ?? 0,
      s.quantityGrowing ?? 0,
    ];
    return values.fold<double>(0, (a, b) => b > a ? b : a);
  }

  bool _itemMatchesFilter(FarmerSupplyForecast item) {
    final review = _farmerSupplyNeedsReview(item);
    if (_filter == 'Live') return item.isHpjConfirmed && !review;
    if (_filter == 'Coming Soon') {
      return !item.isHpjConfirmed && !review;
    }
    if (_filter == 'Needs Review') return review;
    return true;
  }

  bool _groupMatchesFilter(List<FarmerSupplyForecast> rows) {
    if (_filter == 'All') return true;
    return rows.any(_itemMatchesFilter);
  }

  FarmerSupplyForecast _representative(
    List<FarmerSupplyForecast> rows,
  ) {
    if (rows.length == 1) return rows.first;

    final sorted = rows.toList(growable: false)
      ..sort((a, b) {
        int rank(FarmerSupplyForecast item) {
          if (_farmerSupplyNeedsReview(item)) return 3;
          if (item.isHpjConfirmed) return 2;
          return 1;
        }

        final byStatus = rank(b).compareTo(rank(a));
        if (byStatus != 0) return byStatus;

        final aDate = a.updatedAt ?? a.createdAt ?? DateTime(2000);
        final bDate = b.updatedAt ?? b.createdAt ?? DateTime(2000);
        return bDate.compareTo(aDate);
      });

    return sorted.first;
  }

  String _groupQuantityText(List<FarmerSupplyForecast> rows) {
    if (rows.isEmpty) return '';

    final unitKeys = rows
        .map((item) => item.unit.trim().toLowerCase())
        .where((value) => value.isNotEmpty)
        .toSet();

    if (unitKeys.length == 1) {
      final total = rows.fold<double>(0, (sum, item) => sum + _qty(item));
      final unit = rows.first.unit.trim().isEmpty ? 'unit' : rows.first.unit;
      return '${_farmerPartnerNumber(total)} $unit available';
    }

    return '${rows.length} listings • mixed units';
  }

  ({String label, Color color}) _groupStatus(
    List<FarmerSupplyForecast> rows,
  ) {
    final reviewCount = rows.where(_farmerSupplyNeedsReview).length;
    final liveCount = rows
        .where(
          (item) => item.isHpjConfirmed && !_farmerSupplyNeedsReview(item),
        )
        .length;
    final comingCount = rows.length - reviewCount - liveCount;

    if (reviewCount > 0) {
      return (
        label: reviewCount == 1 ? 'Needs Review' : '$reviewCount Need Review',
        color: const Color(0xFFD9384E),
      );
    }
    if (liveCount > 0) {
      return (
        label: liveCount == rows.length ? 'Live' : '$liveCount Live',
        color: const Color(0xFF1AA33A),
      );
    }
    return (
      label: comingCount <= 1 ? 'Coming Soon' : '$comingCount Coming Soon',
      color: const Color(0xFFE29811),
    );
  }

  Future<void> _openCropListings(
    String cropName,
    List<FarmerSupplyForecast> sourceRows,
  ) async {
    if (sourceRows.isEmpty) return;

    if (sourceRows.length == 1) {
      await widget.onOpenSupply(sourceRows.first);
      return;
    }

    final rows = sourceRows.toList(growable: false)
      ..sort((a, b) {
        final aDate = a.updatedAt ?? a.createdAt ?? DateTime(2000);
        final bDate = b.updatedAt ?? b.createdAt ?? DateTime(2000);
        return bDate.compareTo(aDate);
      });

    if (!mounted) return;

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return DraggableScrollableSheet(
          initialChildSize: .72,
          minChildSize: .48,
          maxChildSize: .92,
          expand: false,
          builder: (context, controller) {
            final summary = _groupStatus(rows);
            return Container(
              decoration: const BoxDecoration(
                color: Color(0xFFF8FAF6),
                borderRadius: BorderRadius.vertical(
                  top: Radius.circular(26),
                ),
              ),
              child: ListView(
                controller: controller,
                padding: const EdgeInsets.fromLTRB(14, 10, 14, 30),
                children: [
                  Center(
                    child: Container(
                      width: 42,
                      height: 4,
                      decoration: BoxDecoration(
                        color: const Color(0xFFD2D9CF),
                        borderRadius: BorderRadius.circular(999),
                      ),
                    ),
                  ),
                  const SizedBox(height: 14),
                  Row(
                    children: [
                      HpjProductThumb(
                        productName: cropName,
                        size: 76,
                        radius: 16,
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              cropName,
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontSize: 20,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 3),
                            Text(
                              '${rows.length} listings • ${_groupQuantityText(rows)}',
                              style: const TextStyle(
                                color: FarmColors.mutedText,
                                fontSize: 10,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                            const SizedBox(height: 7),
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 9,
                                vertical: 5,
                              ),
                              decoration: BoxDecoration(
                                color: summary.color.withOpacity(.10),
                                borderRadius: BorderRadius.circular(999),
                              ),
                              child: Text(
                                summary.label,
                                style: TextStyle(
                                  color: summary.color,
                                  fontSize: 8.5,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 16),
                  const Text(
                    'Choose a listing',
                    style: TextStyle(
                      color: FarmColors.ink,
                      fontSize: 14,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 5),
                  const Text(
                    'Edit, confirm or repost the exact listing you want to manage.',
                    style: TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 9.5,
                      height: 1.3,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  const SizedBox(height: 10),
                  ...rows.map((item) {
                    final review = _farmerSupplyNeedsReview(item);
                    final live = item.isHpjConfirmed && !review;
                    final status = review
                        ? 'Needs Review'
                        : live
                            ? 'Live'
                            : 'Coming Soon';
                    final color = review
                        ? const Color(0xFFD9384E)
                        : live
                            ? const Color(0xFF1AA33A)
                            : const Color(0xFFE29811);

                    return Padding(
                      padding: const EdgeInsets.only(bottom: 8),
                      child: Material(
                        color: Colors.white,
                        borderRadius: BorderRadius.circular(15),
                        child: InkWell(
                          borderRadius: BorderRadius.circular(15),
                          onTap: () async {
                            Navigator.of(sheetContext).pop();
                            await widget.onOpenSupply(item);
                          },
                          child: Container(
                            padding: const EdgeInsets.all(10),
                            decoration: BoxDecoration(
                              borderRadius: BorderRadius.circular(15),
                              border: Border.all(
                                color: const Color(0xFFE1E8DE),
                              ),
                            ),
                            child: Row(
                              children: [
                                HpjProductThumb(
                                  productName: item.cropName,
                                  size: 52,
                                  radius: 11,
                                ),
                                const SizedBox(width: 10),
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        '${_farmerPartnerNumber(_qty(item))} ${item.unit}',
                                        style: const TextStyle(
                                          color: FarmColors.ink,
                                          fontSize: 11.5,
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                      const SizedBox(height: 4),
                                      Text(
                                        status,
                                        style: TextStyle(
                                          color: color,
                                          fontSize: 8.5,
                                          fontWeight: FontWeight.w800,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                                if (review)
                                  IconButton(
                                    tooltip: 'Still available',
                                    visualDensity: VisualDensity.compact,
                                    onPressed: () async {
                                      await _confirmStillAvailable(item);
                                      if (sheetContext.mounted) {
                                        Navigator.of(sheetContext).pop();
                                      }
                                    },
                                    icon: const Icon(
                                      Icons.check_circle_outline_rounded,
                                      color: FarmColors.primary,
                                    ),
                                  ),
                                IconButton(
                                  tooltip: 'Post again',
                                  visualDensity: VisualDensity.compact,
                                  onPressed: () async {
                                    final posted =
                                        await _showFarmerRepostProduceSheet(
                                      context,
                                      item,
                                    );
                                    if (posted == true) {
                                      widget.onChanged();
                                      if (sheetContext.mounted) {
                                        Navigator.of(sheetContext).pop();
                                      }
                                    }
                                  },
                                  icon: const Icon(
                                    Icons.repeat_rounded,
                                    color: FarmColors.primary,
                                  ),
                                ),
                                const Icon(
                                  Icons.chevron_right_rounded,
                                  color: FarmColors.deepGreen,
                                ),
                              ],
                            ),
                          ),
                        ),
                      ),
                    );
                  }),
                ],
              ),
            );
          },
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final normalized = _query.trim().toLowerCase();

    final grouped = <String, List<FarmerSupplyForecast>>{};
    final cropNames = <String, String>{};

    for (final item in widget.active) {
      final cropName = item.cropName.trim();
      if (cropName.isEmpty) continue;
      final key = hpjSmartNormalizeSearch(cropName);
      if (key.isEmpty) continue;
      grouped.putIfAbsent(key, () => <FarmerSupplyForecast>[]).add(item);
      cropNames.putIfAbsent(key, () => cropName);
    }

    final current = grouped.entries.where((entry) {
      final rows = entry.value;
      final cropName = cropNames[entry.key] ?? rows.first.cropName;
      final matchesSearch = normalized.isEmpty ||
          cropName.toLowerCase().contains(normalized) ||
          rows.any((item) => item.unit.toLowerCase().contains(normalized));
      return matchesSearch && _groupMatchesFilter(rows);
    }).toList(growable: false)
      ..sort((a, b) {
        final aName = cropNames[a.key] ?? a.value.first.cropName;
        final bName = cropNames[b.key] ?? b.value.first.cropName;
        return aName.toLowerCase().compareTo(bName.toLowerCase());
      });

    return ListView(
      physics: const AlwaysScrollableScrollPhysics(),
      padding: const EdgeInsets.fromLTRB(12, 10, 12, 118),
      children: [
        Row(
          children: [
            const Expanded(
              child: Text(
                'My Crops',
                style: TextStyle(
                  color: FarmColors.ink,
                  fontSize: 25,
                  fontWeight: FontWeight.w900,
                  letterSpacing: -.5,
                ),
              ),
            ),
            IconButton(
              tooltip: 'Farm Calendar',
              onPressed: widget.onCalendar,
              icon: const Icon(Icons.calendar_month_rounded),
            ),
            FilledButton(
              onPressed: widget.onAdd,
              style: FilledButton.styleFrom(
                shape: const CircleBorder(),
                padding: const EdgeInsets.all(12),
              ),
              child: const Icon(Icons.add_rounded),
            ),
          ],
        ),
        const SizedBox(height: 12),
        Container(
          padding: const EdgeInsets.fromLTRB(9, 9, 9, 8),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(20),
            border: Border.all(color: const Color(0xFFDDE6DA)),
          ),
          child: Column(
            children: [
              TextField(
                onChanged: (value) => setState(() => _query = value),
                textInputAction: TextInputAction.search,
                decoration: InputDecoration(
                  hintText: 'Search crops',
                  prefixIcon: const Icon(Icons.search_rounded),
                  suffixIcon: _query.isEmpty
                      ? null
                      : IconButton(
                          tooltip: 'Clear search',
                          onPressed: () => setState(() => _query = ''),
                          icon: const Icon(Icons.close_rounded),
                        ),
                  filled: true,
                  fillColor: const Color(0xFFF8FAF6),
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(15),
                    borderSide: BorderSide.none,
                  ),
                  enabledBorder: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(15),
                    borderSide: const BorderSide(
                      color: Color(0xFFDCE6D9),
                    ),
                  ),
                  contentPadding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 11,
                  ),
                ),
              ),
              const SizedBox(height: 8),
              SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: Row(
                  children: [
                    for (final label in const <String>[
                      'All',
                      'Live',
                      'Coming Soon',
                      'Needs Review',
                    ])
                      Padding(
                        padding: const EdgeInsets.only(right: 7),
                        child: ChoiceChip(
                          label: Text(label),
                          selected: _filter == label,
                          onSelected: (_) => setState(() => _filter = label),
                          selectedColor: const Color(0xFFE3F2E1),
                          backgroundColor: const Color(0xFFF7FAF5),
                          side: const BorderSide(
                            color: Color(0xFFD8E4D5),
                          ),
