class _HpjFarmReminder {
  final int notificationId;
  final String title;
  final DateTime eventAt;
  final DateTime notifyAt;
  final int remindBeforeMinutes;
  final String? cropName;

  const _HpjFarmReminder({
    required this.notificationId,
    required this.title,
    required this.eventAt,
    required this.notifyAt,
    required this.remindBeforeMinutes,
    this.cropName,
  });

  Map<String, dynamic> toJson() => <String, dynamic>{
        'notification_id': notificationId,
        'title': title,
        'event_at': eventAt.toIso8601String(),
        'notify_at': notifyAt.toIso8601String(),
        'remind_before_minutes': remindBeforeMinutes,
        'crop_name': cropName,
      };

  factory _HpjFarmReminder.fromJson(Map<String, dynamic> json) {
    return _HpjFarmReminder(
      notificationId:
          (json['notification_id'] as num?)?.toInt() ?? 0,
      title: (json['title'] ?? '').toString().trim(),
      eventAt:
          DateTime.tryParse((json['event_at'] ?? '').toString()) ??
              DateTime.now(),
      notifyAt:
          DateTime.tryParse((json['notify_at'] ?? '').toString()) ??
              DateTime.now(),
      remindBeforeMinutes:
          (json['remind_before_minutes'] as num?)?.toInt() ?? 0,
      cropName: (json['crop_name'] ?? '').toString().trim().isEmpty
          ? null
          : (json['crop_name'] ?? '').toString().trim(),
    );
  }
}


class _HpjFarmerCalendarMvpPage extends StatefulWidget {
  final FarmerProfile profile;
  final List<FarmerSupplyForecast> supplies;
  final Future<void> Function(FarmerSupplyForecast) onOpenSupply;

  const _HpjFarmerCalendarMvpPage({
    required this.profile,
    required this.supplies,
    required this.onOpenSupply,
  });

  @override
  State<_HpjFarmerCalendarMvpPage> createState() =>
      _HpjFarmerCalendarMvpPageState();
}


class _HpjFarmerCalendarMvpPageState
    extends State<_HpjFarmerCalendarMvpPage> {
  late DateTime month;
  DateTime? selectedDate;

  List<_HpjFarmReminder> _reminders =
      const <_HpjFarmReminder>[];
  bool _loadingReminders = true;

  String get _reminderStorageKey =>
      'hpj_farmer_calendar_reminders_${widget.profile.id}';

  @override
  void initState() {
    super.initState();

    final dated = widget.supplies
        .where(
          (item) =>
              item.expectedHarvestDate != null && item.isActive,
        )
        .toList()
      ..sort(
        (a, b) => a.expectedHarvestDate!
            .compareTo(b.expectedHarvestDate!),
      );

    final now = DateTime.now();
    month = DateTime(now.year, now.month);

    if (dated.isNotEmpty) {
      final todayEvents = dated.where(
        (item) => _sameDay(item.expectedHarvestDate!, now),
      );

      if (todayEvents.isNotEmpty) {
        selectedDate = DateTime(
          now.year,
          now.month,
          now.day,
        );
      } else {
        final firstDate = dated.first.expectedHarvestDate!;
        month = DateTime(
          firstDate.year,
          firstDate.month,
        );
        selectedDate = DateTime(
          firstDate.year,
          firstDate.month,
          firstDate.day,
        );
      }
    }

    unawaited(_loadReminders());
  }

  Future<void> _loadReminders() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_reminderStorageKey);

      if (raw == null || raw.trim().isEmpty) {
        if (mounted) {
          setState(() {
            _reminders = const <_HpjFarmReminder>[];
            _loadingReminders = false;
          });
        }
        return;
      }

      final decoded = jsonDecode(raw);
      if (decoded is! List) {
        throw const FormatException('Invalid reminder list');
      }

      final loaded = decoded
          .whereType<Map>()
          .map(
            (row) => _HpjFarmReminder.fromJson(
              Map<String, dynamic>.from(row),
            ),
          )
          .where((item) => item.title.isNotEmpty)
          .toList()
        ..sort((a, b) => a.eventAt.compareTo(b.eventAt));

      if (!mounted) return;

      setState(() {
        _reminders = loaded;
        _loadingReminders = false;
      });
    } catch (_) {
      if (!mounted) return;

      setState(() {
        _reminders = const <_HpjFarmReminder>[];
        _loadingReminders = false;
      });
    }
  }

  Future<void> _saveReminders(
    List<_HpjFarmReminder> items,
  ) async {
    final sorted = [...items]
      ..sort((a, b) => a.eventAt.compareTo(b.eventAt));

    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(
      _reminderStorageKey,
      jsonEncode(
        sorted.map((item) => item.toJson()).toList(),
      ),
    );

    if (!mounted) return;
    setState(() => _reminders = sorted);
  }

  bool _sameDay(DateTime a, DateTime b) {
    final left = a.toLocal();
    final right = b.toLocal();

    return left.year == right.year &&
        left.month == right.month &&
        left.day == right.day;
  }

  String _monthTitle(DateTime value) {
    const months = <String>[
      'January',
      'February',
      'March',
      'April',
      'May',
      'June',
      'July',
      'August',
      'September',
      'October',
      'November',
      'December',
    ];

    return '${months[value.month - 1]} ${value.year}';
  }

  String _shortDate(DateTime value) {
    const months = <String>[
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];

    final local = value.toLocal();
    return '${months[local.month - 1]} ${local.day}, ${local.year}';
  }

  String _selectedDateTitle(DateTime value) {
    const months = <String>[
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];

    return '${months[value.month - 1]} ${value.day}';
  }

  String _timeLabel(DateTime value) {
    final hour = value.hour % 12 == 0 ? 12 : value.hour % 12;
    final minute = value.minute.toString().padLeft(2, '0');
    final period = value.hour >= 12 ? 'PM' : 'AM';
    return '$hour:$minute $period';
  }

  String _remindBeforeLabel(int minutes) {
    switch (minutes) {
      case 1440:
        return '1 day before';
      case 4320:
        return '3 days before';
      case 10080:
        return '1 week before';
      default:
        return 'At the time';
    }
  }

  void _changeMonth(int offset) {
    setState(() {
      month = DateTime(
        month.year,
        month.month + offset,
      );
      selectedDate = null;
    });
  }

  void _goToToday() {
    final now = DateTime.now();

    setState(() {
      month = DateTime(now.year, now.month);
      selectedDate = DateTime(
        now.year,
        now.month,
        now.day,
      );
    });
  }

  List<FarmerSupplyForecast> _eventsForDate(
    List<FarmerSupplyForecast> dated,
    DateTime? date,
  ) {
    if (date == null) {
      return dated
          .where((item) {
            final value = item.expectedHarvestDate!;
            return value.year == month.year &&
                value.month == month.month;
          })
          .toList(growable: false);
    }

    return dated
        .where(
          (item) =>
              _sameDay(item.expectedHarvestDate!, date),
        )
        .toList(growable: false);
  }

  List<_HpjFarmReminder> _remindersForDate(
    DateTime? date,
  ) {
    if (date == null) {
      return _reminders
          .where(
            (item) =>
                item.eventAt.year == month.year &&
                item.eventAt.month == month.month,
          )
          .toList(growable: false);
    }

    return _reminders
        .where(
          (item) => _sameDay(item.eventAt, date),
        )
        .toList(growable: false);
  }

  int _reminderCountForDay(int day) {
    return _reminders.where((item) {
      final d = item.eventAt;
      return d.year == month.year &&
          d.month == month.month &&
          d.day == day;
    }).length;
  }

  Future<void> _deleteReminder(
    _HpjFarmReminder reminder,
  ) async {
    await FarmReminderService.cancel(
      reminder.notificationId,
    );

    await _saveReminders(
      _reminders
          .where(
            (item) =>
                item.notificationId !=
                reminder.notificationId,
          )
          .toList(),
    );
  }

  Future<void> _openReminderEditor({
    _HpjFarmReminder? existing,
    DateTime? initialDate,
    String? initialTitle,
    String? cropName,
  }) async {
    final now = DateTime.now();
    final startingDate =
        existing?.eventAt ?? initialDate ?? selectedDate ?? now;

    final titleController = TextEditingController(
      text: existing?.title ??
          initialTitle ??
          (cropName == null
              ? 'Farm reminder'
              : 'Harvest $cropName'),
    );

    var eventDate = DateTime(
      startingDate.year,
      startingDate.month,
      startingDate.day,
    );

    var eventTime = TimeOfDay(
      hour: existing?.eventAt.hour ??
          (startingDate.hour == 0 ? 7 : startingDate.hour),
      minute: existing?.eventAt.minute ?? 0,
    );

    var remindBeforeMinutes =
        existing?.remindBeforeMinutes ?? 1440;
    var saving = false;

    try {
      final result = await showModalBottomSheet<String>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        builder: (sheetContext) {
          return StatefulBuilder(
            builder: (sheetContext, setSheetState) {
              Future<void> pickDate() async {
                final picked = await showDatePicker(
                  context: sheetContext,
                  initialDate: eventDate.isBefore(
                    DateTime(
                      now.year,
                      now.month,
                      now.day,
                    ),
                  )
                      ? DateTime(
                          now.year,
                          now.month,
                          now.day,
                        )
                      : eventDate,
                  firstDate: DateTime(
                    now.year,
                    now.month,
                    now.day,
                  ),
                  lastDate: now.add(
                    const Duration(days: 730),
                  ),
                );

                if (picked != null) {
                  setSheetState(() => eventDate = picked);
                }
              }

              Future<void> pickTime() async {
                final picked = await showTimePicker(
                  context: sheetContext,
                  initialTime: eventTime,
                );

                if (picked != null) {
                  setSheetState(() => eventTime = picked);
                }
              }

              Future<void> save() async {
                final title = titleController.text.trim();

                if (title.isEmpty) {
                  ScaffoldMessenger.of(sheetContext)
                      .showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Add a reminder title.',
                      ),
                    ),
                  );
                  return;
                }

                final eventAt = DateTime(
                  eventDate.year,
                  eventDate.month,
                  eventDate.day,
                  eventTime.hour,
                  eventTime.minute,
                );

                final notifyAt = eventAt.subtract(
                  Duration(
                    minutes: remindBeforeMinutes,
                  ),
                );

                if (!notifyAt.isAfter(DateTime.now())) {
                  ScaffoldMessenger.of(sheetContext)
                      .showSnackBar(
                    const SnackBar(
                      content: Text(
                        'Choose a reminder time that is still in the future.',
                      ),
                    ),
                  );
                  return;
                }

                setSheetState(() => saving = true);

                final id = existing?.notificationId ??
                    DateTime.now()
                        .microsecondsSinceEpoch
                        .remainder(2147483647);

                if (existing != null) {
                  await FarmReminderService.cancel(id);
                }

                final phoneScheduled =
                    await FarmReminderService.schedule(
                  id: id,
                  title: title,
                  body: cropName == null &&
                          existing?.cropName == null
                      ? 'Farm reminder from The Harvest Place Ja'
                      : 'Farm reminder for ${cropName ?? existing?.cropName}',
                  scheduledAt: notifyAt,
                );

                final updated = _HpjFarmReminder(
                  notificationId: id,
                  title: title,
                  eventAt: eventAt,
                  notifyAt: notifyAt,
                  remindBeforeMinutes:
                      remindBeforeMinutes,
                  cropName:
                      cropName ?? existing?.cropName,
                );

                final next = _reminders
                    .where(
                      (item) =>
                          item.notificationId != id,
                    )
                    .toList()
                  ..add(updated);

                await _saveReminders(next);

                if (!sheetContext.mounted) return;

                Navigator.of(sheetContext).pop(
                  phoneScheduled
                      ? 'saved-phone'
                      : 'saved-app',
                );
              }

              return SafeArea(
                top: false,
                child: Padding(
                  padding: EdgeInsets.only(
                    bottom: MediaQuery.of(sheetContext)
                        .viewInsets
                        .bottom,
                  ),
                  child: Container(
                    decoration: const BoxDecoration(
                      color: Colors.white,
                      borderRadius:
                          BorderRadius.vertical(
                        top: Radius.circular(26),
                      ),
                    ),
                    child: SingleChildScrollView(
                      padding:
                          const EdgeInsets.fromLTRB(
                        18,
                        12,
                        18,
                        22,
                      ),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment:
                            CrossAxisAlignment.start,
                        children: [
                          Center(
                            child: Container(
                              width: 42,
                              height: 4,
                              decoration: BoxDecoration(
                                color: const Color(
                                  0xFFD8DDD5,
                                ),
                                borderRadius:
                                    BorderRadius.circular(
                                  99,
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(height: 15),

                          Row(
                            children: [
                              const CircleAvatar(
                                radius: 23,
                                backgroundColor:
                                    Color(0xFFFFF3DC),
                                child: Icon(
                                  Icons
                                      .notifications_active_outlined,
                                  color:
                                      Color(0xFFA46B00),
                                ),
                              ),
                              const SizedBox(width: 11),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment:
                                      CrossAxisAlignment
                                          .start,
                                  children: [
                                    Text(
                                      existing == null
                                          ? 'Add Reminder'
                                          : 'Edit Reminder',
                                      style:
                                          const TextStyle(
                                        color:
                                            FarmColors.ink,
                                        fontSize: 18,
                                        fontWeight:
                                            FontWeight.w900,
                                      ),
                                    ),
                                    const SizedBox(
                                      height: 2,
                                    ),
                                    const Text(
                                      'Keep important farm dates on your radar.',
                                      style: TextStyle(
                                        color: FarmColors
                                            .mutedText,
                                        fontSize: 9.2,
                                        fontWeight:
                                            FontWeight.w600,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),

                          const SizedBox(height: 15),

                          TextField(
                            controller:
                                titleController,
                            textCapitalization:
                                TextCapitalization
                                    .sentences,
                            decoration:
                                const InputDecoration(
                              labelText:
                                  'Reminder title',
                              prefixIcon: Icon(
                                Icons.edit_note_rounded,
                              ),
                            ),
                          ),

                          const SizedBox(height: 10),

                          Row(
                            children: [
                              Expanded(
                                child: OutlinedButton
                                    .icon(
                                  onPressed:
                                      saving
                                          ? null
                                          : pickDate,
                                  icon: const Icon(
                                    Icons
                                        .calendar_month_outlined,
                                  ),
                                  label: Text(
                                    _shortDate(
                                      eventDate,
                                    ),
                                  ),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: OutlinedButton
                                    .icon(
                                  onPressed:
                                      saving
                                          ? null
                                          : pickTime,
                                  icon: const Icon(
                                    Icons
                                        .schedule_outlined,
                                  ),
                                  label: Text(
                                    eventTime
                                        .format(
                                          sheetContext,
                                        ),
                                  ),
                                ),
                              ),
                            ],
                          ),

                          const SizedBox(height: 13),
                          const Text(
                            'Remind me',
                            style: TextStyle(
                              color: FarmColors.ink,
                              fontSize: 11,
                              fontWeight:
                                  FontWeight.w900,
                            ),
                          ),
                          const SizedBox(height: 7),

                          Wrap(
                            spacing: 7,
                            runSpacing: 7,
                            children: [
                              for (final option
                                  in const <int>[
                                0,
                                1440,
                                4320,
                                10080,
                              ])
                                ChoiceChip(
                                  label: Text(
                                    _remindBeforeLabel(
                                      option,
                                    ),
                                  ),
                                  selected:
                                      remindBeforeMinutes ==
                                          option,
                                  onSelected: saving
                                      ? null
                                      : (_) {
                                          setSheetState(
                                            () =>
                                                remindBeforeMinutes =
                                                    option,
                                          );
                                        },
                                ),
                            ],
                          ),

                          const SizedBox(height: 16),

                          Row(
                            children: [
                              if (existing != null) ...[
                                OutlinedButton.icon(
                                  onPressed: saving
                                      ? null
                                      : () =>
                                          Navigator.of(
                                            sheetContext,
                                          ).pop(
                                            'delete',
                                          ),
                                  icon: const Icon(
                                    Icons
                                        .delete_outline_rounded,
                                  ),
                                  label:
                                      const Text('Delete'),
                                  style:
                                      OutlinedButton.styleFrom(
                                    foregroundColor:
                                        Colors.red.shade700,
                                  ),
                                ),
                                const SizedBox(width: 8),
                              ],
                              Expanded(
                                child: SizedBox(
                                  height: 46,
                                  child:
                                      FilledButton.icon(
                                    onPressed: saving
                                        ? null
                                        : save,
                                    icon: saving
                                        ? const SizedBox(
                                            width: 16,
                                            height: 16,
                                            child:
                                                CircularProgressIndicator(
                                              strokeWidth:
                                                  2,
                                              color:
                                                  Colors
                                                      .white,
                                            ),
                                          )
                                        : const Icon(
                                            Icons
                                                .notifications_active_outlined,
                                          ),
                                    label: Text(
                                      saving
                                          ? 'Saving...'
                                          : 'Save reminder',
                                    ),
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              );
            },
          );
        },
      );

      if (result == 'delete' && existing != null) {
        await _deleteReminder(existing);

        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Reminder deleted.'),
          ),
        );
        return;
      }

      if (!mounted || result == null) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            result == 'saved-phone'
                ? 'Reminder saved. A phone notification is scheduled.'
                : 'Reminder saved in your Farm Calendar.',
          ),
        ),
      );
    } finally {
      titleController.dispose();
    }
  }

  Future<void> _openEventDetails(
    FarmerSupplyForecast supply,
  ) async {
    if (!mounted) return;

    final quantity = supply.expectedQuantity ??
        supply.quantityGrowing ??
        0;

    final action = await showModalBottomSheet<String>(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return Container(
          decoration: const BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.vertical(
              top: Radius.circular(26),
            ),
          ),
          child: SafeArea(
            top: false,
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(
                18,
                12,
                18,
                24,
              ),
              child: Column(
                crossAxisAlignment:
                    CrossAxisAlignment.start,
                children: [
                  Center(
                    child: Container(
                      width: 42,
                      height: 4,
                      decoration: BoxDecoration(
                        color: FarmColors.line,
                        borderRadius:
                            BorderRadius.circular(99),
                      ),
                    ),
                  ),
                  const SizedBox(height: 16),

                  Row(
                    children: [
                      HpjProductThumb(
                        productName: supply.cropName,
                        size: 72,
                        radius: 17,
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment:
                              CrossAxisAlignment.start,
                          children: [
                            Text(
                              supply.cropName,
                              maxLines: 2,
                              overflow:
                                  TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontSize: 20,
                                fontWeight:
                                    FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              _shortDate(
                                supply
                                    .expectedHarvestDate!,
                              ),
                              style: const TextStyle(
                                color:
                                    FarmColors.deepGreen,
                                fontSize: 10,
                                fontWeight:
                                    FontWeight.w800,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),

                  const SizedBox(height: 16),

                  Container(
                    padding: const EdgeInsets.all(13),
                    decoration: BoxDecoration(
                      color: const Color(0xFFF3F8F1),
                      borderRadius:
                          BorderRadius.circular(17),
                    ),
                    child: Column(
                      children: [
                        Row(
                          children: [
                            const Icon(
                              Icons
                                  .inventory_2_outlined,
                              color:
                                  FarmColors.primary,
                              size: 19,
                            ),
                            const SizedBox(width: 9),
                            const Expanded(
                              child: Text(
                                'Expected quantity',
                                style: TextStyle(
                                  color: FarmColors
                                      .mutedText,
                                  fontSize: 9.2,
                                  fontWeight:
                                      FontWeight.w700,
                                ),
                              ),
                            ),
                            Text(
                              '${_farmerPartnerNumber(quantity)} ${supply.unit}',
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontSize: 11.5,
                                fontWeight:
                                    FontWeight.w900,
                              ),
                            ),
                          ],
                        ),
                        const Divider(height: 20),
                        Row(
                          children: [
                            const Icon(
                              Icons.eco_outlined,
                              color:
                                  FarmColors.primary,
                              size: 19,
                            ),
                            const SizedBox(width: 9),
                            const Expanded(
                              child: Text(
                                'Status',
                                style: TextStyle(
                                  color: FarmColors
                                      .mutedText,
                                  fontSize: 9.2,
                                  fontWeight:
                                      FontWeight.w700,
                                ),
                              ),
                            ),
                            Text(
                              supply.statusLabel,
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontSize: 11,
                                fontWeight:
                                    FontWeight.w900,
                              ),
                            ),
                          ],
                        ),
                      ],
                    ),
                  ),

                  const SizedBox(height: 14),

                  Row(
                    children: [
                      Expanded(
                        child: OutlinedButton.icon(
                          onPressed: () =>
                              Navigator.of(
                                sheetContext,
                              ).pop('reminder'),
                          icon: const Icon(
                            Icons
                                .notifications_active_outlined,
                          ),
                          label: const Text(
                            'Remind me',
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: FilledButton.icon(
                          onPressed: () =>
                              Navigator.of(
                                sheetContext,
                              ).pop('edit'),
                          icon: const Icon(
                            Icons.edit_outlined,
                          ),
                          label: const Text(
                            'Edit crop',
                          ),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );

    if (!mounted) return;

    if (action == 'reminder') {
      await _openReminderEditor(
        initialDate: supply.expectedHarvestDate,
        initialTitle:
            'Harvest ${supply.cropName}',
        cropName: supply.cropName,
      );
      return;
    }

    if (action == 'edit') {
      await widget.onOpenSupply(supply);
      if (mounted) setState(() {});
    }
  }

  @override
  Widget build(BuildContext context) {
    final dated = widget.supplies
        .where(
          (s) =>
              s.expectedHarvestDate != null && s.isActive,
        )
        .toList()
      ..sort(
        (a, b) => a.expectedHarvestDate!
            .compareTo(b.expectedHarvestDate!),
      );

    final first = DateTime(
      month.year,
      month.month,
      1,
    );
    final leading = first.weekday % 7;
    final days = DateTime(
      month.year,
      month.month + 1,
      0,
    ).day;
    final cells = leading + days;
    final rows = ((cells + 6) / 7).floor();
    final totalCells = rows * 7;

    final visibleEvents =
        _eventsForDate(dated, selectedDate);
    final visibleReminders =
        _remindersForDate(selectedDate);

    int eventCountForDay(int day) {
      return dated.where((s) {
        final d = s.expectedHarvestDate!;
        return d.year == month.year &&
            d.month == month.month &&
            d.day == day;
      }).length;
    }

    return Scaffold(
      backgroundColor: const Color(0xFFF7F9F5),
      appBar: AppBar(
        backgroundColor:
            const Color(0xFFF7F9F5),
        surfaceTintColor: Colors.transparent,
        leading: IconButton(
          tooltip: 'Back',
          onPressed: () =>
              Navigator.of(context).maybePop(),
          icon: const Icon(
            Icons.arrow_back_rounded,
          ),
        ),
        title: const Text(
          'Farm Calendar',
          style: TextStyle(
            fontWeight: FontWeight.w900,
          ),
        ),
        actions: [
          IconButton(
            tooltip: 'Add reminder',
            onPressed: () => _openReminderEditor(
              initialDate: selectedDate,
            ),
            icon: const Icon(
              Icons
                  .add_alert_outlined,
              color: FarmColors.primary,
            ),
          ),
        ],
      ),
      body: RefreshIndicator(
        onRefresh: _loadReminders,
        child: ListView(
          physics:
              const AlwaysScrollableScrollPhysics(),
          padding:
              const EdgeInsets.fromLTRB(
            12,
            8,
            12,
            28,
          ),
          children: [
            Container(
              padding:
                  const EdgeInsets.symmetric(
                horizontal: 13,
                vertical: 12,
              ),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius:
                    BorderRadius.circular(18),
                border: Border.all(
                  color:
                      const Color(0xFFDDE6DA),
                ),
              ),
              child: Row(
                children: [
                  Container(
                    width: 42,
                    height: 42,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color:
                          const Color(0xFFEAF5E9),
                      borderRadius:
                          BorderRadius.circular(13),
                    ),
                    child: const Icon(
                      Icons.calendar_month_rounded,
                      color: FarmColors.primary,
                    ),
                  ),
                  const SizedBox(width: 11),
                  Expanded(
                    child: Column(
                      crossAxisAlignment:
                          CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'Farm Calendar',
                          style: TextStyle(
                            color: FarmColors.ink,
                            fontSize: 14,
                            fontWeight:
                                FontWeight.w900,
                          ),
                        ),
                        const SizedBox(height: 3),
                        Text(
                          '${dated.length} crop date${dated.length == 1 ? '' : 's'} • ${_reminders.length} reminder${_reminders.length == 1 ? '' : 's'}',
                          style: const TextStyle(
                            color: FarmColors
                                .mutedText,
                            fontSize: 9.2,
                            fontWeight:
                                FontWeight.w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                  TextButton(
                    onPressed: _goToToday,
                    child: const Text('Today'),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 12),

            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onHorizontalDragEnd: (details) {
                final velocity =
                    details.primaryVelocity ?? 0;

                if (velocity < -150) {
                  _changeMonth(1);
                } else if (velocity > 150) {
                  _changeMonth(-1);
                }
              },
              child: Container(
                padding: const EdgeInsets.fromLTRB(
                  10,
