                    ),

                    const SizedBox(height: 6),

                    Row(
                      mainAxisAlignment:
                          MainAxisAlignment.center,
                      children: [
                        Container(
                          width: 6,
                          height: 6,
                          decoration:
                              const BoxDecoration(
                            color:
                                Color(0xFF22B13C),
                            shape: BoxShape.circle,
                          ),
                        ),
                        const SizedBox(width: 4),
                        const Text(
                          'Crop date',
                          style: TextStyle(
                            color: FarmColors
                                .mutedText,
                            fontSize: 8.2,
                            fontWeight:
                                FontWeight.w600,
                          ),
                        ),
                        const SizedBox(width: 12),
                        Container(
                          width: 7,
                          height: 7,
                          decoration:
                              const BoxDecoration(
                            color:
                                Color(0xFFE6A300),
                            shape: BoxShape.circle,
                          ),
                        ),
                        const SizedBox(width: 4),
                        const Text(
                          'Reminder',
                          style: TextStyle(
                            color: FarmColors
                                .mutedText,
                            fontSize: 8.2,
                            fontWeight:
                                FontWeight.w600,
                          ),
                        ),
                      ],
                    ),

                    const SizedBox(height: 5),
                    const Text(
                      'Tap a date • Hold a date to add a reminder • Swipe months',
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        color:
                            FarmColors.mutedText,
                        fontSize: 8.2,
                        fontWeight:
                            FontWeight.w600,
                      ),
                    ),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 12),

            Container(
              padding: const EdgeInsets.fromLTRB(
                12,
                12,
                12,
                10,
              ),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius:
                    BorderRadius.circular(22),
                border: Border.all(
                  color:
                      const Color(0xFFDDE6DA),
                ),
              ),
              child: Column(
                crossAxisAlignment:
                    CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      const Icon(
                        Icons
                            .event_available_rounded,
                        color:
                            FarmColors.primary,
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          selectedDate == null
                              ? 'This month'
                              : _selectedDateTitle(
                                  selectedDate!,
                                ),
                          style:
                              const TextStyle(
                            color: FarmColors.ink,
                            fontSize: 17,
                            fontWeight:
                                FontWeight.w900,
                          ),
                        ),
                      ),
                      IconButton(
                        tooltip: 'Add reminder',
                        visualDensity:
                            VisualDensity.compact,
                        onPressed: () =>
                            _openReminderEditor(
                          initialDate:
                              selectedDate,
                        ),
                        icon: const Icon(
                          Icons
                              .add_alert_outlined,
                          color:
                              FarmColors.primary,
                          size: 20,
                        ),
                      ),
                    ],
                  ),

                  if (_loadingReminders)
                    const LinearProgressIndicator(
                      minHeight: 2,
                    ),

                  if (visibleEvents.isEmpty &&
                      visibleReminders.isEmpty)
                    Padding(
                      padding: const EdgeInsets
                          .symmetric(
                        vertical: 22,
                      ),
                      child: Center(
                        child: Column(
