class _HpjFarmerCropGuideData {
  final String plantingPeriod;
  final String harvest;
  final String sun;
  final String water;
  final String spacing;
  final String watchOuts;

  const _HpjFarmerCropGuideData({
    required this.plantingPeriod,
    required this.harvest,
    required this.sun,
    required this.water,
    required this.spacing,
    required this.watchOuts,
  });
}

_HpjFarmerCropGuideData _hpjFarmerCropGuideFor(String cropName) {
  final crop = hpjSmartNormalizeSearch(cropName);

  if (crop.contains('breadfruit')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Best established in the wetter months',
      harvest: 'Tree crop — first major harvest takes several years',
      sun: 'Full sun',
      water: 'Regular water while young; avoid waterlogging',
      spacing: 'Allow generous tree spacing',
      watchOuts: 'Fruit rot, mealybugs and overcrowded branches',
    );
  }

  if (crop.contains('ackee')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Plant at the start of a reliable rainy period',
      harvest: 'Tree crop — production increases as trees mature',
      sun: 'Full sun',
      water: 'Water young trees during dry spells',
      spacing: 'Allow room for a mature tree canopy',
      watchOuts: 'Fruit pests, branch damage and poor drainage',
    );
  }

  if (crop.contains('plantain') || crop.contains('banana')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Plant when dependable moisture is available',
      harvest: 'Often around 9–15 months depending on variety and conditions',
      sun: 'Full sun',
      water: 'Needs steady moisture',
      spacing: 'Give each stool enough room for light and airflow',
      watchOuts: 'Wind damage, leaf disease, weevils and poor drainage',
    );
  }

  if (crop.contains('tomato')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Best results usually come in the cooler, drier season',
      harvest: 'About 2–4 months after transplanting, depending on variety',
      sun: 'Full sun',
      water: 'Keep moisture even; avoid soaking leaves late in the day',
      spacing: 'Allow airflow between plants',
      watchOuts: 'Whiteflies, caterpillars, blight and fruit rot',
    );
  }

  if (crop.contains('pepper')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Can be grown year-round with good water management',
      harvest: 'Often begins a few months after transplanting',
      sun: 'Full sun',
      water: 'Even moisture; avoid prolonged waterlogging',
      spacing: 'Allow good airflow between plants',
      watchOuts: 'Aphids, mites, fruit damage and bacterial disease',
    );
  }

  if (crop.contains('cabbage')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Performs best in cooler growing periods',
      harvest: 'Often 2–4 months after transplanting, depending on variety',
      sun: 'Full sun',
      water: 'Keep soil consistently moist',
      spacing: 'Leave room for full head development',
      watchOuts: 'Caterpillars, aphids and head rot',
    );
  }

  if (crop.contains('cucumber')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Warm conditions with reliable water',
      harvest: 'Often starts within 6–10 weeks',
      sun: 'Full sun',
      water: 'Frequent, even moisture',
      spacing: 'Give vines room or use trellising',
      watchOuts: 'Mildew, beetles, fruit rot and water stress',
    );
  }

  if (crop.contains('pumpkin')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Warm growing periods with room for vines',
      harvest: 'Usually several months from planting',
      sun: 'Full sun',
      water: 'Regular water while establishing and fruiting',
      spacing: 'Wide spacing for vines',
      watchOuts: 'Vine pests, mildew and fruit rot',
    );
  }

  if (crop.contains('yam')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Plant near the start of the normal yam-growing season',
      harvest: 'Several months, depending on yam type',
      sun: 'Full sun',
      water: 'Good moisture with free drainage',
      spacing: 'Allow space for mounds and staking',
      watchOuts: 'Tuber rot, vine pests and poor drainage',
    );
  }

  if (crop.contains('callaloo')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Can be planted through much of the year',
      harvest: 'Quick crop — first cutting can come within weeks',
      sun: 'Full sun to light shade',
      water: 'Keep soil evenly moist',
      spacing: 'Close spacing is possible for leaf production',
      watchOuts: 'Leaf-eating insects and water stress',
    );
  }

  if (crop.contains('scallion') || crop.contains('onion')) {
    return const _HpjFarmerCropGuideData(
      plantingPeriod: 'Best with good drainage and steady moisture',
      harvest: 'Timing varies by type and planting method',
      sun: 'Full sun',
      water: 'Regular light watering',
      spacing: 'Use enough room for good airflow',
      watchOuts: 'Thrips, leaf disease and waterlogging',
    );
  }

  return const _HpjFarmerCropGuideData(
    plantingPeriod: 'Check the best local planting window for your parish',
    harvest: 'Varies by crop, variety and local conditions',
    sun: 'Most food crops prefer good light',
    water: 'Keep moisture suitable for the crop and avoid waterlogging',
    spacing: 'Use spacing that allows airflow and easy field access',
    watchOuts: 'Watch for pest damage, disease, poor drainage and heat stress',
  );
}

Future<void> _showHpjFarmerCropGuide(
  BuildContext context,
  String cropName, {
  FarmerMarketDemandOpportunity? demand,
  FarmerSupplyForecast? supply,
}) async {
  final guide = _hpjFarmerCropGuideFor(cropName);

  String marketNote() {
    if (demand == null) {
      return 'Open What Buyers Need to check current HPJ demand for this crop.';
    }

    if (demand.opportunityGap <= 0.0001) {
      return 'HPJ currently has enough confirmed supply for this visible demand.';
    }

    return 'Buyers currently need ${_farmerPartnerNumber(demand.opportunityGap)} ${demand.unit} more.';
  }

  String supplyNote() {
    if (supply == null) return 'No crop quantity is attached to this guide.';
    final quantity = supply.harvestedQuantity ??
        supply.expectedQuantity ??
        supply.quantityGrowing ??
        0;
    return quantity > 0
        ? 'You currently have ${_farmerPartnerNumber(quantity)} ${supply.unit} reported.'
        : 'Update your quantity when you know what will be available.';
  }

  Widget guideRow({
    required IconData icon,
    required String label,
    required String value,
    required Color soft,
    required Color accent,
  }) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            width: 38,
            height: 38,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: soft,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Icon(icon, size: 19, color: accent),
          ),
          const SizedBox(width: 11),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  label,
                  style: const TextStyle(
                    color: FarmColors.ink,
                    fontSize: 10.8,
                    fontWeight: FontWeight.w900,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  value,
                  style: const TextStyle(
                    color: FarmColors.mutedText,
                    fontSize: 9.7,
                    height: 1.35,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    backgroundColor: Colors.transparent,
    builder: (sheetContext) {
      return FractionallySizedBox(
        heightFactor: .91,
        child: Material(
          color: const Color(0xFFF8FBF6),
          borderRadius: const BorderRadius.vertical(
            top: Radius.circular(28),
          ),
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(18, 12, 12, 10),
                child: Row(
                  children: [
                    Container(
                      width: 42,
                      height: 4,
                      decoration: BoxDecoration(
                        color: const Color(0xFFD8DDD5),
                        borderRadius: BorderRadius.circular(99),
                      ),
                    ),
                    const Spacer(),
                    IconButton(
                      tooltip: 'Close',
                      onPressed: () => Navigator.of(sheetContext).pop(),
                      icon: const Icon(Icons.close_rounded),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: SingleChildScrollView(
                  padding: const EdgeInsets.fromLTRB(18, 2, 18, 22),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          HpjProductThumb(
                            productName: cropName,
                            size: 86,
                            radius: 18,
                          ),
