class _HpjFarmerV3Demand extends StatelessWidget {
  final List<FarmerMarketDemandOpportunity> opportunities;
  final int total;
  final VoidCallback onOpen;

  const _HpjFarmerV3Demand({
    required this.opportunities,
    required this.total,
    required this.onOpen,
  });

  bool _urgent(FarmerMarketDemandOpportunity item) =>
      item.demandSignal == 'urgent' ||
      item.demandSignal == 'committed_need';

  String _badgeLabel(FarmerMarketDemandOpportunity item) {
    if (_urgent(item)) return 'High Demand';
    if (item.demandSignal == 'opportunity') return 'Opportunity';
    return 'Steady';
  }

  Color _badgeColor(FarmerMarketDemandOpportunity item) {
    if (_urgent(item)) return const Color(0xFFEF4A43);
    if (item.demandSignal == 'opportunity') return const Color(0xFFF6A623);
    return const Color(0xFFF2D94E);
  }

  Future<void> _showProduceDetails(
    BuildContext context,
    FarmerMarketDemandOpportunity item,
  ) async {
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        final needDate = item.nextNeedBy;
        final needDateLabel = needDate == null
            ? 'Open requirement'
            : _farmerPartnerDate(needDate);

        return _HpjFarmerProduceDetailSheet(
          productName: item.productName,
          eyebrow: 'MARKET DEMAND',
          badgeLabel: _badgeLabel(item),
          badgeColor: _badgeColor(item),
          headline:
              '${_farmerPartnerNumber(item.opportunityGap)} ${item.unit} needed',
          summary:
              'Businesses are currently requesting this produce through HPJ.',
          facts: [
            _HpjFarmerProduceFact(
              icon: Icons.storefront_outlined,
              label: 'Market need',
              value:
                  '${_farmerPartnerNumber(item.visibleDemand)} ${item.unit}',
            ),
            _HpjFarmerProduceFact(
              icon: Icons.inventory_2_outlined,
              label: 'Opportunity remaining',
              value:
                  '${_farmerPartnerNumber(item.opportunityGap)} ${item.unit}',
            ),
            _HpjFarmerProduceFact(
              icon: Icons.calendar_month_outlined,
              label: 'Need by',
              value: needDateLabel,
            ),
          ],
          actionLabel: 'View demand',
          actionIcon: Icons.arrow_forward_rounded,
          onAction: () {
            Navigator.of(sheetContext).pop();
            onOpen();
          },
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    return _FarmerElitePanelShell(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _FarmerElitePanelHeader(
            icon: Icons.bar_chart_rounded,
            title: 'Market Demand',
            subtitle: 'See what buyers need now',
            onAction: onOpen,
            actionLabel: 'Manage Crops',
            compact: true,
          ),
          const SizedBox(height: 12),
          if (opportunities.isEmpty)
            Material(
              color: const Color(0xFFF7FAF6),
              borderRadius: BorderRadius.circular(16),
              child: InkWell(
                onTap: onOpen,
                borderRadius: BorderRadius.circular(16),
                child: const Padding(
                  padding: EdgeInsets.all(16),
                  child: Row(
                    children: [
                      Icon(Icons.storefront_outlined, color: FarmColors.primary),
                      SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          'No open buyer requests right now. Tap to view the full demand board.',
                          style: TextStyle(
                            color: FarmColors.mutedText,
                            fontSize: 10.5,
                            height: 1.35,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ),
                      Icon(
                        Icons.chevron_right_rounded,
                        color: FarmColors.deepGreen,
                      ),
                    ],
                  ),
                ),
              ),
            )
          else ...[
            SizedBox(
              height: 174,
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                physics: const BouncingScrollPhysics(),
                itemCount: opportunities.length,
                separatorBuilder: (_, __) => const SizedBox(width: 12),
                itemBuilder: (context, index) =>
                    _demandCard(context, opportunities[index]),
              ),
            ),
            if (opportunities.length > 1) ...[
              const SizedBox(height: 10),
              const _HpjFarmerSwipeHint(),
            ],
          ],
        ],
      ),
    );
  }

  Widget _demandCard(
    BuildContext context,
    FarmerMarketDemandOpportunity item,
  ) {
    final badge = _badgeLabel(item);
    final badgeColor = _badgeColor(item);

    return Material(
      color: Colors.white,
      borderRadius: BorderRadius.circular(16),
      child: InkWell(
        onTap: () => _showProduceDetails(context, item),
        borderRadius: BorderRadius.circular(16),
        child: Container(
          width: 160,
          clipBehavior: Clip.antiAlias,
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: const Color(0xFFDDE7DA)),
            boxShadow: const [
              BoxShadow(
                color: Color(0x0A173B30),
                blurRadius: 8,
                offset: Offset(0, 3),
              ),
            ],
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Stack(
                children: [
                  GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: () => _showHpjFarmerCropGuide(
                      context,
                      item.productName,
                      demand: item,
                    ),
                    child: SizedBox(
                      width: double.infinity,
                      height: 78,
                      child: HpjProductThumb(
                        productName: item.productName,
                        size: 160,
                        radius: 0,
                      ),
                    ),
                  ),
                  Positioned(
                    left: 8,
                    bottom: 8,
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 10,
                        vertical: 5,
                      ),
                      decoration: BoxDecoration(
                        color: badgeColor,
                        borderRadius: BorderRadius.circular(999),
                      ),
                      child: Text(
                        badge,
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 8.8,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                  ),
                ],
              ),
              Expanded(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(10, 8, 10, 8),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        item.productName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.ink,
                          fontSize: 12.5,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        '${_farmerPartnerNumber(item.opportunityGap)} ${item.unit} needed',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 9.7,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                      const Spacer(),
                      Align(
                        alignment: Alignment.centerRight,
                        child: Container(
                          width: 27,
                          height: 27,
                          alignment: Alignment.center,
                          decoration: BoxDecoration(
                            color: FarmColors.primary,
                            borderRadius: BorderRadius.circular(999),
                          ),
                          child: const Icon(
                            Icons.info_outline_rounded,
                            size: 15,
                            color: Colors.white,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

