class _HpjFarmerV3Supply extends StatelessWidget {
  final List<FarmerSupplyForecast> supplies;
  final double Function(FarmerSupplyForecast) quantityFor;
  final VoidCallback onOpen;

  const _HpjFarmerV3Supply({
    required this.supplies,
    required this.quantityFor,
    required this.onOpen,
  });

  Future<void> _showSupplyDetails(
    BuildContext context,
    FarmerSupplyForecast item,
  ) async {
    final quantityController = TextEditingController(
      text: quantityFor(item) > 0
          ? _farmerPartnerNumber(quantityFor(item))
          : '',
    );
    final notesController = TextEditingController(
      text: item.notes ?? '',
    );

    const standardUnits = <String>[
      'lb',
      'kg',
      'each',
      'bundle',
      'bunch',
      'dozen',
    ];

    String normalizeUnit(String raw) {
      final clean = raw.trim().toLowerCase();
      if (standardUnits.contains(clean)) return clean;

      if (clean == 'lbs' || clean == 'pound' || clean == 'pounds') {
        return 'lb';
      }
      if (clean == 'kgs' || clean == 'kilogram' || clean == 'kilograms') {
        return 'kg';
      }
      if (clean == 'ea' || clean == 'unit' || clean == 'units') {
        return 'each';
      }
      if (clean == 'bundles') return 'bundle';
      if (clean == 'bunches') return 'bunch';
      if (clean == 'dozens') return 'dozen';

      // Legacy/invalid values such as "1" should never break the editor.
      return 'each';
    }

    var selectedUnit = normalizeUnit(item.unit);
    var selectedStatus = item.status.trim().isEmpty
        ? 'growing'
        : item.status.trim().toLowerCase();
    var readyDate = item.expectedHarvestDate ?? DateTime.now().add(
      const Duration(days: 7),
    );

    const allowedStatuses = <String>[
      'planning',
      'growing',
      'expected',
      'harvest_ready',
      'harvested',
    ];

    if (!allowedStatuses.contains(selectedStatus)) {
      selectedStatus = 'growing';
    }

    try {
      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        backgroundColor: Colors.transparent,
        builder: (sheetContext) {
          var saving = false;

          return StatefulBuilder(
            builder: (sheetContext, setSheetState) {
              Future<void> pickDate() async {
                final picked = await showDatePicker(
                  context: sheetContext,
                  initialDate: readyDate,
                  firstDate: DateTime.now().subtract(
                    const Duration(days: 1),
                  ),
                  lastDate: DateTime.now().add(
                    const Duration(days: 730),
                  ),
                );

                if (picked != null) {
                  setSheetState(() => readyDate = picked);
                }
              }

              String statusLabel(String value) {
                switch (value) {
                  case 'planning':
                    return 'Planning';
                  case 'growing':
                    return 'Growing';
                  case 'expected':
                    return 'Expected';
                  case 'harvest_ready':
                    return 'Harvest Ready';
                  case 'harvested':
                    return 'Harvested';
                  default:
                    return value;
                }
              }

              Future<void> save() async {
                final quantity = double.tryParse(
                  quantityController.text.trim(),
                );

                if (quantity == null ||
                    quantity < 0 ||
                    quantity.isNaN ||
                    quantity.isInfinite) {
                  ScaffoldMessenger.of(sheetContext).showSnackBar(
                    const SnackBar(
                      content: Text('Enter a valid quantity.'),
                    ),
                  );
                  return;
                }

                setSheetState(() => saving = true);

                try {
                  await updateFarmerSupplyForecast(
                    forecastId: item.id,
                    cropName: item.cropName,
                    expectedQuantity: quantity,
                    unit: selectedUnit,
                    expectedHarvestDate: readyDate,
                    status: selectedStatus,
                    notes: notesController.text.trim(),
                  );

                  if (!sheetContext.mounted) return;
                  Navigator.of(sheetContext).pop();

                  if (!context.mounted) return;
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text(
                        '${item.cropName} updated successfully.',
                      ),
                    ),
                  );
                } catch (error) {
                  if (!sheetContext.mounted) return;
                  setSheetState(() => saving = false);
                  ScaffoldMessenger.of(sheetContext).showSnackBar(
                    SnackBar(
                      content: Text(friendlyAppError(error)),
                    ),
                  );
                }
              }

              return SafeArea(
                top: false,
                child: Padding(
                  padding: EdgeInsets.only(
                    bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
                  ),
                  child: Container(
                    decoration: const BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.vertical(
                        top: Radius.circular(26),
                      ),
                    ),
                    child: SingleChildScrollView(
                      padding: const EdgeInsets.fromLTRB(
                        18,
                        12,
                        18,
                        22,
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Center(
                            child: Container(
                              width: 42,
                              height: 4,
                              decoration: BoxDecoration(
                                color: const Color(0xFFD8DDD5),
                                borderRadius: BorderRadius.circular(99),
                              ),
                            ),
                          ),
                          const SizedBox(height: 14),
                          Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              HpjProductThumb(
                                productName: item.cropName,
                                size: 82,
                                radius: 16,
                              ),
                              const SizedBox(width: 13),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    const Text(
                                      'MY CROPS',
                                      style: TextStyle(
                                        color: FarmColors.primary,
                                        fontSize: 8.8,
                                        fontWeight: FontWeight.w900,
                                        letterSpacing: 1.1,
                                      ),
                                    ),
                                    const SizedBox(height: 5),
                                    Text(
                                      item.cropName,
                                      style: const TextStyle(
                                        color: FarmColors.ink,
                                        fontSize: 21,
                                        height: 1.05,
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                    const SizedBox(height: 6),
                                    Text(
                                      'Update this crop in one place.',
                                      style: const TextStyle(
                                        color: FarmColors.mutedText,
                                        fontSize: 10,
                                        fontWeight: FontWeight.w600,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 14),

                          // Core MVP fields — everything a farmer needs
                          // to maintain a crop without opening a separate wizard.
                          TextField(
                            controller: quantityController,
                            enabled: !saving,
                            keyboardType:
                                const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            decoration: InputDecoration(
                              labelText: 'Available / expected quantity',
                              prefixIcon:
                                  const Icon(Icons.inventory_2_outlined),
                              suffixText: selectedUnit,
                            ),
                          ),
                          const SizedBox(height: 11),

                          Row(
                            children: [
                              Expanded(
                                flex: 5,
                                child: DropdownButtonFormField<String>(
                                  value: selectedUnit,
                                  isExpanded: true,
                                  decoration: const InputDecoration(
                                    labelText: 'Unit',
                                    contentPadding: EdgeInsets.symmetric(
                                      horizontal: 12,
                                      vertical: 13,
                                    ),
                                  ),
                                  style: const TextStyle(
                                    color: FarmColors.ink,
                                    fontSize: 14,
                                    fontWeight: FontWeight.w700,
                                  ),
                                  items: [
                                    for (final unit in standardUnits)
                                      DropdownMenuItem(
                                        value: unit,
                                        child: Text(
                                          unit,
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                        ),
                                      ),
                                  ],
                                  onChanged: saving
                                      ? null
                                      : (value) {
                                          if (value == null) return;
                                          setSheetState(
                                            () => selectedUnit = value,
                                          );
                                        },
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                flex: 6,
                                child: DropdownButtonFormField<String>(
                                  value: selectedStatus,
                                  isExpanded: true,
                                  decoration: const InputDecoration(
                                    labelText: 'Status',
                                    contentPadding: EdgeInsets.symmetric(
                                      horizontal: 12,
                                      vertical: 13,
                                    ),
                                  ),
                                  style: const TextStyle(
                                    color: FarmColors.ink,
                                    fontSize: 13.5,
                                    fontWeight: FontWeight.w700,
                                  ),
                                  items: [
                                    for (final status in allowedStatuses)
                                      DropdownMenuItem(
                                        value: status,
                                        child: Text(
                                          status == 'harvest_ready'
                                              ? 'Ready'
                                              : statusLabel(status),
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                        ),
                                      ),
                                  ],
                                  onChanged: saving
                                      ? null
                                      : (value) {
                                          if (value == null) return;
                                          setSheetState(
                                            () => selectedStatus = value,
                                          );
                                        },
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 11),

                          Material(
                            color: const Color(0xFFF7FAF6),
                            borderRadius: BorderRadius.circular(14),
                            child: ListTile(
                              enabled: !saving,
                              onTap: pickDate,
                              shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(14),
                              ),
                              leading: const Icon(
                                Icons.calendar_month_outlined,
                                color: FarmColors.primary,
                              ),
                              title: const Text(
                                'Expected ready date',
                                style: TextStyle(
                                  fontSize: 11,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                              subtitle: Text(
                                _farmerPartnerDate(readyDate),
                                style: const TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                              trailing:
                                  const Icon(Icons.chevron_right_rounded),
                            ),
                          ),
                          const SizedBox(height: 11),

                          TextField(
                            controller: notesController,
                            enabled: !saving,
                            maxLines: 2,
                            decoration: const InputDecoration(
                              labelText: 'Notes (optional)',
                              hintText:
                                  'Quality, harvest timing, pickup note...',
                            ),
                          ),
                          const SizedBox(height: 14),

                          Container(
                            width: double.infinity,
                            padding: const EdgeInsets.all(12),
                            decoration: BoxDecoration(
                              color: const Color(0xFFEAF5E9),
                              borderRadius: BorderRadius.circular(14),
                            ),
                            child: const Row(
                              crossAxisAlignment: CrossAxisAlignment.start,
