    }
  }

  String _updatedLabel(FarmerSupplyForecast item) {
    final updated = item.updatedAt ?? item.createdAt;
    if (updated == null) return 'Update when anything changes';

    final now = DateTime.now();
    final local = updated.toLocal();
    final today = DateTime(now.year, now.month, now.day);
    final date = DateTime(local.year, local.month, local.day);
    final days = today.difference(date).inDays;

    if (days <= 0) return 'Updated today';
    if (days == 1) return 'Updated yesterday';
    if (days <= 6) return 'Updated $days days ago';
    return 'Update recommended';
  }

