class _HpjFarmerV3Matches extends StatefulWidget {
  final List<FarmerMarketDemandOpportunity> opportunities;
  final bool Function(FarmerMarketDemandOpportunity) matches;
  final VoidCallback onOpen;

  const _HpjFarmerV3Matches({
    required this.opportunities,
    required this.matches,
    required this.onOpen,
  });

  @override
  State<_HpjFarmerV3Matches> createState() => _HpjFarmerV3MatchesState();
}

class _HpjFarmerV3MatchesState extends State<_HpjFarmerV3Matches> {
  final Set<String> _locallyInterested = <String>{};

  String _key(FarmerMarketDemandOpportunity item) =>
      hpjFarmerDemandWatchKey(item.productName, item.unit);

  bool _hasInterest(FarmerMarketDemandOpportunity item) {
    return _locallyInterested.contains(_key(item)) ||
        item.myReportedSupply > 0.0001 ||
        item.myHpjConfirmedSupply > 0.0001;
  }

  bool _isConfirmed(FarmerMarketDemandOpportunity item) =>
      item.myHpjConfirmedSupply > 0.0001;

  Future<void> _showMatchDetails(
    BuildContext context,
    FarmerMarketDemandOpportunity item,
  ) async {
    final urgent = item.demandSignal == 'urgent' ||
        item.demandSignal == 'committed_need';
    final hasInterest = _hasInterest(item);
    final confirmed = _isConfirmed(item);
    final needDate = item.nextNeedBy;
    final needDateLabel = needDate == null
        ? 'Open requirement'
        : _farmerPartnerDate(needDate);

    final reported = item.myReportedSupply;
    final hpjConfirmed = item.myHpjConfirmedSupply;
    final demand = item.visibleDemand;
    final gap = item.opportunityGap;

    String matchStrength;
    if (confirmed) {
      matchStrength = 'Confirmed match';
    } else if (reported > 0 && gap > 0 && reported >= gap) {
      matchStrength = 'Strong match';
    } else if (reported > 0) {
      matchStrength = 'Partial match';
    } else {
      matchStrength = 'Potential match';
    }

    final collectionStatus = confirmed
        ? 'Collection next'
        : 'Not scheduled';

    final whyText = confirmed
        ? 'HPJ has confirmed ${_farmerPartnerNumber(hpjConfirmed)} ${item.unit} from your reported ${item.productName} supply. The remaining market gap is ${_farmerPartnerNumber(gap)} ${item.unit}.'
        : reported > 0
            ? 'You reported ${_farmerPartnerNumber(reported)} ${item.unit} of ${item.productName}. Buyers need ${_farmerPartnerNumber(demand)} ${item.unit}, with ${_farmerPartnerNumber(gap)} ${item.unit} still open.'
            : 'You have an active ${item.productName} match while HPJ still has ${_farmerPartnerNumber(gap)} ${item.unit} of open buyer demand.';

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return _HpjFarmerProduceDetailSheet(
          productName: item.productName,
          eyebrow: 'MATCH OVERVIEW',
          badgeLabel: confirmed
              ? 'HPJ confirmed'
              : hasInterest
                  ? 'Interest sent'
                  : urgent
                      ? 'Priority match'
                      : 'Supply match',
          badgeColor: confirmed
              ? FarmColors.success
              : hasInterest
                  ? const Color(0xFF2F7D4A)
                  : urgent
                      ? const Color(0xFFEF4A43)
                      : const Color(0xFFD341AF),
          headline:
              '${_farmerPartnerNumber(gap)} ${item.unit} market gap',
          summary:
              'A simple view of the buyer need, your supply position and the next step.',
          facts: [
            _HpjFarmerProduceFact(
              icon: Icons.storefront_outlined,
              label: 'Market needs',
              helpTitle: 'What does Market needs mean?',
              helpText:
                  'This is the total buyer demand HPJ can currently see for this produce. It helps you understand the size of the opportunity, but it is not a guaranteed order.',
              value:
                  '${_farmerPartnerNumber(demand)} ${item.unit}',
            ),
            _HpjFarmerProduceFact(
              icon: Icons.eco_outlined,
              label: 'Your reported supply',
              helpTitle: 'Your reported supply',
              helpText:
                  'This is the quantity you most recently told HPJ you expect to have available. Keep it current so matching and collection planning stay accurate.',
              value:
                  '${_farmerPartnerNumber(reported)} ${item.unit}',
            ),
            _HpjFarmerProduceFact(
              icon: Icons.verified_outlined,
              label: 'HPJ confirmed',
              helpTitle: 'HPJ confirmed quantity',
              helpText:
                  'This is the portion of your reported supply HPJ has confirmed against current demand. Confirmed supply is used for more reliable fulfilment and collection planning.',
              value:
                  '${_farmerPartnerNumber(hpjConfirmed)} ${item.unit}',
            ),
            _HpjFarmerProduceFact(
              icon: Icons.add_chart_rounded,
              label: 'Remaining gap',
              helpTitle: 'Remaining market gap',
              helpText:
                  'This is the quantity HPJ still needs after confirmed supply is considered. A larger gap can mean a stronger opportunity, but timing and final buyer confirmation still matter.',
              value:
                  '${_farmerPartnerNumber(gap)} ${item.unit}',
            ),
            _HpjFarmerProduceFact(
              icon: Icons.calendar_month_outlined,
              label: 'Need by',
              helpTitle: 'Buyer need-by date',
              helpText:
                  'This is the current date by which the produce is needed. Compare it with your expected harvest or ready date before offering supply.',
              value: needDateLabel,
            ),
            _HpjFarmerProduceFact(
              icon: Icons.auto_awesome_outlined,
              label: 'Match strength',
              helpTitle: 'How Match strength works',
              helpText:
                  'Match strength is a simple guide based on your reported supply, the remaining gap and whether HPJ has confirmed part of your supply. It is not a guarantee of purchase.',
              value: matchStrength,
            ),
            _HpjFarmerProduceFact(
              icon: Icons.local_shipping_outlined,
              label: 'Collection',
              helpTitle: 'Collection status',
              helpText:
                  'Collection shows whether this match has moved into pickup planning. A confirmed match may still need a final date, location and quantity before pickup is booked.',
              value: collectionStatus,
            ),
          ],
          whyTitle: 'Why this is a match',
          whyText: whyText,
          actionLabel: confirmed
              ? 'HPJ confirmed'
              : hasInterest
                  ? 'Interest sent'
                  : 'Show interest',
          actionIcon: confirmed
              ? Icons.verified_rounded
              : hasInterest
                  ? Icons.check_circle_rounded
                  : Icons.handshake_rounded,
          onAction: () {
            Navigator.of(sheetContext).pop();
            if (!hasInterest && !confirmed) {
              _showInterest(context, item);
            }
          },
        );
      },
    );
  }

  Future<void> _showInterest(
    BuildContext context,
    FarmerMarketDemandOpportunity item,
  ) async {
    if (_hasInterest(item)) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${item.productName}: your interest is already recorded.',
          ),
        ),
      );
      return;
    }

    final qtyController = TextEditingController();
    final notesController = TextEditingController();
    var harvestDate =
        item.nextNeedBy ?? DateTime.now().add(const Duration(days: 7));

    try {
      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        backgroundColor: Colors.transparent,
        builder: (sheetContext) {
          var saving = false;

          return StatefulBuilder(
            builder: (sheetContext, setSheetState) {
              Future<void> pickDate() async {
                final picked = await showDatePicker(
                  context: sheetContext,
                  initialDate: harvestDate,
                  firstDate: DateTime.now(),
                  lastDate: DateTime.now().add(const Duration(days: 365)),
                );
                if (picked != null) {
                  setSheetState(() => harvestDate = picked);
                }
              }

              Future<void> submitInterest() async {
                final qty = double.tryParse(qtyController.text.trim());
                if (qty == null || qty <= 0 || qty.isNaN || qty.isInfinite) {
                  ScaffoldMessenger.of(sheetContext).showSnackBar(
                    SnackBar(
                      content: Text(
                        'Enter how much ${item.productName} you can supply.',
                      ),
                    ),
                  );
                  return;
                }

                setSheetState(() => saving = true);

                try {
                  await createFarmerSupplyForecast(
                    cropName: item.productName,
                    expectedQuantity: qty,
                    unit: item.unit,
                    expectedHarvestDate: harvestDate,
                    status: 'expected',
                    notes: [
                      'Interest from Matching Opportunities.',
                      'Buyer demand: ${_farmerPartnerNumber(item.opportunityGap)} ${item.unit}.',
                      if (notesController.text.trim().isNotEmpty)
                        notesController.text.trim(),
                    ].join(' '),
                  );

                  if (mounted) {
                    setState(() {
                      _locallyInterested.add(_key(item));
                    });
                  }

                  if (!sheetContext.mounted) return;
                  Navigator.of(sheetContext).pop();

                  if (!context.mounted) return;
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text(
                        'Interest sent for ${item.productName}. HPJ can now review your match.',
                      ),
                    ),
                  );
                } catch (error) {
                  if (!sheetContext.mounted) return;
                  setSheetState(() => saving = false);
                  ScaffoldMessenger.of(sheetContext).showSnackBar(
                    SnackBar(
                      content: Text(friendlyAppError(error)),
                    ),
                  );
                }
              }

              return SafeArea(
                top: false,
                child: Padding(
                  padding: EdgeInsets.only(
                    bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
                  ),
                  child: Container(
                    decoration: const BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.vertical(
                        top: Radius.circular(26),
                      ),
                    ),
                    child: SingleChildScrollView(
                      padding: const EdgeInsets.fromLTRB(18, 12, 18, 22),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Center(
                            child: Container(
                              width: 42,
                              height: 4,
                              decoration: BoxDecoration(
                                color: const Color(0xFFD8DDD5),
                                borderRadius: BorderRadius.circular(99),
                              ),
                            ),
                          ),
                          const SizedBox(height: 16),
                          Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              HpjProductThumb(
                                productName: item.productName,
                                size: 70,
                                radius: 14,
                              ),
                              const SizedBox(width: 12),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    const Text(
                                      'MATCHING OPPORTUNITY',
                                      style: TextStyle(
                                        color: FarmColors.primary,
                                        fontSize: 8.8,
                                        fontWeight: FontWeight.w900,
                                        letterSpacing: 1.1,
                                      ),
                                    ),
                                    const SizedBox(height: 5),
                                    Text(
                                      item.productName,
                                      style: const TextStyle(
                                        color: FarmColors.ink,
                                        fontSize: 20,
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                    const SizedBox(height: 3),
                                    Text(
                                      '${_farmerPartnerNumber(item.opportunityGap)} ${item.unit} currently needed',
                                      style: const TextStyle(
                                        color: FarmColors.mutedText,
                                        fontSize: 10.5,
                                        fontWeight: FontWeight.w600,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 18),
                          const Text(
                            'Show your interest',
                            style: TextStyle(
                              color: FarmColors.ink,
                              fontSize: 15,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          const SizedBox(height: 4),
                          const Text(
                            'Tell HPJ what you can supply. This does not confirm a sale; HPJ will review the match and coordinate the next step.',
                            style: TextStyle(
                              color: FarmColors.mutedText,
                              fontSize: 10.2,
                              height: 1.35,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                          const SizedBox(height: 14),
                          TextField(
                            controller: qtyController,
                            enabled: !saving,
                            keyboardType:
                                const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            decoration: InputDecoration(
                              labelText: 'I can supply (${item.unit})',
                              prefixIcon:
                                  const Icon(Icons.inventory_2_outlined),
                            ),
                          ),
                          const SizedBox(height: 11),
                          Material(
                            color: const Color(0xFFF7FAF6),
                            borderRadius: BorderRadius.circular(14),
                            child: ListTile(
                              enabled: !saving,
                              onTap: pickDate,
                              shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(14),
                              ),
                              leading: const Icon(
                                Icons.calendar_month_outlined,
                                color: FarmColors.primary,
                              ),
                              title: const Text(
                                'Expected ready date',
                                style: TextStyle(
                                  fontSize: 11,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                              subtitle: Text(
                                _farmerPartnerDate(harvestDate),
                                style: const TextStyle(
                                  fontSize: 10,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                              trailing:
                                  const Icon(Icons.chevron_right_rounded),
                            ),
                          ),
                          const SizedBox(height: 11),
                          TextField(
                            controller: notesController,
                            enabled: !saving,
                            maxLines: 2,
                            decoration: const InputDecoration(
                              labelText: 'Note to HPJ (optional)',
                              hintText:
                                  'e.g. ready in stages, quality, pickup note',
                            ),
                          ),
                          const SizedBox(height: 16),
                          SizedBox(
                            width: double.infinity,
                            height: 48,
                            child: FilledButton.icon(
                              onPressed: saving ? null : submitInterest,
                              icon: saving
                                  ? const SizedBox(
                                      width: 18,
                                      height: 18,
                                      child: CircularProgressIndicator(
                                        strokeWidth: 2,
                                        color: Colors.white,
                                      ),
                                    )
                                  : const Icon(Icons.handshake_rounded),
                              label: Text(
                                saving
                                    ? 'Sending interest...'
                                    : 'I’m Interested',
                              ),
                              style: FilledButton.styleFrom(
                                backgroundColor: FarmColors.primary,
                                foregroundColor: Colors.white,
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(14),
                                ),
                                textStyle: const TextStyle(
                                  fontSize: 12,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              );
            },
          );
        },
      );
    } finally {
      qtyController.dispose();
      notesController.dispose();
    }
  }

  @override
  Widget build(BuildContext context) {
    final matched = widget.opportunities.where(widget.matches).toList();

    return _FarmerElitePanelShell(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _FarmerElitePanelHeader(
