          ),
          const SizedBox(height: 12),
          if (matched.isEmpty)
            Material(
              color: const Color(0xFFF7FAF6),
              borderRadius: BorderRadius.circular(16),
              child: InkWell(
                onTap: widget.onOpen,
                borderRadius: BorderRadius.circular(16),
                child: const Padding(
                  padding: EdgeInsets.all(16),
                  child: Row(
                    children: [
                      Icon(Icons.link_rounded, color: FarmColors.primary),
                      SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          'No supply matches right now. Keep your produce updated so HPJ can match new buyer needs.',
                          style: TextStyle(
                            color: FarmColors.mutedText,
                            fontSize: 10.5,
                            height: 1.35,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ),
                      Icon(Icons.chevron_right_rounded),
                    ],
                  ),
                ),
              ),
            )
          else ...[
            SizedBox(
              height: 184,
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                physics: const BouncingScrollPhysics(),
                itemCount: matched.length,
                separatorBuilder: (_, __) => const SizedBox(width: 12),
                itemBuilder: (context, index) =>
                    _matchCard(context, matched[index]),
              ),
            ),
            if (matched.length > 1) ...[
              const SizedBox(height: 10),
              const _HpjFarmerSwipeHint(),
            ],
          ],
        ],
      ),
    );
  }

  Widget _matchCard(
    BuildContext context,
    FarmerMarketDemandOpportunity item,
  ) {
    final urgent = item.demandSignal == 'urgent' ||
        item.demandSignal == 'committed_need';
    final hasInterest = _hasInterest(item);
    final confirmed = _isConfirmed(item);

    final badgeLabel = confirmed
        ? 'HPJ confirmed'
        : hasInterest
            ? 'Interest sent'
            : urgent
                ? 'Priority match'
                : 'Supply match';

    final badgeColor = confirmed
        ? FarmColors.success
        : hasInterest
            ? const Color(0xFF2F7D4A)
            : urgent
                ? const Color(0xFFEF4A43)
                : const Color(0xFFD341AF);

    final reported = item.myReportedSupply;
    final gap = item.opportunityGap;

    final description = confirmed
        ? 'Collection next'
        : hasInterest
            ? 'Under HPJ review'
            : reported > 0
                ? '${_farmerPartnerNumber(reported)} ${item.unit} reported'
                : '${_farmerPartnerNumber(gap)} ${item.unit} gap';

    return Material(
      color: Colors.white,
      borderRadius: BorderRadius.circular(16),
      child: InkWell(
        onTap: () => _showMatchDetails(context, item),
        borderRadius: BorderRadius.circular(16),
        child: Container(
          width: 166,
          clipBehavior: Clip.antiAlias,
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: const Color(0xFFDDE7DA)),
            boxShadow: const [
              BoxShadow(
                color: Color(0x0A173B30),
                blurRadius: 8,
                offset: Offset(0, 3),
              ),
            ],
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Stack(
                children: [
                  GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: () => _showHpjFarmerCropGuide(
                      context,
                      item.productName,
                      demand: item,
                    ),
                    child: SizedBox(
                      width: double.infinity,
                      height: 76,
                      child: HpjProductThumb(
                        productName: item.productName,
                        size: 166,
                        radius: 0,
                      ),
                    ),
                  ),
                  Positioned(
                    left: 8,
                    bottom: 8,
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 9,
                        vertical: 5,
                      ),
                      decoration: BoxDecoration(
                        color: badgeColor,
                        borderRadius: BorderRadius.circular(999),
                      ),
                      child: Text(
                        badgeLabel,
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 8.4,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                  ),
                ],
              ),
              Expanded(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(10, 8, 10, 8),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        item.productName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.ink,
                          fontSize: 12.5,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        description,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 9.4,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        'Market: ${_farmerPartnerNumber(item.visibleDemand)} ${item.unit}',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: FarmColors.deepGreen,
                          fontSize: 8.8,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      const Spacer(),
                      SizedBox(
                        width: double.infinity,
                        height: 30,
                        child: Material(
                          color: hasInterest || confirmed
                              ? const Color(0xFFE7F4E9)
                              : const Color(0xFFEAF5E9),
                          borderRadius: BorderRadius.circular(10),
                          child: InkWell(
                            onTap: confirmed || hasInterest
                                ? () => _showMatchDetails(context, item)
                                : () => _showInterest(context, item),
                            borderRadius: BorderRadius.circular(10),
                            child: Row(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                Icon(
                                  confirmed
                                      ? Icons.verified_rounded
                                      : hasInterest
                                          ? Icons.check_circle_rounded
                                          : Icons.handshake_outlined,
                                  size: 14,
                                  color: FarmColors.deepGreen,
                                ),
                                const SizedBox(width: 5),
                                Text(
                                  confirmed
                                      ? 'Confirmed'
                                      : hasInterest
                                          ? 'Interest sent'
                                          : 'Show interest',
                                  style: const TextStyle(
                                    color: FarmColors.deepGreen,
                                    fontSize: 9.4,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

