class _HpjFarmerCollectionMapPainter extends CustomPainter {
  const _HpjFarmerCollectionMapPainter();

  @override
  void paint(Canvas canvas, Size size) {
    final roadPaint = Paint()
      ..color = Colors.white
      ..strokeWidth = 4.2
      ..strokeCap = StrokeCap.round
      ..style = PaintingStyle.stroke;

    final minorRoadPaint = Paint()
      ..color = const Color(0xFFD6E3D4)
      ..strokeWidth = 2.1
      ..strokeCap = StrokeCap.round
      ..style = PaintingStyle.stroke;

    final pathA = Path()
      ..moveTo(-10, size.height * .78)
      ..cubicTo(
        size.width * .21,
        size.height * .59,
        size.width * .44,
        size.height * .84,
        size.width * .68,
        size.height * .44,
      )
      ..cubicTo(
        size.width * .80,
        size.height * .25,
        size.width * .91,
        size.height * .33,
        size.width + 10,
        size.height * .10,
      );
    canvas.drawPath(pathA, roadPaint);

    final pathB = Path()
      ..moveTo(size.width * .14, -8)
      ..cubicTo(
        size.width * .22,
        size.height * .24,
        size.width * .35,
        size.height * .25,
        size.width * .47,
        size.height * .43,
      )
      ..cubicTo(
        size.width * .59,
        size.height * .61,
        size.width * .61,
        size.height * .79,
        size.width * .72,
        size.height + 8,
      );
    canvas.drawPath(pathB, minorRoadPaint);

    final pathC = Path()
      ..moveTo(size.width * .46, -8)
      ..quadraticBezierTo(
        size.width * .58,
        size.height * .24,
        size.width * .88,
        size.height * .64,
      );
    canvas.drawPath(pathC, minorRoadPaint);

    final center = Offset(size.width * .57, size.height * .50);
    canvas.drawCircle(
      center,
      10,
      Paint()
        ..color = const Color(0xFF197A48)
        ..style = PaintingStyle.fill,
    );
    canvas.drawCircle(
      center,
      3.8,
      Paint()..color = Colors.white,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

