  Widget _needsAttention(FarmPublicProfileBundle bundle) {
    final entries = <Widget>[];
    final review = widget.suppliesNeedingReview.isNotEmpty
        ? widget.suppliesNeedingReview.first
        : null;
    if (review != null) {
      entries.add(
        _attentionCard(
          title: 'Update ${review.cropName} availability',
          icon: Icons.notifications_active_rounded,
          accent: const Color(0xFFD92D2D),
          imageUrl: _productImage(review.cropName, bundle.products),
          onTap: widget.onSupply,
        ),
      );
    }

    FarmerSupplyForecast? harvestWindow;
    for (final supply in widget.supplies) {
      if (supply.expectedHarvestDate != null) {
        harvestWindow = supply;
        break;
      }
    }
    if (harvestWindow != null) {
      entries.add(
        _attentionCard(
          title: 'Confirm ${harvestWindow.cropName} harvest window',
          icon: Icons.calendar_month_rounded,
          accent: _gold,
          imageUrl: _productImage(harvestWindow.cropName, bundle.products),
          onTap: widget.onSupply,
        ),
      );
    }

    final demand = _featuredDemand;
    if (demand != null) {
      entries.add(
        _attentionCard(
          title: 'Review buyer request',
          icon: Icons.description_rounded,
          accent: _green,
          imageUrl: _productImage(demand.productName, bundle.products),
          onTap: widget.onDemand,
        ),
      );
    }

    if (entries.isEmpty && _nextCollection != null) {
      entries.add(
        _attentionCard(
          title: 'Review next collection',
          icon: Icons.local_shipping_rounded,
          accent: _green,
          imageUrl: _farmImage(bundle),
          onTap: widget.onCollections,
        ),
      );
    }

    if (entries.isEmpty) {
      return const SizedBox.shrink();
    }

    return Container(
      padding: const EdgeInsets.fromLTRB(11, 11, 11, 12),
      decoration: _surface(radius: 18),
      child: Column(
        children: [
          _sectionHeading(
            icon: Icons.error_rounded,
            title: 'Needs attention',
            subtitle: 'A few things need your action.',
            actionLabel: 'See all (${entries.length})',
            onAction: widget.onSupply,
            iconColor: const Color(0xFFD92D2D),
          ),
          const SizedBox(height: 9),
          SizedBox(
            height: 112,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              itemCount: entries.length,
              separatorBuilder: (_, __) => const SizedBox(width: 8),
              itemBuilder: (_, index) => entries[index],
            ),
          ),
        ],
      ),
    );
  }

