  Color _supplyStatusColor(FarmerSupplyForecast supply) {
    if (supply.isHarvestReady || supply.isHarvested || supply.isHpjConfirmed) {
      return const Color(0xFF2F8A45);
    }
    if (supply.isPlanning || supply.isExpected) return _gold;
    return _green;
  }

