          const SizedBox(height: 9),
          SizedBox(
            height: 112,
            child: Row(
              children: [
                _collectionPaymentCard(
                icon: Icons.local_shipping_rounded,
                title: 'Next collection',
                value: next == null
                    ? 'No collection set'
                    : _fullDate(next.collectionDate),
                helper: next == null
                    ? 'HPJ will show the next collection here.'
