  void _openAdvancedTools() {
    Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => _FarmerPartnerToolShell(
          title: 'Grow & Community',
          child: ListView(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 90),
            children: [FarmerPartnerToolsCard(profile: widget.profile)],
          ),
        ),
      ),
    );
  }

  Future<void> _openFarmerLearning() async {
    final tutorial = await fetchPublishedHelpTutorial(
      placement: 'farmer',
      audience: 'farmer',
    );
    if (!mounted) return;
    if (tutorial != null) {
      await openHpjHelpTutorial(context, tutorial);
      return;
    }
    _openAdvancedTools();
  }

  Widget _growCommunity(FarmPublicProfileBundle bundle) {
    String? firstPhoto;
    String? secondPhoto;
    if (bundle.photos.isNotEmpty) {
      firstPhoto = cleanHostedImageUrl(bundle.photos.first.imageUrl);
    }
    if (bundle.photos.length > 1) {
      secondPhoto = cleanHostedImageUrl(bundle.photos[1].imageUrl);
    }
    final farmImage = _farmImage(bundle);
    final productImage = bundle.products.isEmpty
        ? null
        : cleanHostedImageUrl(bundle.products.first.imageUrl);

    return Container(
      padding: const EdgeInsets.fromLTRB(11, 11, 11, 12),
      decoration: _surface(radius: 18),
      child: Column(
        children: [
          _sectionHeading(
            icon: Icons.groups_rounded,
            title: 'Grow & Community',
            subtitle: 'Tips, stories and resources for a stronger farming community.',
            actionLabel: 'Explore',
            onAction: _openAdvancedTools,
          ),
          const SizedBox(height: 9),
          SizedBox(
            height: 74,
            child: ListView(
              scrollDirection: Axis.horizontal,
              children: [
                _communityCard(
                  title: 'Grow Tips',
                  helper: 'Smarter planning for your crops',
                  imageUrl: productImage ?? firstPhoto ?? farmImage,
                  icon: Icons.eco_rounded,
                  onTap: () => Navigator.of(context).push<void>(
                    MaterialPageRoute<void>(
                      builder: (_) => HpjFarmerGrowIntelligenceScreen(
                        profile: widget.profile,
                      ),
                    ),
                  ),
                ),
                const SizedBox(width: 8),
                _communityCard(
                  title: 'Community',
                  helper: 'Share what is happening on your farm',
                  imageUrl: secondPhoto ?? farmImage ?? productImage,
                  icon: Icons.groups_rounded,
                  onTap: () => Navigator.of(context).push<void>(
                    MaterialPageRoute<void>(
                      builder: (_) => HpjFarmerStoriesScreen(
                        profile: widget.profile,
                      ),
                    ),
                  ),
                ),
                const SizedBox(width: 8),
                _communityCard(
                  title: 'Watch & Learn',
                  helper: 'Quick guides for HPJ farmers',
                  imageUrl: farmImage ?? firstPhoto ?? productImage,
                  icon: Icons.play_circle_fill_rounded,
                  onTap: () => unawaited(_openFarmerLearning()),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Future<void> _openFarmerSponsor(HpjSponsorCampaign campaign) async {
    if (campaign.ctaType == 'farm') {
      final farmerId = campaign.targetFarmerId.trim();
      if (farmerId.isEmpty) return;
      await Navigator.of(context).push<void>(
        MaterialPageRoute<void>(
          builder: (_) => PublicFarmProfileScreen(
            farmerId: farmerId,
            sourceWorkspace: 'farmer',
          ),
        ),
      );
      return;
    }

    if (campaign.ctaType == 'external' &&
        _isSafeSponsorExternalUrl(campaign.ctaUrl)) {
      final opened = await openExternalShareUrl(campaign.ctaUrl);
      if (!opened && mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Could not open the sponsor link.')),
        );
      }
      return;
    }

    // A Shop CTA belongs in the Customer workspace. Use the existing mobile
    // workspace switcher rather than inventing a second shopping route here.
    if (mounted) {
      await showHpjMobileAccountPortalSheet(
        context,
        currentPortal: 'farmer',
      );
    }
  }

  Widget _farmerSponsorCard(HpjSponsorCampaign campaign) {
    final media = campaign.imageUrl.trim().isNotEmpty
        ? campaign.imageUrl.trim()
        : campaign.logoUrl.trim();

    return Material(
      color: Colors.white,
      borderRadius: BorderRadius.circular(18),
      child: InkWell(
        onTap: () => unawaited(_openFarmerSponsor(campaign)),
        borderRadius: BorderRadius.circular(18),
        child: Container(
          width: double.infinity,
          clipBehavior: Clip.antiAlias,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(18),
            border: Border.all(color: _line),
          ),
          child: Row(
            children: [
              SizedBox(
                width: 92,
                height: 92,
                child: media.isEmpty || !_isSafeSponsorExternalUrl(media)
                    ? Container(
                        color: _soft,
                        alignment: Alignment.center,
                        child: const Icon(
                          Icons.campaign_outlined,
                          color: _deepGreen,
                          size: 28,
                        ),
                      )
                    : Image.network(
                        media,
                        fit: BoxFit.cover,
                        errorBuilder: (_, __, ___) => Container(
                          color: _soft,
                          alignment: Alignment.center,
                          child: const Icon(
                            Icons.campaign_outlined,
                            color: _deepGreen,
                            size: 28,
                          ),
                        ),
                      ),
              ),
              const SizedBox(width: 11),
              Expanded(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(0, 10, 10, 10),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'SPONSORED',
                        style: TextStyle(
                          color: _gold,
                          fontSize: 8.5,
                          fontWeight: FontWeight.w900,
                          letterSpacing: .5,
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        campaign.sponsorName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: _ink,
                          fontSize: 12.5,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        campaign.headline,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                          color: _muted,
                          fontSize: 10,
                          height: 1.25,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      const SizedBox(height: 5),
                      Text(
                        campaign.ctaLabel.trim().isEmpty
                            ? 'Learn more →'
                            : '${campaign.ctaLabel.trim()} →',
                        style: const TextStyle(
                          color: _deepGreen,
                          fontSize: 9.5,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _farmerNetworkContent() {
    final preferences = widget.preferences;
    final showFeed = preferences.showAgricultureNews;
    final showReels = preferences.showFreshReels;
    final showSponsor = preferences.showPromotions;
    if (!showFeed && !showReels && !showSponsor) {
      return const SizedBox.shrink();
    }

    return Container(
      padding: const EdgeInsets.all(12),
      decoration: _surface(radius: 20, color: const Color(0xFFFEFFFC)),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _sectionHeading(
            icon: Icons.groups_2_outlined,
            title: 'From the HPJ Network',
            subtitle: 'Updates, farm videos and clearly labelled partners.',
          ),
          if (showFeed) ...[
            const SizedBox(height: 10),
            HpjAgricultureUpdatesSection(
              audience: 'farmer',
              workspace: 'farmer',
              limit: 2,
              refreshKey: widget.refreshKey,
              title: 'Farmer feed',
              subtitle:
                  'Buyer demand, Jamaican agriculture news and HPJ updates selected for your farm.',
              socialStyle: true,
              showImages: preferences.showFeedImages,
              onAction: widget.onAgricultureAction,
            ),
          ],
          if (showReels) ...[
            const SizedBox(height: 10),
            FreshReelFeedPreviewCard(
              preferences: preferences,
              audience: 'farmer',
              placement: freshReelPlacementFarmerFeed,
              refreshKey: widget.refreshKey,
            ),
          ],
          if (showSponsor) ...[
            FutureBuilder<HpjSponsorCampaign?>(
              future: _sponsorFuture,
              builder: (context, snapshot) {
                final campaign = snapshot.data;
                if (campaign == null) return const SizedBox.shrink();
                return Padding(
                  padding: const EdgeInsets.only(top: 10),
                  child: _farmerSponsorCard(campaign),
                );
              },
            ),
          ],
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<FarmPublicProfileBundle>(
      future: _bundleFuture,
      builder: (context, snapshot) {
        final bundle = snapshot.data ??
            const FarmPublicProfileBundle(
              profile: null,
              products: <Product>[],
              photos: <FarmPublicPhoto>[],
              growingSupply: <PublicFarmSupplyItem>[],
            );

        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _hero(bundle),
            Transform.translate(
              offset: const Offset(0, -9),
              child: _todayPanel(),
            ),
            const SizedBox(height: 2),
            const _HpjFarmerStartNewChatCard(),
            const SizedBox(height: 10),
            _needsAttention(bundle),
            const SizedBox(height: 10),
            _buyerOpportunity(bundle),
            const SizedBox(height: 10),
            _supplySection(bundle),
            const SizedBox(height: 10),
            _collectionsAndPayments(bundle),
            const SizedBox(height: 10),
            _growCommunity(bundle),
            if (widget.preferences.showAgricultureNews ||
                widget.preferences.showFreshReels ||
                widget.preferences.showPromotions) ...[
              const SizedBox(height: 10),
              _farmerNetworkContent(),
            ],
          ],
        );
      },
    );
  }
}

// ============================================================================
// HPJ FARMER V5 — PHONE-FIRST DASHBOARD (presentation only).
// Real farm images, farmer supply, buyer demand, payouts and collections.
// All links use the existing Farmer routes. No demo financial/weather data.
// ============================================================================
// HPJ Farmer V5: mobile-first presentation of existing farmer snapshot.
// No hard-coded demand, payouts, dates, weather, or image URLs.
class _HpjFarmerV4Home extends StatelessWidget {
  final FarmerProfile profile;
  final List<FarmerSupplyForecast> supplies;
  final List<FarmerMarketDemandOpportunity> demand;
  final Set<String> matchingDemandKeys;
  final List<FarmerCollectionScheduleItem> collections;
  final List<_FarmerTodayNotification> notifications;
  final double grossThisMonth;
  final double pending;
  final VoidCallback onSupply;
  final VoidCallback onDemand;
  final VoidCallback onOrders;
  final VoidCallback onPayments;
  final VoidCallback onCollections;
  final VoidCallback onAccount;

  const _HpjFarmerV4Home({
    required this.profile,
    required this.supplies,
    required this.demand,
    required this.matchingDemandKeys,
    required this.collections,
    required this.notifications,
    required this.grossThisMonth,
    required this.pending,
    required this.onSupply,
    required this.onDemand,
    required this.onOrders,
    required this.onPayments,
    required this.onCollections,
    required this.onAccount,
  });

  static const _green = Color(0xFF19543A);
  static const _ink = Color(0xFF193326);
  static const _muted = Color(0xFF647369);
  static const _line = Color(0xFFE0E9DF);
  static const _pale = Color(0xFFF0F8F0);
  static const _red = Color(0xFFAA433B);

  bool _urgent(FarmerMarketDemandOpportunity item) =>
      item.demandSignal == 'urgent' || item.demandSignal == 'committed_need';

  double _qty(FarmerSupplyForecast item) {
    var highest = 0.0;
    for (final value in <double>[
      item.harvestedQuantity ?? 0,
      item.expectedQuantity ?? 0,
      item.quantityGrowing ?? 0,
    ]) {
      if (value.isFinite && value > highest) highest = value;
    }
    return highest;
  }

  Widget _card(Widget child, {EdgeInsets padding = const EdgeInsets.all(16)}) {
    return Container(
      width: double.infinity,
      padding: padding,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: _line),
        boxShadow: [BoxShadow(color: _green.withOpacity(.035),
          blurRadius: 14, offset: const Offset(0, 5))],
      ),
      child: child,
    );
  }

  Widget _sectionTitle(String title, String subtitle, VoidCallback action,
      {String actionLabel = 'See all'}) => Row(
    crossAxisAlignment: CrossAxisAlignment.center,
    children: [
      Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: const TextStyle(fontSize: 20, height: 1.10,
            letterSpacing: -.35, fontWeight: FontWeight.w900, color: _ink)),
          const SizedBox(height: 3),
          Text(subtitle, maxLines: 2, style: const TextStyle(
            fontSize: 11.5, color: _muted, height: 1.22)),
        ])),
      TextButton(onPressed: action,
        style: TextButton.styleFrom(foregroundColor: _green,
          padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 8),
          minimumSize: const Size(0, 38)),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Text(actionLabel, style: const TextStyle(fontSize: 12,
            fontWeight: FontWeight.w900)),
          const SizedBox(width: 2),
          const Icon(Icons.arrow_forward_rounded, size: 16),
        ])),
    ],
  );

  Widget _bigAction(IconData icon, String title, String subtitle,
      VoidCallback onTap, {required bool primary}) {
    final fg = primary ? Colors.white : _ink;
    return Material(
      color: primary ? _green : Colors.white,
      borderRadius: BorderRadius.circular(19),
      child: InkWell(onTap: onTap, borderRadius: BorderRadius.circular(19),
        child: Container(height: 108,
          padding: const EdgeInsets.fromLTRB(13, 12, 11, 11),
          decoration: BoxDecoration(borderRadius: BorderRadius.circular(19),
            border: Border.all(color: primary ? _green : _line)),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [
              Container(height: 31, width: 31,
                decoration: BoxDecoration(
                  color: primary ? Colors.white.withOpacity(.15) : _pale,
                  borderRadius: BorderRadius.circular(10)),
                child: Icon(icon, size: 19,
                  color: primary ? Colors.white : _green)),
              const Spacer(),
              Icon(Icons.arrow_outward_rounded, color: fg, size: 18),
            ]),
            const Spacer(),
            Text(title, maxLines: 1, overflow: TextOverflow.ellipsis,
              style: TextStyle(fontSize: 15, fontWeight: FontWeight.w900,
                color: fg)),
            Text(subtitle, maxLines: 1, overflow: TextOverflow.ellipsis,
              style: TextStyle(fontSize: 10.5,
                color: primary ? const Color(0xFFDFF0E3) : _muted)),
          ]),
        ),
      ),
    );
  }

  Widget _smallAction(IconData icon, String title, VoidCallback onTap) =>
    Material(color: Colors.white, borderRadius: BorderRadius.circular(15),
