class _FarmerEliteHero extends StatelessWidget {
  final FarmerProfile profile;
  final bool desktop;
  final VoidCallback onAddSupply;

  const _FarmerEliteHero({
    required this.profile,
    required this.desktop,
    required this.onAddSupply,
  });

  String get _fallbackFarmName {
    final farm = profile.farmName.trim();
    if (farm.isNotEmpty) return farm;
    final farmer = profile.farmerName.trim();
    return farmer.isEmpty ? 'My Farm' : "$farmer's Farm";
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<FarmPublicProfileRecord?>(
      future: fetchFarmPublicProfile(
        profile.id,
        includeUnpublished: true,
      ),
      builder: (context, snapshot) {
        final farm = snapshot.data;
        final cover = cleanHostedImageUrl(farm?.coverImageUrl);
        final logo = cleanHostedImageUrl(farm?.logoImageUrl);
        final farmName = (farm?.publicName.trim().isNotEmpty ?? false)
            ? farm!.publicName.trim()
            : _fallbackFarmName;
        final community = farm?.community.trim() ?? '';
        final parish = (farm?.parish.trim().isNotEmpty ?? false)
            ? farm!.parish.trim()
            : profile.parish.trim();
        final verified = farm?.hpjVerified == true;

        final location = <String>[
          if (community.isNotEmpty) community,
          if (parish.isNotEmpty) parish,
          if (community.isEmpty && parish.isEmpty) 'Jamaica',
        ].join(' • ');

        return Container(
          height: desktop ? 190 : 245,
          clipBehavior: Clip.antiAlias,
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(desktop ? 18 : 20),
            color: const Color(0xFFE7EFE2),
            border: Border.all(color: const Color(0xFFDCE5D8)),
            boxShadow: [
              BoxShadow(
                color: const Color(0xFF0B4A33).withOpacity(.06),
                blurRadius: 10,
                offset: const Offset(0, 8),
              ),
            ],
          ),
          child: Stack(
            fit: StackFit.expand,
            children: [
              if (cover != null)
                Image.network(
                  cover,
                  fit: BoxFit.cover,
                  alignment: Alignment.center,
                  errorBuilder: (_, __, ___) => DecoratedBox(
                    decoration: BoxDecoration(
                      color: const Color(0xFFF8FBF6),
                      border: Border.all(color: const Color(0xFFDDE6DA)),
                    ),
                  ),
                )
              else
                DecoratedBox(
                  decoration: BoxDecoration(
                    color: const Color(0xFFDDE6DA),
                    border: Border.all(color: const Color(0xFFDDE6DA)),
                  ),
                ),
              DecoratedBox(
                decoration: BoxDecoration(
                  color: const Color(0xFFDDE6DA),
                  border: Border.all(color: const Color(0xFFDDE6DA)),
                ),
              ),
              Padding(
                padding: EdgeInsets.fromLTRB(
                  desktop ? 26 : 18,
                  desktop ? 20 : 18,
                  desktop ? 20 : 16,
                  desktop ? 18 : 16,
                ),
                child: desktop
                    ? _desktopHeroContent(
                        farmName: farmName,
                        location: location,
                        verified: verified,
                        logo: logo,
                      )
                    : _mobileHeroContent(
                        farmName: farmName,
                        location: location,
                        verified: verified,
                        logo: logo,
                      ),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _desktopHeroContent({
    required String farmName,
    required String location,
    required bool verified,
    required String? logo,
  }) {
    return Row(
      children: [
        Expanded(
          flex: 7,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Row(
                crossAxisAlignment: CrossAxisAlignment.center,
                children: [
                  _farmerIdentityLogo(
                    logo: logo,
                    farmName: farmName,
                    size: 58,
                  ),
                  const SizedBox(width: 13),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          DateTime.now().hour < 12
                      ? 'Good morning,'
                      : DateTime.now().hour < 17
                          ? 'Good afternoon,'
                          : 'Good evening,',
                          style: TextStyle(
                            color: FarmColors.deepGreen,
                            fontSize: 13,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                        const SizedBox(height: 2),
                        Text(
                          farmName,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: Color(0xFF073F2D),
                            fontSize: 32,
                            height: .98,
                            fontWeight: FontWeight.w900,
                            letterSpacing: -1.1,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              const Text(
                'Together we grow a stronger, healthier Jamaica.',
                style: TextStyle(
                  color: FarmColors.deepGreen,
                  fontSize: 15,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 4),
              const Text(
                'List your supply, meet real demand and grow your business with The Harvest Place Ja.',
                style: TextStyle(
                  color: FarmColors.ink,
                  fontSize: 11,
                  height: 1.3,
                  fontWeight: FontWeight.w600,
                ),
              ),
              const SizedBox(height: 12),
              Wrap(
                spacing: 8,
                runSpacing: 7,
                children: [
                  _FarmerEliteHeroChip(
                    icon: Icons.location_on_rounded,
                    label: location,
                  ),
                  if (verified)
                    const _FarmerEliteHeroChip(
                      icon: Icons.verified_rounded,
                      label: 'HPJ Verified',
                    ),
                  const _FarmerEliteHeroChip(
                    icon: Icons.eco_rounded,
                    label: 'Fresh produce',
                  ),
                  const _FarmerEliteHeroChip(
                    icon: Icons.flag_rounded,
                    label: 'Jamaican farmer',
                  ),
                ],
              ),
            ],
          ),
        ),
        const Spacer(flex: 2),
        Column(
          mainAxisAlignment: MainAxisAlignment.center,
          crossAxisAlignment: CrossAxisAlignment.end,
          children: [
            const Text(
              'Grow\nSell\nThrive',
              textAlign: TextAlign.right,
              style: TextStyle(
                color: Color(0xFF123E2E),
                fontSize: 19,
                height: .88,
                fontStyle: FontStyle.italic,
                fontWeight: FontWeight.w800,
              ),
            ),
            const SizedBox(height: 18),
            FilledButton.icon(
              onPressed: onAddSupply,
              icon: const Icon(Icons.add_rounded, size: 20),
              label: const Text('Add your supply'),
              style: FilledButton.styleFrom(
                backgroundColor: FarmColors.primary,
                foregroundColor: Colors.white,
                padding: const EdgeInsets.symmetric(
                  horizontal: 22,
                  vertical: 16,
                ),
                textStyle: const TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                ),
                shape: const StadiumBorder(),
              ),
            ),
          ],
        ),
      ],
    );
  }

  Widget _farmerIdentityLogo({
    required String? logo,
    required String farmName,
    required double size,
  }) {
    final cleanName = farmName.trim();
    final initial = cleanName.isEmpty ? 'F' : cleanName.substring(0, 1).toUpperCase();

    Widget fallback() {
      return Container(
        color: const Color(0xFFF2F7EE),
        alignment: Alignment.center,
        child: Text(
          initial,
          style: TextStyle(
            color: FarmColors.deepGreen,
            fontSize: size * .40,
            fontWeight: FontWeight.w900,
          ),
        ),
      );
    }

    return Container(
      width: size,
      height: size,
      padding: const EdgeInsets.all(3),
      decoration: BoxDecoration(
        color: const Color(0xFFF8FBF6),
        shape: BoxShape.circle,
        border: Border.all(
          color: const Color(0xFFDDE6DA),
          width: 2,
        ),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF0B4A33).withOpacity(.14),
            blurRadius: 12,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: ClipOval(
        child: logo == null
            ? fallback()
            : Image.network(
                logo,
                fit: BoxFit.contain,
                errorBuilder: (_, __, ___) => fallback(),
              ),
      ),
    );
  }

  Widget _mobileHeroContent({
    required String farmName,
    required String location,
    required bool verified,
    required String? logo,
  }) {
    // Actual farm cover photo is drawn behind this copy by the parent hero.
    // Keep the right-hand side open so farmers see their own photograph.
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(
        DateTime.now().hour < 12 ? 'Good morning,' :
            DateTime.now().hour < 17 ? 'Good afternoon,' : 'Good evening,',
        style: const TextStyle(fontSize: 12, color: FarmColors.deepGreen,
          fontWeight: FontWeight.w800)),
      const SizedBox(height: 4),
      ConstrainedBox(constraints: const BoxConstraints(maxWidth: 255),
        child: Text(farmName, maxLines: 2, overflow: TextOverflow.ellipsis,
          style: const TextStyle(fontSize: 31, height: 1.0,
            color: FarmColors.deepGreen, fontWeight: FontWeight.w900,
            letterSpacing: -.8))),
      if (verified) ...[
        const SizedBox(height: 8),
        const Row(mainAxisSize: MainAxisSize.min, children: [
          Icon(Icons.verified_rounded, color: FarmColors.success, size: 18),
          SizedBox(width: 6),
          Text('HPJ verified farmer', style: TextStyle(
            color: FarmColors.success, fontSize: 11.5,
            fontWeight: FontWeight.w900)),
        ]),
      ],
      const SizedBox(height: 10),
      Row(mainAxisSize: MainAxisSize.min, children: [
        const Icon(Icons.location_on_rounded, color: FarmColors.deepGreen,
          size: 16),
        const SizedBox(width: 4),
        Flexible(child: Text(location, maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: const TextStyle(fontSize: 11.5,
            color: FarmColors.ink, fontWeight: FontWeight.w800))),
      ]),
      const Spacer(),
      const Text('GROW • SELL • THRIVE',
        style: TextStyle(fontSize: 10, letterSpacing: 1.0,
          color: FarmColors.primary, fontWeight: FontWeight.w900)),
      const SizedBox(height: 4),
      const Text('Grow with us. Feed Jamaica.',
        maxLines: 1, overflow: TextOverflow.ellipsis,
        style: TextStyle(fontSize: 12.5,
          color: FarmColors.deepGreen, fontWeight: FontWeight.w800)),
    ]);
  }

}

