      _FarmerEliteMetricCard(
        desktop: desktop,
        icon: Icons.priority_high_rounded,
        value: '$urgentNeeds',
        label: 'Urgent needs',
        helper: 'High priority this week',
        accent: FarmColors.danger,
        soft: const Color(0xFFFFECEC),
