      _FarmerEliteMetricCard(
        desktop: desktop,
        icon: Icons.local_shipping_outlined,
        value: '$collections',
        label: 'Collections',
        helper: 'Upcoming pickups',
        onTap: onOpenCollections,
      ),
      _FarmerEliteMetricCard(
        desktop: desktop,
        icon: Icons.account_balance_wallet_outlined,
        value: formatJmd(pendingPayments),
        label: desktop ? 'Pending payments' : 'Payments',
        helper: 'From completed deliveries',
        onTap: onOpenPayments,
      ),
    ];

    if (desktop) {
      return LayoutBuilder(
        builder: (context, constraints) {
          const gap = 10.0;
          final width = (constraints.maxWidth - gap * 4) / 5;
          return Row(
            children: [
              for (var i = 0; i < cards.length; i++) ...[
                SizedBox(width: width, child: cards[i]),
                if (i != cards.length - 1) const SizedBox(width: gap),
              ],
            ],
          );
        },
      );
    }

    return SizedBox(
      height: 126,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        padding: EdgeInsets.zero,
        itemCount: cards.length,
        separatorBuilder: (_, __) => const SizedBox(width: 8),
        itemBuilder: (_, index) => SizedBox(
          width: 116,
          child: cards[index],
        ),
      ),
    );
  }
}

class _FarmerEliteMetricCard extends StatelessWidget {
