class _FarmerEliteDemandPanel extends StatelessWidget {
  final bool desktop;
  final List<FarmerMarketDemandOpportunity> opportunities;
  final int totalDemand;
  final String filter;
  final ValueChanged<String> onFilter;
  final bool Function(FarmerMarketDemandOpportunity item) matches;
  final VoidCallback onOpenDemand;
  final VoidCallback onRefresh;

  const _FarmerEliteDemandPanel({
    required this.desktop,
    required this.opportunities,
    required this.totalDemand,
    required this.filter,
    required this.onFilter,
    required this.matches,
    required this.onOpenDemand,
    required this.onRefresh,
  });

  @override
  Widget build(BuildContext context) {
    final featured = opportunities.isEmpty ? null : opportunities.first;

    return _FarmerElitePanelShell(
      padding: EdgeInsets.all(desktop ? 14 : 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _FarmerElitePanelHeader(
            icon: Icons.bar_chart_rounded,
            title: 'Produce in Demand',
            subtitle: desktop
                ? 'Real demand. Real opportunities. Supply what Jamaica needs.'
                : 'Real demand. Real opportunities.',
            actionLabel: desktop ? 'View all demand' : 'View all',
            onAction: onOpenDemand,
            compact: !desktop,
          ),
          SizedBox(height: desktop ? 10 : 8),
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: [
                _FarmerEliteFilterPill(
                  label: 'All ($totalDemand)',
                  selected: filter == 'All',
                  onTap: () => onFilter('All'),
                ),
                const SizedBox(width: 7),
                _FarmerEliteFilterPill(
                  label: 'Urgent',
                  selected: filter == 'Urgent',
                  icon: Icons.circle,
                  iconColor: FarmColors.danger,
                  onTap: () => onFilter('Urgent'),
                ),
                const SizedBox(width: 7),
                _FarmerEliteFilterPill(
                  label: 'This week',
                  selected: filter == 'This week',
                  icon: Icons.calendar_today_outlined,
                  onTap: () => onFilter('This week'),
                ),
                const SizedBox(width: 7),
                _FarmerEliteFilterPill(
                  label: 'My crops',
                  selected: filter == 'My crops',
                  icon: Icons.eco_outlined,
                  onTap: () => onFilter('My crops'),
                ),
                const SizedBox(width: 7),
                _FarmerEliteFilterPill(
                  label: 'Best match',
                  selected: filter == 'Best match',
                  icon: Icons.sell_outlined,
                  onTap: () => onFilter('Best match'),
                ),
              ],
            ),
          ),
          SizedBox(height: desktop ? 12 : 10),
          if (featured == null)
            _FarmerEliteEmptyDemand(onOpenDemand: onOpenDemand)
          else
            _FarmerEliteFeaturedDemandCard(
              desktop: desktop,
              opportunity: featured,
              matchesMySupply: matches(featured),
              onRefresh: onRefresh,
            ),
        ],
      ),
    );
  }
