class _FarmerEliteFeaturedDemandCard extends StatefulWidget {
  final bool desktop;
  final FarmerMarketDemandOpportunity opportunity;
  final bool matchesMySupply;
  final VoidCallback onRefresh;

  const _FarmerEliteFeaturedDemandCard({
    required this.desktop,
    required this.opportunity,
    required this.matchesMySupply,
    required this.onRefresh,
  });

  @override
  State<_FarmerEliteFeaturedDemandCard> createState() =>
      _FarmerEliteFeaturedDemandCardState();
}

class _FarmerEliteFeaturedDemandCardState
    extends State<_FarmerEliteFeaturedDemandCard> {
  bool get urgent =>
      widget.opportunity.demandSignal == 'urgent' ||
      widget.opportunity.demandSignal == 'committed_need';

  Future<void> _supply() async {
    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _FarmerDemandSupplySheet(
        demand: widget.opportunity,
      ),
    );

    if (!mounted || saved != true) return;
    widget.onRefresh();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${widget.opportunity.productName} supply reported. HPJ can now review the match.',
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final item = widget.opportunity;
    final date = item.nextNeedBy == null
        ? 'Flexible timing'
        : 'Needed by ${_farmerPartnerDate(item.nextNeedBy)}';

    final reasons = <String>[
      urgent ? 'High priority buyer need' : 'High buyer interest',
      widget.matchesMySupply
          ? 'Matches your active supply'
          : 'Open supply opportunity',
      'Current HPJ supply gap',
      'Live Jamaica buyer demand',
    ];

    return Container(
      padding: EdgeInsets.all(widget.desktop ? 12 : 10),
      decoration: BoxDecoration(
        color: const Color(0xFFFBFCF9),
        borderRadius: BorderRadius.circular(15),
        border: Border.all(color: const Color(0xFFDCE5D8)),
      ),
      child: widget.desktop
          ? Row(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                SizedBox(
                  width: 145,
                  child: _FarmerEliteDemandImage(
                    productName: item.productName,
                    urgent: urgent,
                  ),
                ),
                const SizedBox(width: 14),
                Expanded(
                  flex: 4,
                  child: _FarmerEliteDemandCopy(
                    item: item,
                    matchesMySupply: widget.matchesMySupply,
                    date: date,
                  ),
                ),
                const SizedBox(width: 14),
                Expanded(
                  flex: 4,
                  child: _FarmerEliteWhyDemand(
                    reasons: reasons,
                    onTap: _supply,
                    buttonLabel: 'View details',
                  ),
                ),
              ],
            )
          : Column(
              children: [
                Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    SizedBox(
                      width: 118,
                      height: 128,
                      child: _FarmerEliteDemandImage(
                        productName: item.productName,
                        urgent: urgent,
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: _FarmerEliteDemandCopy(
                        item: item,
                        matchesMySupply: widget.matchesMySupply,
                        date: date,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 10),
                _FarmerEliteWhyDemand(
                  reasons: reasons,
                  onTap: _supply,
                  buttonLabel: 'View demand',
                ),
              ],
            ),
    );
  }
}

