class _FarmerEliteActivityPanel extends StatelessWidget {
  final bool desktop;
  final List<_FarmerTodayNotification> notifications;
  final List<FarmerMarketDemandOpportunity> opportunities;
  final bool Function(FarmerMarketDemandOpportunity item) matches;
  final VoidCallback onSeeAll;

  const _FarmerEliteActivityPanel({
    required this.desktop,
    required this.notifications,
    required this.opportunities,
    required this.matches,
    required this.onSeeAll,
  });

  @override
  Widget build(BuildContext context) {
    final rows = <_FarmerEliteActivityData>[];

    for (final item in opportunities.where(matches).take(1)) {
      rows.add(
        _FarmerEliteActivityData(
          icon: Icons.link_rounded,
          title: 'New demand match for ${item.productName}',
          helper: 'Live HPJ demand',
          soft: const Color(0xFFFFF4D8),
          accent: const Color(0xFFB37A00),
        ),
      );
    }

    for (final n in notifications.take(3)) {
      rows.add(
        _FarmerEliteActivityData(
          icon: n.icon,
          title: n.title,
          helper: n.message,
          soft: const Color(0xFFF0F4EF),
          accent: FarmColors.deepGreen,
        ),
      );
    }

    if (rows.isEmpty) {
      rows.add(
        const _FarmerEliteActivityData(
          icon: Icons.check_circle_outline_rounded,
          title: 'You are all caught up',
          helper: 'New farmer activity will appear here.',
          soft: Color(0xFFEAF5E7),
          accent: FarmColors.success,
        ),
      );
    }

    return _FarmerElitePanelShell(
      padding: EdgeInsets.all(desktop ? 13 : 11),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _FarmerElitePanelHeader(
            icon: Icons.schedule_rounded,
            title: 'Recent Activity',
            subtitle: desktop ? 'Your latest farmer updates' : 'Your latest updates',
            onAction: onSeeAll,
            compact: !desktop,
          ),
          SizedBox(height: desktop ? 8 : 6),
          for (var i = 0; i < rows.take(desktop ? 4 : 5).length; i++) ...[
            _FarmerEliteActivityRow(
              data: rows[i],
              compact: !desktop,
            ),
            if (i != rows.take(desktop ? 4 : 5).length - 1)
              const Divider(height: 10, color: Color(0xFFE5EAE2)),
          ],
        ],
      ),
    );
  }
}

