class _FarmerEliteAlertsPanel extends StatelessWidget {
  final bool desktop;
  final List<_FarmerTodayNotification> notifications;
  final int reviewCount;
  final VoidCallback onOpenSupply;
  final VoidCallback onOpenDemand;

  const _FarmerEliteAlertsPanel({
    required this.desktop,
    required this.notifications,
    required this.reviewCount,
    required this.onOpenSupply,
    required this.onOpenDemand,
  });

  bool _looksDemandRelated(_FarmerTodayNotification item) {
    final title = item.title.toLowerCase();
    final message = item.message.toLowerCase();
    return title.contains('demand') ||
        title.contains('buyer') ||
        title.contains('match') ||
        title.contains('opportunity') ||
        message.contains('demand') ||
        message.contains('buyer') ||
        message.contains('match') ||
        message.contains('opportunity');
  }

  @override
  Widget build(BuildContext context) {
    Widget actionRow({
      required IconData icon,
      required Color soft,
      required Color accent,
      required String title,
      required String helper,
      required String buttonText,
      required VoidCallback onTap,
    }) {
      return Container(
        padding: const EdgeInsets.fromLTRB(12, 11, 10, 11),
        decoration: BoxDecoration(
          color: const Color(0xFFFAFCF9),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: const Color(0xFFE2E9E0)),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              width: desktop ? 42 : 38,
              height: desktop ? 42 : 38,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: soft,
                borderRadius: BorderRadius.circular(12),
              ),
              child: Icon(
                icon,
                size: desktop ? 20 : 18,
                color: accent,
              ),
            ),
            const SizedBox(width: 10),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      color: FarmColors.ink,
                      fontSize: desktop ? 12.2 : 11,
                      height: 1.15,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 3),
                  Text(
                    helper,
                    maxLines: 3,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: desktop ? 10 : 8.9,
                      height: 1.3,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(width: 8),
            FilledButton(
              onPressed: onTap,
              style: FilledButton.styleFrom(
                elevation: 0,
                padding: const EdgeInsets.symmetric(
                  horizontal: 10,
                  vertical: 0,
                ),
                minimumSize: const Size(72, 34),
                backgroundColor: const Color(0xFFF2F7F1),
                foregroundColor: FarmColors.deepGreen,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(11),
                ),
                textStyle: TextStyle(
                  fontSize: desktop ? 10.2 : 9.1,
                  fontWeight: FontWeight.w900,
                ),
              ),
              child: Text(buttonText),
            ),
          ],
        ),
      );
    }

    final rows = <Widget>[];

    if (reviewCount > 0) {
      rows.add(
        actionRow(
          icon: Icons.eco_outlined,
          soft: const Color(0xFFFFF3D9),
          accent: const Color(0xFFBC8208),
          title:
              '$reviewCount produce update${reviewCount == 1 ? '' : 's'} needed',
          helper:
              'Open My Supply to refresh quantity, status or ready date so matching stays accurate.',
          buttonText: 'Open',
          onTap: onOpenSupply,
        ),
      );
    }

    final uniqueNotifications = <String>{};
    for (final item in notifications) {
      final key =
          '${item.title.trim().toLowerCase()}|${item.message.trim().toLowerCase()}';
      if (!uniqueNotifications.add(key)) continue;

      final demandRelated = _looksDemandRelated(item);
      rows.add(
        actionRow(
          icon: item.icon,
          soft: demandRelated
              ? const Color(0xFFE8F5EB)
              : const Color(0xFFF1F5EE),
          accent: demandRelated
              ? FarmColors.primary
              : const Color(0xFF607066),
          title: item.title,
          helper: item.message,
          buttonText: demandRelated ? 'Market' : 'Supply',
          onTap: demandRelated ? onOpenDemand : onOpenSupply,
        ),
      );

      if (rows.length >= 3) break;
    }

    if (rows.isEmpty) {
      rows.add(
        Container(
          width: double.infinity,
          padding: const EdgeInsets.fromLTRB(14, 14, 14, 14),
          decoration: BoxDecoration(
            color: const Color(0xFFFAFCF9),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: const Color(0xFFE2E9E0)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Container(
                    width: desktop ? 42 : 38,
                    height: desktop ? 42 : 38,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: const Color(0xFFEAF5E9),
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: const Icon(
                      Icons.check_circle_outline_rounded,
                      color: FarmColors.primary,
                      size: 19,
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Text(
                      'You are up to date',
                      style: TextStyle(
                        color: FarmColors.ink,
                        fontSize: desktop ? 12.5 : 11.2,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              Text(
                'There are no urgent farmer alerts right now. You can still check buyer demand for new opportunities.',
                style: TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: desktop ? 10.2 : 9,
                  height: 1.35,
                  fontWeight: FontWeight.w600,
                ),
              ),
              const SizedBox(height: 10),
              Align(
                alignment: Alignment.centerLeft,
                child: FilledButton.icon(
                  onPressed: onOpenDemand,
                  icon: const Icon(Icons.insights_outlined, size: 17),
                  label: const Text('View demand'),
                  style: FilledButton.styleFrom(
                    elevation: 0,
                    backgroundColor: const Color(0xFFEAF5E9),
                    foregroundColor: FarmColors.deepGreen,
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(11),
                    ),
                    textStyle: const TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      );
    }

    final visibleCount = rows.length > 3 ? 3 : rows.length;

    return FarmCard(
      padding: const EdgeInsets.fromLTRB(14, 13, 14, 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(
                Icons.notifications_active_outlined,
                size: 18,
                color: FarmColors.primary,
              ),
              const SizedBox(width: 8),
              const Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Notices & Updates',
                      style: TextStyle(
                        color: FarmColors.ink,
                        fontSize: 15.5,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    SizedBox(height: 2),
                    Text(
                      'Important HPJ notices and actions for your farm',
                      style: TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 9.2,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
              if (visibleCount > 0)
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 5,
                  ),
                  decoration: BoxDecoration(
                    color: const Color(0xFFEAF5E9),
                    borderRadius: BorderRadius.circular(999),
                  ),
                  child: Text(
                    '$visibleCount',
                    style: const TextStyle(
                      color: FarmColors.deepGreen,
                      fontSize: 8.8,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
            ],
          ),
          const SizedBox(height: 11),
          for (var i = 0; i < rows.length; i++) ...[
            rows[i],
            if (i != rows.length - 1) const SizedBox(height: 9),
          ],
        ],
      ),
    );
  }
}


