    required this.supplyReviewCount,
    required this.opportunities,
    required this.matchingDemandKeys,
    required this.upcomingCollectionCount,
    required this.onOpenSupply,
    required this.onOpenDemand,
    required this.onOpenCollections,
    required this.onRefresh,
  });

  @override
  State<_FarmerWebDemandFirstHome> createState() =>
      _FarmerWebDemandFirstHomeState();
}

class _FarmerWebDemandFirstHomeState
    extends State<_FarmerWebDemandFirstHome> {
  String filter = 'All';

  bool _isUrgent(FarmerMarketDemandOpportunity item) {
    return item.demandSignal == 'urgent' ||
        item.demandSignal == 'committed_need';
  }

  bool _isThisWeek(FarmerMarketDemandOpportunity item) {
    final date = item.nextNeedBy;
    if (date == null) return false;
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final days = DateTime(
      date.year,
      date.month,
      date.day,
    ).difference(today).inDays;
    return days >= 0 && days <= 7;
  }

  bool _matchesMyCrops(FarmerMarketDemandOpportunity item) {
    return widget.matchingDemandKeys.contains(
      hpjFarmerDemandWatchKey(
        item.productName,
        item.unit,
      ),
    );
  }

  List<FarmerMarketDemandOpportunity> get filteredOpportunities {
    final rows =
        List<FarmerMarketDemandOpportunity>.from(widget.opportunities);

    switch (filter) {
      case 'Urgent':
        return rows.where(_isUrgent).toList();

      case 'This week':
        return rows.where(_isThisWeek).toList();

      case 'My crops':
        return rows.where(_matchesMyCrops).toList();

      case 'Best match':
        rows.sort((a, b) {
          final aMatch = _matchesMyCrops(a) ? 1 : 0;
          final bMatch = _matchesMyCrops(b) ? 1 : 0;

          if (aMatch != bMatch) {
            return bMatch.compareTo(aMatch);
          }

          final aUrgent = _isUrgent(a) ? 1 : 0;
          final bUrgent = _isUrgent(b) ? 1 : 0;

          if (aUrgent != bUrgent) {
            return bUrgent.compareTo(aUrgent);
          }

          return b.opportunityGap.compareTo(a.opportunityGap);
        });
        return rows;

      case 'All':
      default:
        return rows;
    }
  }

  int get urgentCount =>
      widget.opportunities.where(_isUrgent).length;

  FarmerMarketDemandOpportunity? get shortageAlert {
    final urgent = widget.opportunities
        .where(_isUrgent)
        .toList()
      ..sort(
        (a, b) =>
            b.opportunityGap.compareTo(a.opportunityGap),
      );

    if (urgent.isNotEmpty) return urgent.first;

    final all =
        List<FarmerMarketDemandOpportunity>.from(
      widget.opportunities,
    )..sort(
            (a, b) =>
                b.opportunityGap.compareTo(a.opportunityGap),
          );

    return all.isEmpty ? null : all.first;
  }

  FarmerMarketDemandOpportunity? get bestOpportunity {
    final rows =
        List<FarmerMarketDemandOpportunity>.from(
      widget.opportunities,
    )..sort((a, b) {
            final aMatch = _matchesMyCrops(a) ? 1 : 0;
            final bMatch = _matchesMyCrops(b) ? 1 : 0;
            if (aMatch != bMatch) {
              return bMatch.compareTo(aMatch);
            }
            return b.opportunityGap.compareTo(a.opportunityGap);
          });

    return rows.isEmpty ? null : rows.first;
  }

  String get trendingNames {
    final names = <String>[];
    for (final item in widget.opportunities) {
      final clean = item.productName.trim();
      if (clean.isEmpty) continue;
      if (names.any(
        (name) =>
            name.toLowerCase() == clean.toLowerCase(),
      )) {
        continue;
      }
      names.add(clean);
      if (names.length == 3) break;
    }
    return names.isEmpty
        ? 'Demand updates will appear here'
        : names.join(', ');
  }

  @override
  Widget build(BuildContext context) {
    final rows = filteredOpportunities;

    return RefreshIndicator(
      onRefresh: () async {
        widget.onRefresh();
        await Future<void>.delayed(
          const Duration(milliseconds: 120),
        );
      },
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        padding: const EdgeInsets.fromLTRB(
          16,
          14,
          16,
          86,
        ),
        children: [
          _FarmerWebOpportunityHero(
            profile: widget.profile,
          ),
          const SizedBox(height: 14),
          _FarmerWebKpiStrip(
            openDemandCount: widget.opportunities.length,
            urgentCount: urgentCount,
            matchingCropCount:
                widget.matchingDemandKeys.length,
            upcomingCollectionCount:
                widget.upcomingCollectionCount,
            onOpenDemand: widget.onOpenDemand,
            onOpenCollections: widget.onOpenCollections,
            onOpenSupply: widget.onOpenSupply,
          ),
          const SizedBox(height: 15),
          _FarmerWebProduceDemandSection(
            rows: rows,
            totalCount: widget.opportunities.length,
            filter: filter,
            onFilter: (value) {
              setState(() => filter = value);
            },
            matchesMyCrops: _matchesMyCrops,
            onOpenDemand: widget.onOpenDemand,
            onSupplied: widget.onRefresh,
          ),
          const SizedBox(height: 14),
          LayoutBuilder(
            builder: (context, constraints) {
              final stack =
                  constraints.maxWidth < 1040;

              final insights = _FarmerWebDemandInsights(
                trendingNames: trendingNames,
                shortageAlert: shortageAlert,
                bestOpportunity: bestOpportunity,
                onOpenDemand: widget.onOpenDemand,
              );

              final cta = _FarmerWebSupplyFutureCard(
                activeSupplyCount:
                    widget.activeSupplyCount,
                reviewCount:
                    widget.supplyReviewCount,
                onTap: widget.onOpenSupply,
              );

              if (stack) {
                return Column(
                  children: [
                    insights,
                    const SizedBox(height: 12),
                    cta,
                  ],
                );
              }

              return Row(
                crossAxisAlignment:
                    CrossAxisAlignment.start,
                children: [
                  Expanded(child: insights),
                  const SizedBox(width: 12),
                  SizedBox(
                    width: 310,
                    child: cta,
                  ),
                ],
              );
            },
          ),
        ],
      ),
    );
  }
}

