      child: InkWell(
        borderRadius: BorderRadius.circular(999),
        onTap: onTap,
        child: Container(
          padding: const EdgeInsets.symmetric(
            horizontal: 15,
            vertical: 9,
          ),
          decoration: BoxDecoration(
            borderRadius:
                BorderRadius.circular(999),
            border: Border.all(
              color: selected
                  ? FarmColors.primary
                  : HpjWebUi.border,
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              if (dotColor != null) ...[
                Container(
                  width: 7,
                  height: 7,
                  decoration: BoxDecoration(
                    color: dotColor,
                    shape: BoxShape.circle,
                  ),
                ),
                const SizedBox(width: 7),
              ] else if (icon != null) ...[
                Icon(
                  icon,
                  color: foreground,
                  size: 14,
                ),
                const SizedBox(width: 6),
              ],
              Text(
                count == null
                    ? label
                    : '$label ($count)',
                style: TextStyle(
                  color: foreground,
                  fontSize: 9.8,
                  fontWeight:
                      FontWeight.w900,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _FarmerWebDemandCard
    extends StatefulWidget {
  final FarmerMarketDemandOpportunity opportunity;
  final bool matchesMySupply;
  final VoidCallback onSupplied;

  const _FarmerWebDemandCard({
    required this.opportunity,
    required this.matchesMySupply,
    required this.onSupplied,
  });

  @override
  State<_FarmerWebDemandCard> createState() =>
      _FarmerWebDemandCardState();
}

class _FarmerWebDemandCardState
    extends State<_FarmerWebDemandCard> {
  bool get _urgent {
    return widget.opportunity.demandSignal ==
            'urgent' ||
        widget.opportunity.demandSignal ==
            'committed_need';
  }

  Future<void> _supply() async {
    final saved =
        await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _FarmerDemandSupplySheet(
        demand: widget.opportunity,
      ),
    );

    if (!mounted || saved != true) return;

    widget.onSupplied();

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${widget.opportunity.productName} supply reported. HPJ can now review the match.',
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final item = widget.opportunity;
    final badgeText = _urgent
        ? 'URGENT'
        : item.demandSignal == 'opportunity'
            ? 'HIGH DEMAND'
            : 'ACTIVE';

    final badgeColor = _urgent
        ? FarmColors.danger
        : item.demandSignal == 'opportunity'
            ? const Color(0xFFF2B516)
            : const Color(0xFF38A65A);

    final needDate = item.nextNeedBy == null
        ? 'Flexible timing'
        : 'Needed by ${_farmerPartnerDate(item.nextNeedBy)}';

    return Container(
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(15),
        border: Border.all(
          color: HpjWebUi.border,
        ),
      ),
      child: Column(
        crossAxisAlignment:
            CrossAxisAlignment.start,
        children: [
          SizedBox(
            height: 115,
            child: Stack(
              children: [
                Positioned.fill(
                  child: Center(
                    child: HpjProductThumb(
                      productName:
                          item.productName,
                      size: 112,
                      radius: 12,
                    ),
                  ),
                ),
                Positioned(
                  left: 10,
                  top: 10,
                  child: Container(
                    padding:
                        const EdgeInsets.symmetric(
                      horizontal: 9,
                      vertical: 5,
                    ),
                    decoration: BoxDecoration(
                      color: badgeColor,
                      borderRadius:
                          BorderRadius.circular(
                        999,
                      ),
                    ),
                    child: Text(
                      badgeText,
                      style: TextStyle(
                        color: _urgent
                            ? Colors.white
                            : FarmColors.deepGreen,
                        fontSize: 8.2,
                        fontWeight:
                            FontWeight.w900,
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
          Expanded(
            child: Padding(
              padding:
                  const EdgeInsets.fromLTRB(
                11,
                8,
                11,
                11,
              ),
              child: Column(
                crossAxisAlignment:
                    CrossAxisAlignment.start,
                children: [
                  Text(
                    item.productName,
                    maxLines: 1,
                    overflow:
                        TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: FarmColors.ink,
                      fontSize: 12.5,
                      fontWeight:
                          FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 5),
                  Text(
                    '${_farmerPartnerNumber(item.opportunityGap)} ${item.unit} needed',
                    maxLines: 1,
                    overflow:
                        TextOverflow.ellipsis,
                    style: const TextStyle(
                      color:
                          FarmColors.deepGreen,
                      fontSize: 11.2,
                      fontWeight:
                          FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 6),
                  if (widget.matchesMySupply)
                    const Row(
                      children: [
                        Icon(
                          Icons.check_circle_rounded,
                          color:
                              FarmColors.success,
                          size: 13,
                        ),
                        SizedBox(width: 5),
                        Expanded(
                          child: Text(
                            'Matches your supply',
                            maxLines: 1,
                            overflow:
                                TextOverflow
                                    .ellipsis,
                            style: TextStyle(
                              color: FarmColors
                                  .success,
                              fontSize: 8.8,
                              fontWeight:
                                  FontWeight
                                      .w800,
                            ),
                          ),
                        ),
                      ],
                    )
                  else
                    const Row(
                      children: [
                        Icon(
                          Icons.groups_outlined,
                          color: FarmColors
                              .mutedText,
                          size: 13,
                        ),
                        SizedBox(width: 5),
                        Expanded(
                          child: Text(
                            'HPJ buyer demand',
                            maxLines: 1,
                            overflow:
                                TextOverflow
                                    .ellipsis,
                            style: TextStyle(
                              color: FarmColors
                                  .mutedText,
                              fontSize: 8.8,
                              fontWeight:
                                  FontWeight
                                      .w700,
                            ),
                          ),
                        ),
                      ],
                    ),
                  const SizedBox(height: 4),
                  Row(
                    children: [
                      const Icon(
                        Icons
                            .calendar_today_outlined,
                        color: FarmColors
                            .mutedText,
                        size: 12,
                      ),
                      const SizedBox(width: 5),
                      Expanded(
                        child: Text(
                          needDate,
                          maxLines: 1,
                          overflow:
                              TextOverflow
                                  .ellipsis,
                          style: const TextStyle(
                            color: FarmColors
                                .mutedText,
                            fontSize: 8.5,
                            fontWeight:
                                FontWeight
                                    .w600,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const Spacer(),
                  SizedBox(
                    width: double.infinity,
                    height: 35,
                    child: FilledButton.icon(
                      onPressed:
                          item.opportunityGap >
