class _FarmerBusinessSnapshotCard extends StatelessWidget {
  final String farmName;
  final double sales30;
  final double sales90;
  final int supplyTransactions30;
  final int confirmedCropCount;
  final int opportunityCount;
  final int upcomingCollections;
  final FarmerMarketDemandOpportunity? topOpportunity;
  final VoidCallback onOpenDemand;
  final VoidCallback onOpenSupply;
  final VoidCallback onOpenPayments;

  const _FarmerBusinessSnapshotCard({
    required this.farmName,
    required this.sales30,
    required this.sales90,
    required this.supplyTransactions30,
    required this.confirmedCropCount,
    required this.opportunityCount,
    required this.upcomingCollections,
    required this.topOpportunity,
    required this.onOpenDemand,
    required this.onOpenSupply,
    required this.onOpenPayments,
  });

  @override
  Widget build(BuildContext context) {
    return FarmCard(
      padding: const EdgeInsets.fromLTRB(14, 13, 14, 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Expanded(
                child: Text(
                  'Business status',
                  style: TextStyle(
                    color: FarmColors.ink,
                    fontSize: 14,
                    fontWeight: FontWeight.w800,
                  ),
                ),
              ),
              Icon(
                Icons.lock_outline_rounded,
                size: 15,
                color: FarmColors.mutedText.withOpacity(.75),
              ),
            ],
          ),
          const SizedBox(height: 11),
          LayoutBuilder(
            builder: (context, constraints) {
              final twoColumns = constraints.maxWidth < 310;
              final itemWidth = twoColumns
                  ? (constraints.maxWidth - 8) / 2
                  : (constraints.maxWidth - 16) / 3;

              return Wrap(
                spacing: 8,
                runSpacing: 8,
                children: [
                  SizedBox(
                    width: itemWidth,
                    child: _FarmerBusinessMetric(
                      label: 'Sales',
                      value: formatJmd(sales30),
                      note:
                          '$supplyTransactions30 transaction${supplyTransactions30 == 1 ? '' : 's'}',
                      onTap: onOpenPayments,
                    ),
                  ),
                  SizedBox(
                    width: itemWidth,
                    child: _FarmerBusinessMetric(
                      label: 'Market',
                      value: '$opportunityCount',
                      note: opportunityCount == 0
                          ? 'No open gap'
                          : 'For your crops',
                      onTap: onOpenDemand,
                    ),
                  ),
                  SizedBox(
                    width: itemWidth,
                    child: _FarmerBusinessMetric(
                      label: 'Confirmed',
                      value: '$confirmedCropCount',
                      note: 'Crops',
                      onTap: onOpenSupply,
                    ),
                  ),
                ],
              );
            },
          ),
          const SizedBox(height: 9),
          Text(
            '$upcomingCollections upcoming collection${upcomingCollections == 1 ? '' : 's'} • 90-day sales ${formatJmd(sales90)}',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              color: FarmColors.mutedText,
              fontSize: 9.8,
              fontWeight: FontWeight.w500,
            ),
          ),
        ],
      ),
    );
  }
}



