                    ]),
                    const SizedBox(height: 8),
                    TextField(
                      controller: noteController,
                      enabled: !saving && !deal.isApplied,
                      maxLines: 2,
                      decoration: const InputDecoration(labelText: 'Deal note'),
                    ),
                    const SizedBox(height: 13),
                    if (deal.isAgreed && !deal.isApplied)
                      SizedBox(
