class _HpjFarmerDemandBoardMvpScreenState
    extends State<HpjFarmerDemandBoardMvpScreen> {
  late Future<_HpjFarmerDemandMvpSnapshot> _future;
  late final PageController _pageController;

  static const List<_HpjFarmerDemandMvpCategory> _categories = [
    _HpjFarmerDemandMvpCategory(
      key: 'all',
      title: 'All',
      subtitle: '',
      icon: Icons.grid_view_rounded,
      accent: Color(0xFF2E7D4F),
      soft: Color(0xFFEAF5E9),
    ),
    _HpjFarmerDemandMvpCategory(
      key: 'needs_supply',
      title: 'Open',
      subtitle: '',
      icon: Icons.campaign_outlined,
      accent: Color(0xFFB56A0D),
      soft: Color(0xFFFFF3DD),
    ),
    _HpjFarmerDemandMvpCategory(
      key: 'my_supply',
      title: 'Matches Me',
      subtitle: '',
      icon: Icons.eco_outlined,
      accent: Color(0xFF1F7A45),
      soft: Color(0xFFE8F3E7),
    ),
    _HpjFarmerDemandMvpCategory(
      key: 'covered',
      title: 'Covered',
      subtitle: '',
      icon: Icons.verified_rounded,
      accent: Color(0xFF287D67),
      soft: Color(0xFFE8F6F1),
    ),
  ];

  int _selectedIndex = 0;

  @override
  void initState() {
    super.initState();
    _pageController = PageController(viewportFraction: 0.90);
    _future = _load();
  }

  @override
  void dispose() {
    _pageController.dispose();
    super.dispose();
  }

  Future<_HpjFarmerDemandMvpSnapshot> _load() async {
    Future<List<FarmerMarketDemandOpportunity>> loadDemand() async {
      try {
        return await fetchFarmerMarketDemandBoard(60);
      } catch (error) {
        farmDebugLog('Farmer Demand MVP — demand unavailable: $error');
        return <FarmerMarketDemandOpportunity>[];
      }
    }

    Future<List<FarmerSupplyForecast>> loadSupply() async {
      try {
        return await fetchFarmerSupplyForecasts(widget.profile.id);
      } catch (error) {
        farmDebugLog('Farmer Demand MVP — supply unavailable: $error');
        return <FarmerSupplyForecast>[];
      }
    }

    final results = await Future.wait<dynamic>([
      loadDemand(),
      loadSupply(),
    ]);

    return _HpjFarmerDemandMvpSnapshot(
      opportunities: results[0] as List<FarmerMarketDemandOpportunity>,
      supplies: results[1] as List<FarmerSupplyForecast>,
    );
  }

  Future<void> _refresh() async {
    final next = _load();
    if (mounted) {
      setState(() => _future = next);
    }
    await next;
  }

  Set<String> _matchingDemandKeys(List<FarmerSupplyForecast> supplies) {
    return supplies
        .where((s) => s.isActive)
        .map(
          (s) => hpjFarmerDemandWatchKey(
            s.cropName,
            s.unit,
          ),
        )
        .toSet();
  }

  bool _hasMarketDemand(FarmerMarketDemandOpportunity item) =>
      item.visibleDemand > 0.0001;

  String _cropDemandKey(FarmerMarketDemandOpportunity item) =>
      hpjWatchKeyPart(item.productName);

  int _demandPriority(FarmerMarketDemandOpportunity item) {
    var score = 0;
    if (!_isCovered(item)) score += 100000;
    if (item.opportunityGap > 0.0001) score += 50000;
    if (item.demandSignal == 'committed_need') score += 30000;
    if (item.demandSignal == 'urgent') score += 25000;
    if (item.demandSignal == 'opportunity') score += 15000;
    if (_isNeededSoon(item)) score += 10000;
    score += item.visibleDemand.clamp(0, 9999).round();
    return score;
  }

  List<FarmerMarketDemandOpportunity> _uniqueMarketRows(
    List<FarmerMarketDemandOpportunity> opportunities,
  ) {
    final bestByCrop = <String, FarmerMarketDemandOpportunity>{};

    for (final item in opportunities) {
      // The farmer Market page is for real buyer demand. Supply-only rows from
      // the demand-board RPC belong in My Crops, not as fake "Covered" needs.
      if (!_hasMarketDemand(item)) continue;

      final key = _cropDemandKey(item);
      if (key.isEmpty) continue;

      final current = bestByCrop[key];
      if (current == null) {
        bestByCrop[key] = item;
        continue;
      }

      final itemScore = _demandPriority(item);
      final currentScore = _demandPriority(current);
      if (itemScore > currentScore) {
        bestByCrop[key] = item;
      } else if (itemScore == currentScore) {
        final itemDate = item.nextNeedBy ?? DateTime(2999);
        final currentDate = current.nextNeedBy ?? DateTime(2999);
        if (itemDate.isBefore(currentDate)) {
          bestByCrop[key] = item;
        }
      }
    }

    final rows = bestByCrop.values.toList(growable: false);
    rows.sort((a, b) {
      final byPriority = _demandPriority(b).compareTo(_demandPriority(a));
      if (byPriority != 0) return byPriority;

      final aDate = a.nextNeedBy ?? DateTime(2999);
      final bDate = b.nextNeedBy ?? DateTime(2999);
      final byDate = aDate.compareTo(bDate);
      if (byDate != 0) return byDate;

      return a.productName.toLowerCase().compareTo(
            b.productName.toLowerCase(),
          );
    });
    return rows;
  }

  bool _isNeededSoon(FarmerMarketDemandOpportunity item) {
    if (item.demandSignal == 'urgent' || item.demandSignal == 'committed_need') {
      return true;
    }

    final date = item.nextNeedBy;
    if (date == null) return false;
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    final days = DateTime(date.year, date.month, date.day).difference(today).inDays;
    return days >= 0 && days <= 7;
  }

  bool _matchesMySupply(
    FarmerMarketDemandOpportunity item,
    Set<String> matchingKeys,
  ) {
    final exact = hpjFarmerDemandWatchKey(
      item.productName,
      item.unit,
    );
    if (matchingKeys.contains(exact)) return true;

    // Home/Market is crop-first. If a farmer grows Ackee, show Ackee once even
    // when buyer demand is expressed in a different unit (each vs dozen).
    final cropPrefix = '${hpjWatchKeyPart(item.productName)}|';
    return matchingKeys.any((key) => key.startsWith(cropPrefix));
  }

  bool _isCovered(FarmerMarketDemandOpportunity item) {
    // A supply-only row (visible demand = 0) is not a market need and must not
    // appear as "Covered" on the demand page.
    if (!_hasMarketDemand(item)) return false;
    return item.demandSignal == 'covered_by_you' ||
        item.opportunityGap <= 0.0001;
  }

  bool _needsSupply(
    FarmerMarketDemandOpportunity item,
    Set<String> matchingKeys,
  ) {
    return !_matchesMySupply(item, matchingKeys) && !_isCovered(item);
  }

  List<FarmerMarketDemandOpportunity> _categoryRows(
    String key,
    List<FarmerMarketDemandOpportunity> opportunities,
    Set<String> matchingKeys,
  ) {
    // One market card per crop. If HPJ has Ackee demand in multiple units or
    // dates, the strongest/current row represents Ackee on this overview.
    final rows = _uniqueMarketRows(opportunities);

    switch (key) {
      case 'all':
        return rows;

      case 'needs_supply':
        return rows
            .where(
              (item) =>
                  !_isCovered(item) &&
                  item.opportunityGap > 0.0001,
            )
            .toList(growable: false);

      case 'my_supply':
        return rows
            .where(
              (item) => _matchesMySupply(item, matchingKeys),
            )
            .toList(growable: false);

      case 'covered':
        return rows.where(_isCovered).toList(growable: false);

      default:
        return rows;
    }
  }

  String _dateLabel(DateTime? value) {
    if (value == null) return 'Timing to be confirmed';
    const months = <String>[
      'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
      'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
    ];
    return '${value.day} ${months[value.month - 1]} ${value.year}';
  }

  String _badgeLabel(FarmerMarketDemandOpportunity item) {
    if (_isCovered(item)) return 'Covered';
    if (_isNeededSoon(item)) return 'Needed soon';
    if (item.demandSignal == 'committed_need') return 'Committed';
    if (item.demandSignal == 'steady') return 'Steady';
    return 'Open need';
  }

  Color _badgeColor(FarmerMarketDemandOpportunity item) {
    if (_isCovered(item)) return const Color(0xFF2E7D4F);
    if (_isNeededSoon(item)) return const Color(0xFF1F7A45);
    if (item.demandSignal == 'steady') return const Color(0xFFB58210);
    return const Color(0xFFB56A0D);
  }

  void _openDemandInfo(
    FarmerMarketDemandOpportunity item,
    bool matchesMySupply,
  ) {
    showModalBottomSheet<void>(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) {
        final badgeColor = _badgeColor(item);
        final hasGap = item.opportunityGap > 0;
        return Container(
          decoration: const BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
          ),
          child: SafeArea(
            top: false,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(18, 12, 18, 18),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Center(
                    child: Container(
                      width: 42,
                      height: 4,
                      decoration: BoxDecoration(
                        color: FarmColors.line,
                        borderRadius: BorderRadius.circular(99),
                      ),
                    ),
                  ),
                  const SizedBox(height: 16),
                  Row(
                    children: [
                      HpjProductThumb(
                        productName: item.productName,
                        size: 58,
                        radius: 16,
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              item.productName,
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontSize: 20,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 6),
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 10,
                                vertical: 6,
                              ),
                              decoration: BoxDecoration(
                                color: badgeColor.withOpacity(.12),
                                borderRadius: BorderRadius.circular(999),
                              ),
                              child: Text(
                                _badgeLabel(item),
                                style: TextStyle(
                                  color: badgeColor,
                                  fontSize: 10.5,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 16),
                  Text(
                    'This category shows the farmer-view MVP summary for the selected produce.',
                    style: const TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 11.5,
                      height: 1.35,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  const SizedBox(height: 14),
                  Row(
                    children: [
                      Expanded(
