  Widget _categorySummary(
    _HpjFarmerDemandMvpCategory category,
    List<FarmerMarketDemandOpportunity> rows,
    Set<String> matchingKeys,
  ) {
    final gapTotal = rows.fold<num>(0, (sum, item) => sum + item.opportunityGap);
    final marketNeedTotal = rows.fold<num>(0, (sum, item) => sum + item.visibleDemand);
    final matchingCount =
        rows.where((item) => _matchesMySupply(item, matchingKeys)).length;
    final coveredCount = rows.where(_isCovered).length;

    String helper;
    switch (category.key) {
      case 'needed_soon':
        helper =
            'Use this view to see the nearest opportunities first. Focus on demand with the highest current gap.';
        break;
      case 'my_supply':
        helper =
            'These items already match crops you reported. Review quantity, timing and unit to improve matching.';
        break;
      case 'needs_supply':
        helper =
            'These are the gaps HPJ still needs more farmers to help fill. Good place to spot expansion opportunities.';
        break;
      case 'covered':
        helper =
            'These opportunities are already linked or supplied, so you can review them without urgent action.';
        break;
      default:
        helper = '';
    }

    return FarmCard(
      padding: const EdgeInsets.fromLTRB(14, 13, 14, 13),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 38,
                height: 38,
                decoration: BoxDecoration(
                  color: category.soft,
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Icon(category.icon, color: category.accent),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      category.title,
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 15.2,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      category.subtitle,
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 9.2,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 9,
                  vertical: 6,
                ),
                decoration: BoxDecoration(
                  color: category.soft,
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Text(
                  '${rows.length}',
                  style: TextStyle(
                    color: category.accent,
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 11),
          Text(
            helper,
            style: const TextStyle(
              color: FarmColors.mutedText,
              fontSize: 10.2,
              height: 1.4,
              fontWeight: FontWeight.w600,
            ),
          ),
          const SizedBox(height: 12),
          Row(
            children: [
              Expanded(
                child: _mvpMetricTile(
                  'Gap',
                  gapTotal > 0 ? _farmerPartnerNumber(gapTotal.toDouble()) : '0',
                  Icons.add_chart_rounded,
                  const Color(0xFFFFF3DD),
                  const Color(0xFFB56A0D),
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: _mvpMetricTile(
                  'Market needs',
                  marketNeedTotal > 0 ? _farmerPartnerNumber(marketNeedTotal.toDouble()) : '0',
                  Icons.storefront_outlined,
                  const Color(0xFFEAF5E9),
                  FarmColors.primary,
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          Row(
            children: [
              Expanded(
                child: _mvpMetricTile(
                  'Matches',
                  '$matchingCount',
