  Widget _buildBody(
    BuildContext context,
    _HpjFarmerDemandMvpSnapshot snapshot,
  ) {
    final matchingKeys = _matchingDemandKeys(snapshot.supplies);
    final pages = _categories
        .map(
          (category) => _categoryRows(
            category.key,
            snapshot.opportunities,
            matchingKeys,
          ),
        )
        .toList(growable: false);

    if (_selectedIndex >= pages.length) {
      _selectedIndex = 0;
    }

    final selectedCategory = _categories[_selectedIndex];
    final selectedRows = pages[_selectedIndex];

    return RefreshIndicator(
      onRefresh: _refresh,
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        padding: EdgeInsets.fromLTRB(
          14,
          widget.embedded ? 12 : 16,
          14,
          90,
        ),
        children: [
          Row(
            children: [
              const Expanded(
                child: Text(
                  'Market',
                  style: TextStyle(
                    color: FarmColors.ink,
                    fontSize: 24,
                    fontWeight: FontWeight.w900,
                    letterSpacing: -.4,
                  ),
                ),
              ),
              IconButton(
                tooltip: 'Refresh market',
                onPressed: () => unawaited(_refresh()),
                icon: const Icon(
                  Icons.refresh_rounded,
                  color: FarmColors.primary,
                ),
              ),
            ],
          ),
          const SizedBox(height: 2),
          const Text(
            'Current buyer needs, one card per crop.',
            style: TextStyle(
              color: FarmColors.mutedText,
              fontSize: 10.5,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 12),

          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: List.generate(_categories.length, (index) {
                final category = _categories[index];
                final selected = _selectedIndex == index;
                final count = pages[index].length;

                return Padding(
                  padding: const EdgeInsets.only(right: 7),
                  child: ChoiceChip(
                    selected: selected,
                    onSelected: (_) => setState(() => _selectedIndex = index),
                    avatar: Icon(
                      category.icon,
                      size: 15,
                      color: selected
                          ? FarmColors.deepGreen
                          : FarmColors.mutedText,
                    ),
                    label: Text('${category.title}  $count'),
                    selectedColor: const Color(0xFFE4F2E1),
                    backgroundColor: Colors.white,
                    side: BorderSide(
                      color: selected
                          ? const Color(0xFFBFD8B8)
                          : const Color(0xFFDDE6DA),
                    ),
                    labelStyle: TextStyle(
                      color: selected
                          ? FarmColors.deepGreen
                          : FarmColors.mutedText,
                      fontSize: 9.2,
                      fontWeight: FontWeight.w900,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(999),
                    ),
                  ),
                );
              }),
            ),
          ),
          const SizedBox(height: 14),

          Row(
            children: [
              Expanded(
                child: Text(
                  selectedCategory.title,
                  style: const TextStyle(
                    color: FarmColors.ink,
                    fontSize: 17,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              Text(
                '${selectedRows.length}',
                style: const TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 10,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ],
          ),
          const SizedBox(height: 9),

          if (selectedRows.isEmpty)
            Container(
              padding: const EdgeInsets.symmetric(
                horizontal: 14,
                vertical: 20,
              ),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(18),
                border: Border.all(color: const Color(0xFFDDE7DA)),
              ),
              child: Row(
                children: [
                  Container(
                    width: 42,
                    height: 42,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: selectedCategory.soft,
                      borderRadius: BorderRadius.circular(13),
                    ),
                    child: Icon(
                      selectedCategory.icon,
                      color: selectedCategory.accent,
                    ),
                  ),
                  const SizedBox(width: 11),
                  Expanded(
                    child: Text(
                      selectedCategory.key == 'all'
                          ? 'No active buyer needs right now.'
                          : 'No items in this filter.',
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 10.5,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ),
                ],
              ),
            )
          else
            ...selectedRows.map(
              (item) => Padding(
                padding: const EdgeInsets.only(bottom: 9),
                child: _opportunityCard(item, matchingKeys),
              ),
            ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final body = FutureBuilder<_HpjFarmerDemandMvpSnapshot>(
      future: _future,
      builder: (context, snapshot) {
        final data = snapshot.data;
        if (snapshot.connectionState == ConnectionState.waiting && data == null) {
          return const Center(child: CircularProgressIndicator());
        }
        if (snapshot.hasError && data == null) {
          return RefreshIndicator(
            onRefresh: _refresh,
            child: ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.fromLTRB(16, 24, 16, 90),
              children: const [
                FarmEmptyState(
                  icon: Icons.insights_outlined,
                  title: 'Demand board unavailable',
                  message: 'Please refresh the page and try again.',
                ),
              ],
            ),
          );
        }
        return _buildBody(
          context,
          data ??
              const _HpjFarmerDemandMvpSnapshot(
                opportunities: <FarmerMarketDemandOpportunity>[],
                supplies: <FarmerSupplyForecast>[],
              ),
        );
      },
    );

    if (widget.embedded) {
      return body;
    }

    return Scaffold(
      backgroundColor: const Color(0xFFF6F8F4),
      appBar: AppBar(
        backgroundColor: const Color(0xFFF6F8F4),
        surfaceTintColor: Colors.transparent,
        title: const Text('Market'),
      ),
      body: body,
    );
  }
}


class FarmerSupplyScreen extends StatefulWidget {
  final FarmerProfile profile;
  final int refreshKey;
  final String? initialSupplyId;

  const FarmerSupplyScreen({
    super.key,
    required this.profile,
    required this.refreshKey,
    this.initialSupplyId,
  });

  @override
  State<FarmerSupplyScreen> createState() =>
      _FarmerSupplyScreenState();
}

class _FarmerSupplyScreenState
    extends State<FarmerSupplyScreen> {
  int localRefreshKey = 0;

  void refreshSupply() {
    setState(() {
      localRefreshKey++;
    });
  }

  Future<void> _openSupplyUpdate(
    FarmerSupplyForecast supply,
  ) async {
    final changed = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _FarmerSupplyUpdateSheet(supply: supply),
    );

    if (changed == true && mounted) {
      refreshSupply();
    }
  }

  Future<void> _showCropCalendar(
    List<FarmerSupplyForecast> supplies,
  ) async {
    await Navigator.of(context).push<void>(
      MaterialPageRoute<void>(
        builder: (_) => _HpjFarmerCalendarMvpPage(
          profile: widget.profile,
          supplies: supplies,
          onOpenSupply: _openSupplyUpdate,
        ),
      ),
    );
  }

  Future<void> openSupplyForm(
    List<FarmerSupplyForecast>
        recentSupplies,
  ) async {
    final savedCrop =
        await showModalBottomSheet<String>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor:
          Colors.transparent,
      builder: (_) =>
          _FarmerSupplyEntrySheet(
        farmerId: widget.profile.id,
        recentSupplies:
            recentSupplies,
      ),
    );

    if (!mounted ||
        savedCrop == null ||
        savedCrop.trim().isEmpty) {
      return;
    }

    refreshSupply();

    await _showSupplyValueFeedback(
      savedCrop.trim(),
    );
  }

  Future<void>
      _showSupplyValueFeedback(
    String cropName,
  ) async {
    FarmerMarketDemandOpportunity?
        match;

    try {
      final board =
          await fetchFarmerMarketDemandBoard(
        30,
      );

      final wanted =
          cropName.trim().toLowerCase();

      for (final item in board) {
        if (item.productName
                .trim()
                .toLowerCase() ==
            wanted) {
          match = item;
          break;
        }
      }
    } catch (error) {
      farmDebugLog(
        'Farmer supply value feedback unavailable: $error',
      );
    }

    if (!mounted) return;

    await showModalBottomSheet<void>(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      backgroundColor:
          Colors.transparent,
      builder: (_) =>
          _FarmerSupplyValueSheet(
        cropName: cropName,
        opportunity: match,
      ),
    );
  }

  double _planningQuantity(FarmerSupplyForecast supply) {
    final values = <double>[
      supply.harvestedQuantity ?? 0,
      supply.expectedQuantity ?? 0,
      supply.quantityGrowing ?? 0,
    ];

    var best = 0.0;
    for (final value in values) {
      if (value.isFinite && value > best) best = value;
    }
    return best;
  }

  bool _needsSupplyAttention(FarmerSupplyForecast supply) {
    if (!supply.isActive) return false;

    if (_planningQuantity(supply) <= 0) return true;

    if (supply.expectedHarvestDate == null && !supply.isHarvested) {
      return true;
    }

    final harvestDate = supply.expectedHarvestDate;
    if (harvestDate != null && !supply.isHarvested) {
      final now = DateTime.now();
      final today = DateTime(now.year, now.month, now.day);
      final expected = DateTime(
        harvestDate.year,
        harvestDate.month,
        harvestDate.day,
      );

      if (expected.isBefore(today)) return true;
    }

    return _farmerSupplyNeedsReview(supply);
  }

  int _compareSupplyForFarmer(
    FarmerSupplyForecast a,
    FarmerSupplyForecast b,
  ) {
    if (a.isActive != b.isActive) return a.isActive ? -1 : 1;

    final aNeeds = _needsSupplyAttention(a);
    final bNeeds = _needsSupplyAttention(b);
    if (aNeeds != bNeeds) return aNeeds ? -1 : 1;

    final aDate = a.expectedHarvestDate ?? DateTime(2999);
    final bDate = b.expectedHarvestDate ?? DateTime(2999);
    final dateCompare = aDate.compareTo(bDate);
    if (dateCompare != 0) return dateCompare;

    return a.cropName.toLowerCase().compareTo(b.cropName.toLowerCase());
  }

  Future<void> _openManageSupply(
    List<FarmerSupplyForecast> supplies, {
    String initialFilter = 'all',
  }) async {
    final searchController = TextEditingController();
    var filter = initialFilter;

    try {
      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        builder: (sheetContext) {
          return StatefulBuilder(
            builder: (context, setSheetState) {
              bool matchesFilter(FarmerSupplyForecast supply) {
                switch (filter) {
                  case 'current':
                    return supply.isActive && !_needsSupplyAttention(supply);
                  case 'needs':
                    return supply.isActive && _needsSupplyAttention(supply);
                  case 'past':
                    return !supply.isActive;
                  default:
                    return true;
                }
              }

              final query = searchController.text.trim().toLowerCase();
              final visible = supplies.where((supply) {
                if (!matchesFilter(supply)) return false;
                if (query.isEmpty) return true;

                return supply.cropName.toLowerCase().contains(query) ||
                    (supply.category ?? '').toLowerCase().contains(query) ||
                    supply.unit.toLowerCase().contains(query) ||
                    supply.statusLabel.toLowerCase().contains(query);
              }).toList()
                ..sort(_compareSupplyForFarmer);

              return FractionallySizedBox(
                heightFactor: 0.92,
                child: Material(
                  color: FarmColors.background,
                  borderRadius: const BorderRadius.vertical(
                    top: Radius.circular(26),
                  ),
                  child: Column(
                    children: [
                      Padding(
                        padding: const EdgeInsets.fromLTRB(18, 12, 10, 10),
                        child: Row(
                          children: [
                            const Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    'Manage Supply',
                                    style: TextStyle(
                                      color: FarmColors.ink,
                                      fontSize: 20,
                                      fontWeight: FontWeight.w900,
                                    ),
                                  ),
                                  SizedBox(height: 2),
                                  Text(
                                    'Search, update or safely cancel old crop reports.',
                                    style: TextStyle(
                                      color: FarmColors.mutedText,
                                      fontSize: 10,
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                            IconButton(
                              tooltip: 'Close',
                              onPressed: () => Navigator.of(sheetContext).pop(),
                              icon: const Icon(Icons.close_rounded),
                            ),
                          ],
                        ),
                      ),
                      Padding(
                        padding: const EdgeInsets.fromLTRB(18, 0, 18, 8),
                        child: TextField(
                          controller: searchController,
                          onChanged: (_) => setSheetState(() {}),
                          decoration: InputDecoration(
                            hintText: 'Search crop, status or unit...',
                            prefixIcon: const Icon(Icons.search_rounded),
                            suffixIcon: query.isEmpty
                                ? null
                                : IconButton(
                                    tooltip: 'Clear search',
                                    onPressed: () {
                                      searchController.clear();
                                      setSheetState(() {});
                                    },
                                    icon: const Icon(Icons.close_rounded),
                                  ),
                          ),
                        ),
                      ),
                      SingleChildScrollView(
                        scrollDirection: Axis.horizontal,
                        padding: const EdgeInsets.fromLTRB(18, 0, 18, 10),
                        child: Row(
                          children: [
                            for (final option in const <String, String>{
                              'all': 'All',
                              'current': 'Current',
                              'needs': 'Needs Update',
                              'past': 'Past',
                            }.entries) ...[
                              ChoiceChip(
                                label: Text(option.value),
                                selected: filter == option.key,
                                onSelected: (_) {
                                  setSheetState(() => filter = option.key);
                                },
                              ),
                              const SizedBox(width: 7),
                            ],
                          ],
                        ),
                      ),
                      const Divider(height: 1),
                      Expanded(
                        child: visible.isEmpty
                            ? const Center(
                                child: Padding(
                                  padding: EdgeInsets.all(24),
                                  child: Text(
                                    'No supply reports match this view.',
                                    textAlign: TextAlign.center,
                                    style: TextStyle(
                                      color: FarmColors.mutedText,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                ),
                              )
                            : ListView.separated(
                                padding: const EdgeInsets.fromLTRB(
                                  18,
                                  14,
                                  18,
                                  28,
                                ),
                                itemCount: visible.length,
                                separatorBuilder: (_, __) =>
                                    const SizedBox(height: 10),
                                itemBuilder: (_, index) {
                                  final supply = visible[index];
                                  return _FarmerSupplyCard(
                                    farmerId: widget.profile.id,
                                    supply: supply,
                                    onChanged: () {
                                      refreshSupply();
                                      if (Navigator.of(sheetContext).canPop()) {
                                        Navigator.of(sheetContext).pop();
                                      }
                                    },
                                  );
                                },
                              ),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        },
      );
    } finally {
      searchController.dispose();
    }
  }
  @override
  Widget build(BuildContext context) {
    final desktopWeb = HpjWebUi.isDesktop(context);

    return FarmPage(
      child: FutureBuilder<List<FarmerSupplyForecast>>(
        key: ValueKey(
          'farmer-supply-${widget.refreshKey}-$localRefreshKey',
        ),
        future: fetchFarmerSupplyForecasts(widget.profile.id),
        builder: (context, snapshot) {
          final supplies =
              snapshot.data ?? const <FarmerSupplyForecast>[];

          final requestedSupplyId =
              widget.initialSupplyId?.trim() ?? '';

          final focusedSupplies = requestedSupplyId.isEmpty
              ? const <FarmerSupplyForecast>[]
              : supplies
                  .where((item) => item.id.trim() == requestedSupplyId)
                  .toList();

          final exactSupplyFound = focusedSupplies.isNotEmpty;
          final visibleSupplies =
              exactSupplyFound ? focusedSupplies : supplies;

          final active =
              visibleSupplies.where((item) => item.isActive).toList();

          final current = active
              .where((item) => !_needsSupplyAttention(item))
              .toList()
            ..sort(_compareSupplyForFarmer);

          final needsUpdate =
              active.where(_needsSupplyAttention).toList()
                ..sort(_compareSupplyForFarmer);

          final past = visibleSupplies
              .where((item) => !item.isActive)
              .toList()
            ..sort(_compareSupplyForFarmer);

          final confirmed =
              active.where((item) => item.isHpjConfirmed).length;

          final currentPreview = current.take(5).toList();
          final needsPreview = needsUpdate.take(3).toList();
          final pastPreview = past.take(3).toList();

          if (snapshot.connectionState == ConnectionState.waiting &&
              supplies.isEmpty) {
            return ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.fromLTRB(18, 20, 18, 110),
              children: const [
                SizedBox(
                  height: 360,
                  child: SkeletonList(count: 3),
                ),
              ],
            );
          }

          if (snapshot.hasError && supplies.isEmpty) {
            return ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.fromLTRB(18, 28, 18, 110),
              children: [
                const FarmEmptyState(
                  icon: Icons.cloud_off_outlined,
                  title: 'My Crops could not load',
                  message:
                      'Your crop reports are still safe. Retry before adding or updating supply.',
                ),
                const SizedBox(height: 12),
                FilledButton.icon(
                  onPressed: refreshSupply,
                  icon: const Icon(Icons.refresh_rounded),
                  label: const Text('Retry My Crops'),
                ),
              ],
            );
          }

          if (hpjUseMobileAppPresentation(context)) {
            final canGoBack = Navigator.of(context).canPop();

            final producePage = _HpjFarmerReferenceCropsPage(
              profile: widget.profile,
              supplies: supplies,
              active: active,
              needsUpdate: needsUpdate,
              onAdd: () => openSupplyForm(supplies),
              onCalendar: () => _showCropCalendar(supplies),
              onChanged: refreshSupply,
              onOpenSupply: _openSupplyUpdate,
            );

            if (!canGoBack) {
              return producePage;
            }

            return Column(
              children: [
                SafeArea(
                  bottom: false,
                  child: Container(
                    width: double.infinity,
                    padding: const EdgeInsets.fromLTRB(10, 8, 14, 8),
                    decoration: const BoxDecoration(
                      color: FarmColors.background,
                      border: Border(
                        bottom: BorderSide(
                          color: Color(0xFFE1E7DE),
                        ),
                      ),
                    ),
                    child: Row(
                      children: [
                        IconButton(
                          tooltip: 'Back',
                          onPressed: () => Navigator.of(context).maybePop(),
                          icon: const Icon(
                            Icons.arrow_back_rounded,
                            color: FarmColors.deepGreen,
                          ),
                        ),
                        const SizedBox(width: 2),
                        const Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                'My Crops',
                                style: TextStyle(
                                  color: FarmColors.ink,
                                  fontSize: 17,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                              SizedBox(height: 1),
                              Text(
                                'Manage crops, pricing and availability',
                                style: TextStyle(
                                  color: FarmColors.mutedText,
                                  fontSize: 9.2,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
                Expanded(child: producePage),
              ],
            );
          }

          return ListView(
            padding: const EdgeInsets.fromLTRB(18, 18, 18, 110),
            children: [
              _PremiumFarmerSupplyHero(
                farmName: widget.profile.farmName,
                activeCount: active.length,
                currentCount: current.length,
                needsUpdateCount: needsUpdate.length,
                confirmedCount: confirmed,
                onAdd: () => openSupplyForm(supplies),
                onManage: () => _openManageSupply(supplies),
              ),
              const SizedBox(height: 14),

              if (requestedSupplyId.isNotEmpty) ...[
                _FarmerRecordFocusNotice(
                  found: exactSupplyFound,
                  foundMessage:
                      'Opened from your notification. Showing the related supply report.',
                  missingMessage:
                      'That supply report is no longer available. Showing your current supply instead.',
                ),
                const SizedBox(height: 14),
              ],

              _FarmerShopListingRequestSummary(
                farmerId: widget.profile.id,
                refreshKey: localRefreshKey,
              ),
              const SizedBox(height: 14),

              if (active.isNotEmpty)
                _PremiumFarmerSupplyHealthCard(
                  currentCount: current.length,
                  needsUpdateCount: needsUpdate.length,
                  confirmedCount: confirmed,
                  onReview: needsUpdate.isEmpty
                      ? () => _openManageSupply(supplies)
                      : () => _openManageSupply(
                            supplies,
                            initialFilter: 'needs',
                          ),
                ),

              if (active.isNotEmpty) const SizedBox(height: 16),

              if (active.isEmpty && past.isEmpty)
                _FarmerFirstCropCard(
                  onTap: () => openSupplyForm(supplies),
                )
              else ...[
                if (current.isNotEmpty) ...[
                  _PremiumFarmerSupplySectionHeader(
                    eyebrow: 'CURRENT',
                    title: 'Active harvest plans',
                    subtitle:
                        'Supply reports that are current and ready for HPJ planning.',
                    countLabel: '${current.length}',
                    accent: FarmColors.success,
                  ),
                  const SizedBox(height: 10),
                  if (desktopWeb)
                    HpjWebResponsiveGrid(
                      minItemWidth: 470,
                      spacing: 16,
                      runSpacing: 16,
                      children: currentPreview
                          .map(
                            (supply) => _FarmerSupplyCard(
                              farmerId: widget.profile.id,
                              supply: supply,
                              onChanged: refreshSupply,
                            ),
                          )
                          .toList(growable: false),
                    )
                  else
                    ...currentPreview.map(
                      (supply) => Padding(
                        padding: const EdgeInsets.only(bottom: 11),
                        child: _FarmerSupplyCard(
                          farmerId: widget.profile.id,
                          supply: supply,
                          onChanged: refreshSupply,
                        ),
                      ),
                    ),
                  if (current.length > currentPreview.length) ...[
                    const SizedBox(height: 2),
                    SizedBox(
                      width: double.infinity,
                      child: OutlinedButton.icon(
                        onPressed: () => _openManageSupply(
                          supplies,
                          initialFilter: 'current',
                        ),
                        icon: const Icon(Icons.list_alt_rounded, size: 17),
                        label: Text(
                          'View all ${current.length} current crops',
                        ),
                      ),
                    ),
                  ],
                ],

                if (needsUpdate.isNotEmpty) ...[
                  const SizedBox(height: 18),
                  _PremiumFarmerSupplySectionHeader(
                    eyebrow: 'ACTION NEEDED',
                    title: 'Update these crop reports',
                    subtitle:
                        'Older, overdue, missing-date or zero-quantity reports should be confirmed or updated.',
                    countLabel: '${needsUpdate.length}',
                    accent: FarmColors.warning,
                  ),
                  const SizedBox(height: 10),
                  if (desktopWeb)
                    HpjWebResponsiveGrid(
                      minItemWidth: 470,
                      spacing: 16,
                      runSpacing: 16,
                      children: needsPreview
