                ],

                if (past.isNotEmpty) ...[
                  const SizedBox(height: 18),
                  FarmCard(
                    padding: EdgeInsets.zero,
                    child: ExpansionTile(
                      tilePadding:
                          const EdgeInsets.symmetric(horizontal: 16),
                      childrenPadding:
