}



class _HpjFarmerSupplyMobileMvp extends StatelessWidget {
  final String farmerId;
  final List<FarmerSupplyForecast> supplies;
  final List<FarmerSupplyForecast> active;
  final List<FarmerSupplyForecast> current;
  final List<FarmerSupplyForecast> needsUpdate;
  final int confirmedCount;
  final int refreshKey;
  final VoidCallback onAdd;
  final VoidCallback onManage;
  final VoidCallback onCalendar;
  final VoidCallback onViewCurrent;
  final Future<void> Function(FarmerSupplyForecast supply) onOpenSupply;

  const _HpjFarmerSupplyMobileMvp({
    required this.farmerId,
    required this.supplies,
    required this.active,
    required this.current,
    required this.needsUpdate,
    required this.confirmedCount,
    required this.refreshKey,
    required this.onAdd,
    required this.onManage,
    required this.onCalendar,
    required this.onViewCurrent,
    required this.onOpenSupply,
  });

  List<FarmerSupplyForecast> _uniqueByCrop(
    Iterable<FarmerSupplyForecast> rows,
  ) {
    final byCrop = <String, FarmerSupplyForecast>{};

    for (final item in rows) {
      final key = hpjSmartNormalizeSearch(item.cropName);
      if (key.isEmpty) continue;

      final previous = byCrop[key];
      if (previous == null) {
        byCrop[key] = item;
        continue;
      }

      final previousDate =
          previous.updatedAt ?? previous.createdAt ?? DateTime(2000);
      final itemDate = item.updatedAt ?? item.createdAt ?? DateTime(2000);

      if (itemDate.isAfter(previousDate)) {
        byCrop[key] = item;
      }
    }

    final result = byCrop.values.toList();
    result.sort((a, b) {
      final aDate = a.updatedAt ?? a.createdAt ?? DateTime(2000);
      final bDate = b.updatedAt ?? b.createdAt ?? DateTime(2000);
      return bDate.compareTo(aDate);
    });
    return result;
  }

  @override
  Widget build(BuildContext context) {
    final uniqueActive = _uniqueByCrop(active);
    final uniqueCurrent = _uniqueByCrop(
      current.isNotEmpty ? current : active,
    );
    final uniqueNeeds = _uniqueByCrop(needsUpdate);
    final confirmed = uniqueActive.where((item) => item.isHpjConfirmed).length;

    final preview = uniqueCurrent.take(4).toList(growable: false);
    final needsIds = uniqueNeeds.map((item) => item.id).toSet();

    return ListView(
      physics: const AlwaysScrollableScrollPhysics(),
      padding: const EdgeInsets.fromLTRB(14, 12, 14, 118),
      children: [
        _HpjFarmerSupplyMobileHero(
          onAdd: onAdd,
          onManage: onManage,
          onCalendar: onCalendar,
        ),
        const SizedBox(height: 10),
        Container(
          padding: const EdgeInsets.fromLTRB(12, 10, 12, 10),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: const Color(0xFFDDE7DD)),
          ),
          child: const Row(
            children: [
              Icon(
                Icons.photo_camera_outlined,
                color: FarmColors.primary,
                size: 19,
              ),
              SizedBox(width: 9),
              Expanded(
                child: Text(
                  'Photo first • amount • ready date • post. You can edit or post again anytime.',
                  style: TextStyle(
                    color: FarmColors.mutedText,
                    fontSize: 9.7,
                    height: 1.3,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 8),
        Align(
          alignment: Alignment.centerRight,
          child: HpjContextHelpButton(
            topic: HpjContextHelpTopic.farmerSupply,
            showLabel: true,
          ),
        ),
        const SizedBox(height: 10),

        // Keep the numbers operational and easy to understand.
        Row(
          children: [
            _HpjFarmerSupplyStatCard(
              icon: Icons.eco_rounded,
              value: '${uniqueActive.length}',
              label: 'My produce',
            ),
            const SizedBox(width: 8),
            _HpjFarmerSupplyStatCard(
              icon: Icons.schedule_rounded,
              value: '${uniqueNeeds.length}',
              label: 'Needs update',
              warning: uniqueNeeds.isNotEmpty,
            ),
            const SizedBox(width: 8),
            _HpjFarmerSupplyStatCard(
              icon: Icons.verified_rounded,
              value: '$confirmed',
              label: 'HPJ confirmed',
            ),
          ],
        ),
        const SizedBox(height: 14),

        // Primary job of this page: manage crops already reported.
        _HpjFarmerCurrentSupplyCard(
          supplies: preview,
          totalCount: uniqueCurrent.length,
          needsIds: needsIds,
          onViewAll: onViewCurrent,
          onAdd: onAdd,
          onOpenSupply: onOpenSupply,
        ),
        const SizedBox(height: 14),

        // Secondary workflow: only crops submitted to the customer Shop.
        _HpjFarmerMobileShopListingCard(
          farmerId: farmerId,
          refreshKey: refreshKey,
        ),
      ],
    );
  }
}

