class _HpjFarmerMobileShopListingCard extends StatefulWidget {
  final String farmerId;
  final int refreshKey;

  const _HpjFarmerMobileShopListingCard({
    required this.farmerId,
    required this.refreshKey,
  });

  @override
  State<_HpjFarmerMobileShopListingCard> createState() =>
      _HpjFarmerMobileShopListingCardState();
}

class _HpjFarmerMobileShopListingCardState
    extends State<_HpjFarmerMobileShopListingCard> {
  int localRefreshKey = 0;

  String _date(DateTime? value) {
    if (value == null) return '';
    const months = <String>[
      'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
      'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
    ];
    return '${value.day} ${months[value.month - 1]} ${value.year}';
  }

  bool _canResubmit(FarmerShopListingRequest request) {
    return request.status == 'rejected' ||
        request.status == 'needs_changes';
  }

  String _statusHelp(FarmerShopListingRequest request) {
    switch (request.status) {
      case 'live':
        return 'This produce is live in the Customer Shop.';
      case 'approved':
        return 'HPJ approved this request. Publishing is being completed.';
      case 'needs_changes':
        return 'HPJ needs changes before this produce can go live.';
      case 'rejected':
        return 'This request was not approved. You can update it and request review again.';
      default:
        return 'HPJ is reviewing this Shop request.';
    }
  }

  Future<FarmerSupplyForecast?> _findSupply(
    FarmerShopListingRequest request,
  ) async {
    final rows = await fetchFarmerSupplyForecasts(widget.farmerId);
    for (final supply in rows) {
      if (supply.id == request.supplyId) return supply;
    }
    return null;
  }

  Future<void> _resubmit(
    BuildContext context,
    FarmerShopListingRequest request,
  ) async {
    final supply = await _findSupply(request);

    if (!mounted) return;

    if (supply == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'The original produce supply record could not be found.',
          ),
        ),
      );
      return;
    }

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _FarmerExistingSupplyShopRequestSheet(
        farmerId: widget.farmerId,
        supply: supply,
      ),
    );

    if (!mounted) return;
    setState(() => localRefreshKey++);
  }

  Future<void> _openRequest(
    BuildContext context,
    FarmerShopListingRequest request,
  ) async {
    final canResubmit = _canResubmit(request);

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return SafeArea(
          top: false,
          child: Container(
            decoration: const BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.vertical(
                top: Radius.circular(26),
              ),
            ),
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(18, 12, 18, 22),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Center(
                    child: Container(
                      width: 42,
                      height: 4,
                      decoration: BoxDecoration(
                        color: const Color(0xFFD8DDD5),
                        borderRadius: BorderRadius.circular(99),
                      ),
                    ),
                  ),
                  const SizedBox(height: 16),
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      HpjProductThumb(
                        productName: request.productName,
                        size: 76,
                        radius: 15,
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            const Text(
                              'SHOP STATUS',
                              style: TextStyle(
                                color: FarmColors.primary,
                                fontSize: 8.8,
                                fontWeight: FontWeight.w900,
                                letterSpacing: 1.0,
                              ),
                            ),
                            const SizedBox(height: 5),
                            Text(
                              request.productName,
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontSize: 20,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 5),
                            HpjMvpStatusPill(
                              label: request.statusLabel,
                              color: request.statusColor,
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 16),
                  Text(
                    _statusHelp(request),
                    style: const TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 10.5,
                      height: 1.4,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  if (request.expectedHarvestDate != null) ...[
                    const SizedBox(height: 12),
                    _HpjFarmerShopInfoRow(
                      icon: Icons.calendar_month_outlined,
                      label: 'Expected harvest',
                      value: _date(request.expectedHarvestDate),
                    ),
                  ],
                  if (request.unit.trim().isNotEmpty) ...[
                    const SizedBox(height: 8),
                    _HpjFarmerShopInfoRow(
                      icon: Icons.scale_outlined,
                      label: 'Unit',
                      value: request.unit,
                    ),
                  ],
                  if (request.adminNotes.trim().isNotEmpty) ...[
                    const SizedBox(height: 12),
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: request.status == 'rejected' ||
                                request.status == 'needs_changes'
                            ? const Color(0xFFFFF4E7)
                            : const Color(0xFFF4F7F2),
                        borderRadius: BorderRadius.circular(14),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            'HPJ note',
                            style: TextStyle(
                              color: FarmColors.ink,
                              fontSize: 10.5,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                          const SizedBox(height: 4),
                          Text(
                            request.adminNotes,
                            style: const TextStyle(
                              color: FarmColors.mutedText,
                              fontSize: 9.8,
                              height: 1.35,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                  const SizedBox(height: 16),
                  if (canResubmit)
                    SizedBox(
                      width: double.infinity,
                      height: 46,
                      child: FilledButton.icon(
                        onPressed: () async {
                          Navigator.of(sheetContext).pop();
                          await _resubmit(context, request);
                        },
                        icon: const Icon(Icons.refresh_rounded),
                        label: Text(
                          request.status == 'rejected'
                              ? 'Update & request again'
                              : 'Make changes & resubmit',
                        ),
                        style: FilledButton.styleFrom(
                          backgroundColor: FarmColors.primary,
                          foregroundColor: Colors.white,
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(13),
                          ),
                          textStyle: const TextStyle(
                            fontSize: 11.5,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                    )
                  else
                    SizedBox(
                      width: double.infinity,
                      height: 44,
                      child: OutlinedButton.icon(
                        onPressed: () => Navigator.of(sheetContext).pop(),
                        icon: const Icon(Icons.check_rounded),
                        label: const Text('Done'),
                        style: OutlinedButton.styleFrom(
                          foregroundColor: FarmColors.deepGreen,
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(13),
                          ),
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _row(
    BuildContext context,
    FarmerShopListingRequest request,
  ) {
    final statusColor = request.statusColor;
    final statusBackground = request.status == 'rejected'
        ? const Color(0xFFFFECE8)
        : request.status == 'needs_changes'
            ? const Color(0xFFFFF4D8)
            : request.status == 'live' || request.status == 'approved'
                ? const Color(0xFFE4F5E7)
                : const Color(0xFFFFF4D8);

    return InkWell(
      onTap: () => _openRequest(context, request),
      borderRadius: BorderRadius.circular(12),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 9),
        child: Row(
          children: [
            HpjProductThumb(
              productName: request.productName,
              size: 52,
              radius: 12,
            ),
            const SizedBox(width: 11),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    request.productName,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: Color(0xFF111E19),
                      fontSize: 13,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 3),
                  Text(
                    request.status == 'rejected'
                        ? 'Tap to update and request again'
                        : request.status == 'needs_changes'
                            ? 'Tap to review HPJ changes'
                            : request.expectedHarvestDate == null
                                ? request.statusLabel
                                : 'Expected ${_date(request.expectedHarvestDate)}',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      color: _canResubmit(request)
                          ? const Color(0xFFA76D00)
                          : const Color(0xFF748078),
                      fontSize: 9.5,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(width: 7),
            Container(
              padding: const EdgeInsets.symmetric(
                horizontal: 9,
                vertical: 6,
              ),
              decoration: BoxDecoration(
                color: statusBackground,
                borderRadius: BorderRadius.circular(999),
              ),
              child: Text(
                request.statusLabel,
                style: TextStyle(
                  color: statusColor,
                  fontSize: 8.7,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
            const SizedBox(width: 2),
            const Icon(
              Icons.chevron_right_rounded,
              color: Color(0xFF5D6861),
              size: 20,
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _showAll(
    BuildContext context,
    List<FarmerShopListingRequest> requests,
  ) async {
    await showModalBottomSheet<void>(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) => FractionallySizedBox(
        heightFactor: .88,
        child: Material(
          color: const Color(0xFFF8FBF6),
          borderRadius: const BorderRadius.vertical(
            top: Radius.circular(28),
          ),
          child: Column(
            children: [
              const Padding(
                padding: EdgeInsets.fromLTRB(18, 18, 18, 12),
                child: Row(
                  children: [
                    Icon(
                      Icons.storefront_outlined,
                      color: Color(0xFF006B3D),
                    ),
                    SizedBox(width: 9),
                    Expanded(
                      child: Text(
                        'Shop status',
                        style: TextStyle(
                          color: Color(0xFF111E19),
                          fontSize: 18,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              const Divider(height: 1),
              Expanded(
                child: ListView.separated(
                  padding: const EdgeInsets.fromLTRB(18, 8, 18, 24),
                  itemCount: requests.length,
                  separatorBuilder: (_, __) => const Divider(height: 1),
                  itemBuilder: (_, index) =>
                      _row(context, requests[index]),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<FarmerShopListingRequest>>(
      key: ValueKey(
        'mvp-farmer-shop-listing-${widget.farmerId}-'
        '${widget.refreshKey}-$localRefreshKey',
      ),
      future: fetchFarmerShopListingRequests(
        farmerId: widget.farmerId,
        limit: 20,
      ),
      builder: (context, snapshot) {
        final requests =
            snapshot.data ?? const <FarmerShopListingRequest>[];

        return Container(
          padding: const EdgeInsets.fromLTRB(14, 14, 14, 9),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(20),
            border: Border.all(color: const Color(0xFFDDE7DD)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Container(
                    width: 36,
                    height: 36,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: const Color(0xFFE9F6EB),
                      borderRadius: BorderRadius.circular(11),
                    ),
                    child: const Icon(
                      Icons.storefront_outlined,
                      color: Color(0xFF006B3D),
                      size: 20,
                    ),
                  ),
                  const SizedBox(width: 9),
                  const Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Shop status',
                          style: TextStyle(
                            color: Color(0xFF111E19),
                            fontSize: 15.5,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        SizedBox(height: 2),
                        Text(
                          'Tap a produce request to view its status or fix it.',
                          style: TextStyle(
                            color: Color(0xFF748078),
                            fontSize: 9.3,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ],
                    ),
                  ),
                  if (requests.isNotEmpty)
                    TextButton(
                      onPressed: () => _showAll(context, requests),
                      child: const Text('View all'),
                    ),
                ],
              ),
              const SizedBox(height: 5),
              if (snapshot.connectionState == ConnectionState.waiting &&
                  requests.isEmpty)
                const Padding(
                  padding: EdgeInsets.symmetric(vertical: 20),
                  child: Center(
                    child: CircularProgressIndicator(strokeWidth: 2),
                  ),
                )
              else if (requests.isEmpty)
                const Padding(
                  padding: EdgeInsets.symmetric(vertical: 18),
                  child: Text(
                    'No produce submitted to the customer Shop yet.',
                    style: TextStyle(
                      color: Color(0xFF748078),
                      fontSize: 10,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                )
              else
                for (var i = 0; i < requests.take(3).length; i++) ...[
                  if (i > 0) const Divider(height: 1),
                  _row(context, requests[i]),
                ],
            ],
          ),
        );
      },
    );
  }
}

