class _HpjFarmerCurrentSupplyCard extends StatelessWidget {
  final List<FarmerSupplyForecast> supplies;
  final int totalCount;
  final Set<String> needsIds;
  final VoidCallback onViewAll;
  final VoidCallback onAdd;
  final Future<void> Function(FarmerSupplyForecast supply) onOpenSupply;

  const _HpjFarmerCurrentSupplyCard({
    required this.supplies,
    required this.totalCount,
    required this.needsIds,
    required this.onViewAll,
    required this.onAdd,
    required this.onOpenSupply,
  });

  String _qty(FarmerSupplyForecast supply) {
    final value = supply.harvestedQuantity ??
        supply.expectedQuantity ??
        supply.quantityGrowing ??
        0;
    final text = value == value.roundToDouble()
        ? value.toInt().toString()
        : value.toStringAsFixed(1);
    return '$text ${supply.unit}';
  }

  String _freshness(FarmerSupplyForecast supply) {
    final updated = supply.updatedAt ?? supply.createdAt;
    if (updated == null) return 'Update when anything changes';

    final now = DateTime.now();
    final date = updated.toLocal();
    final days = DateTime(now.year, now.month, now.day)
        .difference(DateTime(date.year, date.month, date.day))
        .inDays;

    if (days <= 0) return 'Updated today';
    if (days == 1) return 'Updated yesterday';
    if (days <= 6) return 'Updated $days days ago';
    return 'Update recommended';
  }

  Widget _row(BuildContext context, FarmerSupplyForecast supply) {
    final needs = needsIds.contains(supply.id);
    final confirmed = supply.isHpjConfirmed;

    final label = needs
        ? 'Needs update'
        : confirmed
            ? 'HPJ confirmed'
            : supply.statusLabel;

    final chipColor = needs
        ? const Color(0xFFFFF2D7)
        : confirmed
            ? const Color(0xFFE4F5E7)
            : const Color(0xFFEAF3E7);

    final textColor = needs
        ? const Color(0xFFA76D00)
        : const Color(0xFF006B3D);

    return InkWell(
      onTap: () => onOpenSupply(supply),
      borderRadius: BorderRadius.circular(13),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 9),
        child: Row(
          children: [
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onTap: () => _showHpjFarmerCropGuide(
                context,
                supply.cropName,
                supply: supply,
              ),
              child: HpjProductThumb(
                productName: supply.cropName,
                size: 54,
                radius: 13,
              ),
            ),
            const SizedBox(width: 11),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    supply.cropName,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: Color(0xFF111E19),
                      fontSize: 13,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                  const SizedBox(height: 3),
                  Text(
                    '${_qty(supply)} • ${_freshness(supply)}',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: Color(0xFF748078),
                      fontSize: 9.3,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(width: 7),
            Container(
              padding: const EdgeInsets.symmetric(
                horizontal: 9,
                vertical: 6,
              ),
              decoration: BoxDecoration(
                color: chipColor,
                borderRadius: BorderRadius.circular(999),
              ),
              child: Text(
                label,
                style: TextStyle(
                  color: textColor,
                  fontSize: 8.3,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
            const SizedBox(width: 2),
            const Icon(
              Icons.chevron_right_rounded,
              color: Color(0xFF5D6861),
              size: 19,
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 13),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: const Color(0xFFDDE7DD)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 36,
                height: 36,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: const Color(0xFFE9F6EB),
                  borderRadius: BorderRadius.circular(11),
                ),
                child: const Icon(
                  Icons.eco_rounded,
                  color: Color(0xFF006B3D),
                  size: 20,
                ),
              ),
              const SizedBox(width: 9),
              const Expanded(
                child: Column(
