class _FarmerSupplyUpdateSheet extends StatefulWidget {
  final FarmerSupplyForecast supply;

  const _FarmerSupplyUpdateSheet({
    required this.supply,
  });

  @override
  State<_FarmerSupplyUpdateSheet> createState() =>
      _FarmerSupplyUpdateSheetState();
}

class _FarmerSupplyUpdateSheetState
    extends State<_FarmerSupplyUpdateSheet> {
  late final TextEditingController cropNameController;
  late final TextEditingController expectedController;
  late final TextEditingController harvestedController;
  late final TextEditingController priceController;
  late final TextEditingController salePriceController;
  late final TextEditingController lowStockController;
  late final TextEditingController notesController;

  static const editableStatuses = <String>[
    'planning',
    'growing',
    'expected',
    'harvest_ready',
    'harvested',
    'hpj_confirmed',
  ];

  static const availableUnits = <String>[
    'each',
    'lb',
    'kg',
    'bunch',
    'dozen',
    'crate',
    'bag',
    'box',
  ];

  late String selectedStatus;
  late String selectedUnit;
  late DateTime selectedReadyDate;
  bool showInShop = true;
  bool saving = false;
  final Set<String> selectedBadges = <String>{};

  FarmerSupplyForecast get supply => widget.supply;

  @override
  void initState() {
    super.initState();
    cropNameController = TextEditingController(text: supply.cropName);
    expectedController = TextEditingController(
      text: _cleanNumber(supply.expectedQuantity),
    );
    harvestedController = TextEditingController(
      text: _cleanNumber(supply.harvestedQuantity),
    );
    priceController = TextEditingController();
    salePriceController = TextEditingController();
    lowStockController = TextEditingController();
    notesController = TextEditingController(text: supply.notes ?? '');

    selectedStatus = editableStatuses.contains(supply.status)
        ? supply.status
        : 'expected';

    selectedUnit = supply.unit.trim().isEmpty ? 'each' : supply.unit.trim();
    if (!availableUnits.contains(selectedUnit)) selectedUnit = 'each';

    selectedReadyDate = supply.expectedHarvestDate ?? DateTime.now();

    if (supply.isHpjConfirmed) selectedBadges.add('HPJ Confirmed');
    if (supply.isHarvestReady || supply.isHarvested) {
      selectedBadges.add('Live in Shop');
    }
    if (!supply.isActive) selectedBadges.add('Coming Soon');
  }

  @override
  void dispose() {
    cropNameController.dispose();
    expectedController.dispose();
    harvestedController.dispose();
    priceController.dispose();
    salePriceController.dispose();
    lowStockController.dispose();
    notesController.dispose();
    super.dispose();
  }

  String _cleanNumber(num? value) {
    if (value == null) return '';
    if (value == value.roundToDouble()) return value.toInt().toString();
    return value.toString();
  }

  String _statusDisplay(String value) {
    switch (value) {
      case 'planning':
        return 'Planning';
      case 'growing':
        return 'Growing';
      case 'expected':
        return 'Expected';
      case 'harvest_ready':
        return 'Ready soon';
      case 'harvested':
        return 'Harvested';
      case 'hpj_confirmed':
        return 'HPJ confirmed';
      default:
        return 'Pending';
    }
  }

  String _approvalLine() {
    if (supply.isHpjConfirmed) {
      return 'Your crop is confirmed by HPJ and ready for matching.';
    }
    return 'Keep this crop updated so HPJ can match it with buyer demand.';
  }

  String _formatDate(DateTime date) {
    const months = [
      'Jan','Feb','Mar','Apr','May','Jun',
      'Jul','Aug','Sep','Oct','Nov','Dec'
    ];
    return '${date.day} ${months[date.month - 1]} ${date.year}';
  }

  Future<void> _pickReadyDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: selectedReadyDate,
      firstDate: DateTime.now().subtract(const Duration(days: 365)),
      lastDate: DateTime.now().add(const Duration(days: 730)),
    );
    if (picked != null) setState(() => selectedReadyDate = picked);
  }

  Future<void> _save() async {
    final cropName = cropNameController.text.trim();
    final expected = double.tryParse(expectedController.text.trim());
    final harvested = double.tryParse(harvestedController.text.trim());

    if (cropName.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Enter the crop name.')),
      );
      return;
    }

    if (expected == null || expected < 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Enter a valid amount.')),
      );
      return;
    }

    setState(() => saving = true);

    try {
      await updateFarmerSupplyForecast(
        forecastId: supply.id,
        cropName: cropName,
        expectedQuantity: expected,
        harvestedQuantity: harvested,
        unit: selectedUnit,
        expectedHarvestDate: selectedReadyDate,
        status: selectedStatus,
        notes: notesController.text.trim(),
      );

      if (!mounted) return;
      Navigator.of(context).pop(true);
    } catch (error) {
      if (!mounted) return;
      setState(() => saving = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            error.toString().replaceFirst('Exception: ', ''),
          ),
        ),
      );
    }
  }

  Future<void> _cancelSupply() async {
    final confirm = await showDialog<bool>(
          context: context,
          builder: (context) => AlertDialog(
            title: const Text('Mark this crop unavailable?'),
            content: const Text(
              'The crop stays in your history, but it will no longer be treated as active supply.',
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(context).pop(false),
                child: const Text('Keep'),
              ),
              FilledButton(
                onPressed: () => Navigator.of(context).pop(true),
                child: const Text('Mark unavailable'),
              ),
            ],
          ),
        ) ??
        false;

    if (!confirm) return;

    setState(() => saving = true);

    try {
      await cancelFarmerSupplyForecast(supply.id);
      if (!mounted) return;
      Navigator.of(context).pop(true);
    } catch (error) {
      if (!mounted) return;
      setState(() => saving = false);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            error.toString().replaceFirst('Exception: ', ''),
          ),
        ),
      );
    }
  }

  Widget _fieldLabel(IconData icon, String label) {
    return Row(
      children: [
        Icon(icon, size: 18, color: FarmColors.primary),
        const SizedBox(width: 8),
        Text(
          label,
          style: const TextStyle(
            color: FarmColors.ink,
            fontSize: 12.5,
            fontWeight: FontWeight.w800,
          ),
        ),
      ],
    );
  }

  Widget _badgeChip(String label, {Color? color}) {
    final active = selectedBadges.contains(label);
    final accent = color ?? FarmColors.primary;
    return FilterChip(
      selected: active,
      onSelected: (value) {
        setState(() {
          if (value) {
            selectedBadges.add(label);
          } else {
            selectedBadges.remove(label);
          }
        });
      },
      label: Text(label),
      selectedColor: accent.withOpacity(.14),
      checkmarkColor: accent,
      labelStyle: TextStyle(
        color: active ? accent : FarmColors.ink,
        fontWeight: FontWeight.w700,
        fontSize: 11,
      ),
      backgroundColor: Colors.white,
    );
  }

