class _FarmerSupplyCard extends StatelessWidget {

  final String farmerId;
  final FarmerSupplyForecast supply;
  final VoidCallback onChanged;

  const _FarmerSupplyCard({
    required this.farmerId,
    required this.supply,
    required this.onChanged,
  });

  String _quantity(double? value) {
    if (value == null) return '—';

    final text = value == value.roundToDouble()
        ? value.toInt().toString()
        : value.toStringAsFixed(1);

    return '$text ${supply.unit}';
  }

  String _dateLabel(DateTime? date) {
    if (date == null) return 'Not set';

    const months = [
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];

    return '${date.day} ${months[date.month - 1]} ${date.year}';
  }

  Color _statusColor() {
    if (supply.isHpjConfirmed) {
      return FarmColors.green;
    }

    if (supply.isHarvested || supply.isHarvestReady) {
      return FarmColors.warning;
    }

    if (supply.isCancelled) {
      return FarmColors.danger;
    }

    return FarmColors.deepGreen;
  }

  bool get _locked {
    return supply.isHpjConfirmed || supply.isCompleted || supply.isCancelled;
  }

  Widget _metric({
    required String label,
    required String value,
  }) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.symmetric(
          horizontal: 10,
          vertical: 9,
        ),
        decoration: BoxDecoration(
          color: FarmColors.cardSoft,
          borderRadius: BorderRadius.circular(14),
          border: Border.all(
            color: FarmColors.line,
          ),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: FarmColors.mutedText,
                fontSize: 9.5,
                fontWeight: FontWeight.w700,
              ),
            ),
            const SizedBox(height: 3),
            Text(
              value,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: FarmColors.ink,
                fontSize: 13,
                fontWeight: FontWeight.w900,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _openShopListing(
    BuildContext context,
  ) async {
    final sent = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _FarmerExistingSupplyShopRequestSheet(
        farmerId: farmerId,
        supply: supply,
      ),
    );

    if (sent != true || !context.mounted) return;

    onChanged();

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${supply.cropName} was sent to HPJ for Shop review.',
        ),
      ),
    );
  }

  Future<void> _openMarketAndPrice(
    BuildContext context,
  ) async {
    final changed = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _FarmerSupplyMarketDealSheet(
        supply: supply,
      ),
    );

    if (changed == true) {
      onChanged();
    }
  }

  Future<void> _openUpdate(
    BuildContext context,
  ) async {
    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _FarmerSupplyUpdateSheet(
        supply: supply,
      ),
    );

    if (saved != true) return;

    onChanged();

    if (!context.mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${supply.cropName} updated.',
        ),
      ),
    );
  }

  Future<void> _repostSupply(
    BuildContext context,
  ) async {
    final posted = await _showFarmerRepostProduceSheet(
      context,
      supply,
    );

    if (posted != true || !context.mounted) return;

    onChanged();

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${supply.cropName} posted again.',
        ),
      ),
    );
  }

  Future<void> _confirmStillAccurate(
    BuildContext context,
  ) async {
    try {
      await updateFarmerSupplyForecast(
        forecastId: supply.id,
        expectedQuantity: supply.expectedQuantity,
        harvestedQuantity: supply.harvestedQuantity,
        status: supply.status,
      );

      onChanged();

      if (!context.mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${supply.cropName} confirmed as current.',
          ),
        ),
      );
    } catch (error) {
      if (!context.mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            error.toString().replaceFirst(
                  'Exception: ',
                  '',
                ),
          ),
        ),
      );
    }
  }

  Future<void> _cancelSupply(
    BuildContext context,
  ) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: const Text(
            'Cancel crop report?',
          ),
          content: Text(
            '${supply.cropName} will be removed from your active supply planning.',
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(
                  dialogContext,
                  false,
                );
              },
              child: const Text('Keep'),
            ),
            TextButton(
              onPressed: () {
                Navigator.pop(
                  dialogContext,
                  true,
                );
              },
              child: const Text('Cancel report'),
            ),
          ],
        );
      },
    );

    if (confirmed != true) return;

    try {
      await cancelFarmerSupplyForecast(
        supply.id,
      );

      onChanged();

      if (!context.mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${supply.cropName} cancelled.',
          ),
        ),
      );
    } catch (error) {
      if (!context.mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            error.toString().replaceFirst('Exception: ', ''),
          ),
        ),
      );
    }
  }
  @override
  Widget build(BuildContext context) {
    final color = _statusColor();
    final category = (supply.category ?? '').trim();
    final notes = (supply.notes ?? '').trim();
    final needsReview = _farmerSupplyNeedsReview(supply);

    return Container(
      padding: const EdgeInsets.all(15),
      decoration: BoxDecoration(
        color: FarmColors.card,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(
          color: needsReview
              ? FarmColors.warning.withOpacity(0.30)
              : FarmColors.line,
        ),
        boxShadow: [
          BoxShadow(
            color: const Color(0xFF173B30).withOpacity(0.06),
            blurRadius: 18,
            offset: const Offset(0, 7),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                padding: const EdgeInsets.all(3),
                decoration: BoxDecoration(
                  color: FarmColors.primarySoft,
                  borderRadius: BorderRadius.circular(18),
                  border: Border.all(color: FarmColors.line),
                ),
                child: HpjProductThumb(
                  productName: supply.cropName,
                  size: 60,
                  radius: 15,
                ),
              ),
              const SizedBox(width: 11),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      supply.cropName,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 17,
                        fontWeight: FontWeight.w900,
                        letterSpacing: -0.2,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      [
                        if (category.isNotEmpty) category,
                        supply.unit,
                      ].join(' • '),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 10,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 8),
              Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 9, vertical: 6),
                decoration: BoxDecoration(
                  color: color.withOpacity(0.10),
                  borderRadius: BorderRadius.circular(999),
                  border: Border.all(color: color.withOpacity(0.16)),
                ),
                child: Text(
                  supply.statusLabel,
                  style: TextStyle(
                    color: color,
                    fontSize: 9,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
            ],
          ),

          const SizedBox(height: 13),

          Row(
            children: [
              _metric(
                label: 'Growing',
                value: _quantity(supply.quantityGrowing),
              ),
              const SizedBox(width: 7),
              _metric(
                label: 'Expected',
                value: _quantity(supply.expectedQuantity),
              ),
              const SizedBox(width: 7),
              _metric(
                label: 'Harvested',
                value: _quantity(supply.harvestedQuantity),
              ),
            ],
          ),

          const SizedBox(height: 11),

          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(11),
            decoration: BoxDecoration(
              color: needsReview
                  ? const Color(0xFFFFF7E8)
                  : FarmColors.background,
              borderRadius: BorderRadius.circular(15),
              border: Border.all(
                color: needsReview
                    ? FarmColors.warning.withOpacity(0.28)
                    : FarmColors.line,
              ),
            ),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Icon(
                  needsReview
                      ? Icons.schedule_outlined
                      : Icons.event_available_outlined,
                  size: 18,
                  color:
                      needsReview ? FarmColors.warning : FarmColors.success,
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Expected harvest • ${_dateLabel(supply.expectedHarvestDate)}',
                        style: const TextStyle(
                          color: FarmColors.ink,
                          fontSize: 10.4,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        needsReview
                            ? '${_farmerSupplyFreshnessLabel(supply)} • Please confirm or update'
                            : _farmerSupplyFreshnessLabel(supply),
                        style: const TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 9.3,
                          height: 1.3,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),

          if (notes.isNotEmpty) ...[
            const SizedBox(height: 10),
            Text(
              notes,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: FarmColors.mutedText,
                fontSize: 10.2,
                height: 1.35,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],

          if (supply.isHpjConfirmed) ...[
            const SizedBox(height: 11),
            Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(
                horizontal: 11,
                vertical: 10,
              ),
              decoration: BoxDecoration(
                color: FarmColors.success.withOpacity(0.09),
                borderRadius: BorderRadius.circular(15),
                border: Border.all(
                  color: FarmColors.success.withOpacity(0.17),
                ),
              ),
              child: Row(
                children: [
                  const Icon(
                    Icons.verified_rounded,
                    color: FarmColors.success,
                    size: 18,
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      supply.hpjConfirmedQuantity == null
                          ? 'HPJ has confirmed this supply'
                          : 'HPJ confirmed ${_quantity(supply.hpjConfirmedQuantity)}',
                      style: const TextStyle(
                        color: FarmColors.success,
                        fontSize: 10.3,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ],

          if (supply.isActive || !_locked) ...[
            const SizedBox(height: 13),
            const Divider(height: 1),
            const SizedBox(height: 11),
          ],

          if (supply.isActive) ...[
            if (supply.isHpjConfirmed) ...[
              SizedBox(
                width: double.infinity,
                child: ElevatedButton.icon(
                  icon: const Icon(Icons.handshake_outlined, size: 17),
                  label: const Text('Market Allocation & Price'),
                  onPressed: () => _openMarketAndPrice(context),
                ),
              ),
              const SizedBox(height: 8),
            ],
            SizedBox(
              width: double.infinity,
              child: OutlinedButton.icon(
                icon: const Icon(Icons.storefront_outlined, size: 17),
                label: const Text('Request Customer Shop Listing'),
                onPressed: () => _openShopListing(context),
              ),
            ),
          ],

          const SizedBox(height: 8),
          SizedBox(
            width: double.infinity,
            child: OutlinedButton.icon(
              icon: const Icon(
                Icons.repeat_rounded,
                size: 17,
              ),
              label: Text(
                supply.isActive
                    ? 'Repost produce'
                    : 'Post again',
              ),
              onPressed: () => _repostSupply(context),
            ),
          ),

          if (!_locked) ...[
            if (needsReview) ...[
              const SizedBox(height: 8),
              SizedBox(
                width: double.infinity,
                child: FilledButton.icon(
                  icon: const Icon(Icons.check_rounded, size: 17),
                  label: const Text('Confirm Still Accurate'),
                  onPressed: () => _confirmStillAccurate(context),
                ),
              ),
            ],
            const SizedBox(height: 8),
            LayoutBuilder(
              builder: (context, constraints) {
                final narrow = constraints.maxWidth < 350;
                final update = OutlinedButton.icon(
                  icon: const Icon(Icons.edit_outlined, size: 17),
                  label: const Text('Update crop'),
                  onPressed: () => _openUpdate(context),
                );
                final cancel = TextButton.icon(
                  icon: const Icon(Icons.close_rounded, size: 16),
                  label: const Text('Cancel report'),
                  onPressed: () => _cancelSupply(context),
                );

                if (narrow) {
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      update,
                      const SizedBox(height: 4),
                      cancel,
                    ],
                  );
                }

                return Row(
                  children: [
                    Expanded(child: update),
                    const SizedBox(width: 8),
                    cancel,
                  ],
                );
              },
            ),
          ],
        ],
      ),
    );
  }
}

class FarmerProductsScreen extends StatelessWidget {
  final FarmerProfile profile;
  final int refreshKey;
  final VoidCallback onChanged;
  const FarmerProductsScreen(
      {super.key,
      required this.profile,
      required this.refreshKey,
      required this.onChanged});

  Future<void> openProductForm(BuildContext context) async {
    if (!profile.isApproved) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Admin must approve your farm before products can be submitted.',
          ),
        ),
      );
      return;
    }

    final nameController = TextEditingController();
    final priceController = TextEditingController();
    final stockController = TextEditingController();
    final unitController = TextEditingController(text: 'each');
    final descriptionController = TextEditingController();
    final imageController = TextEditingController();
    final originalPriceController = TextEditingController();
    final discountPriceController = TextEditingController();
    final discountPercentController = TextEditingController();
    final discountLabelController = TextEditingController();
    final estimatedReadyDateController = TextEditingController();
    final expectedStockController = TextEditingController();
    final subscribeSavePercentController = TextEditingController(text: '5');
    final dealRankController = TextEditingController(text: '10');

    String selectedCategory = productCategoryOptions.first;
    bool isOrganic = false;
    bool isLocal = true;
    bool isDiscountActive = false;
    bool readySoon = false;
    bool isDealOfDay = false;
    bool subscribeSaveEnabled = false;

    await showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            return Material(
              color: Colors.transparent,
              child: Container(
                padding: EdgeInsets.only(
                  left: 18,
                  right: 18,
                  top: 18,
                  bottom: MediaQuery.of(sheetContext).viewInsets.bottom + 24,
                ),
                decoration: const BoxDecoration(
                  color: FarmColors.cream,
                  borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
                ),
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const Text(
                        'Submit Product Listing',
                        style: TextStyle(
                          fontSize: 22,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      const SizedBox(height: 14),
                      TextField(
                        controller: nameController,
                        decoration:
                            const InputDecoration(labelText: 'Product name'),
                      ),
                      const SizedBox(height: 10),
                      DropdownButtonFormField<String>(
                        value: selectedCategory,
                        decoration:
                            const InputDecoration(labelText: 'Category'),
                        items: productCategoryOptions
                            .map(
                              (category) => DropdownMenuItem<String>(
                                value: category,
                                child: Text(category),
                              ),
                            )
                            .toList(),
                        onChanged: (value) {
                          if (value == null) return;
                          setSheetState(() {
                            selectedCategory = value;
                          });
                        },
                      ),
                      const SizedBox(height: 10),
                      SwitchListTile(
                        value: isOrganic,
                        title: const Text('Organic item'),
                        subtitle: Text(
                          isOrganic
                              ? 'This item will show as organic in the shop.'
                              : 'Turn on only if this item is organic.',
                        ),
                        activeColor: FarmColors.green,
                        onChanged: (value) {
                          setSheetState(() {
                            isOrganic = value;
                          });
                        },
                      ),
                      const SizedBox(height: 10),
                      TextField(
                        controller: priceController,
                        keyboardType: const TextInputType.numberWithOptions(
                            decimal: true),
                        decoration: const InputDecoration(labelText: 'Price'),
                      ),
                      const SizedBox(height: 10),
                      LayoutBuilder(
                        builder: (context, constraints) {
                          final stockField = TextField(
                            controller: stockController,
                            keyboardType: TextInputType.number,
                            decoration: const InputDecoration(
                                labelText: 'Stock quantity'),
                          );

                          final originSelector = LocalProductSelector(
                            value: isLocal,
                            onChanged: (value) =>
                                setSheetState(() => isLocal = value),
                          );

                          if (constraints.maxWidth < 520) {
                            return Column(
                              children: [
                                stockField,
                                const SizedBox(height: 10),
                                originSelector,
                              ],
                            );
                          }

                          return Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Expanded(child: stockField),
                              const SizedBox(width: 9),
                              Expanded(child: originSelector),
                            ],
                          );
                        },
                      ),
                      const SizedBox(height: 10),
                      SwitchListTile(
                        value: readySoon,
                        title: const Text('Ready soon item'),
                        subtitle: const Text(
                            'Let customers request a ready alert before this item is available.'),
                        activeColor: FarmColors.warning,
                        onChanged: (value) =>
                            setSheetState(() => readySoon = value),
                      ),
                      if (readySoon) ...[
                        TextField(
                          controller: estimatedReadyDateController,
                          decoration: const InputDecoration(
                              labelText: 'Estimated ready date',
                              helperText: 'Use YYYY-MM-DD'),
                        ),
                        const SizedBox(height: 10),
                        TextField(
                          controller: expectedStockController,
                          keyboardType: TextInputType.number,
                          decoration: const InputDecoration(
                              labelText: 'Expected quantity'),
                        ),
                        const SizedBox(height: 10),
                      ],
                      SwitchListTile(
                        value: isDiscountActive,
                        title: const Text('Discount / deal active'),
                        activeColor: FarmColors.warning,
                        onChanged: (value) =>
                            setSheetState(() => isDiscountActive = value),
                      ),
                      if (isDiscountActive) ...[
                        TextField(
                          controller: originalPriceController,
                          keyboardType: const TextInputType.numberWithOptions(
                              decimal: true),
                          decoration: const InputDecoration(
                              labelText: 'Original price'),
                        ),
                        const SizedBox(height: 10),
                        TextField(
                          controller: discountPriceController,
                          keyboardType: const TextInputType.numberWithOptions(
                              decimal: true),
                          decoration: const InputDecoration(
                              labelText: 'Discount price'),
                        ),
                        const SizedBox(height: 10),
                        TextField(
                          controller: discountPercentController,
                          keyboardType: const TextInputType.numberWithOptions(
                              decimal: true),
                          decoration: const InputDecoration(
                              labelText: 'Discount percent'),
                        ),
                        const SizedBox(height: 10),
                        TextField(
                          controller: discountLabelController,
                          decoration:
                              const InputDecoration(labelText: 'Deal label'),
                        ),
                        const SizedBox(height: 10),
                      ],
                      SwitchListTile(
                        value: isDealOfDay,
                        title: const Text('Deal of the Day'),
                        subtitle: const Text(
                            'Feature this item in the customer deal section.'),
                        activeColor: FarmColors.warning,
                        onChanged: (value) =>
                            setSheetState(() => isDealOfDay = value),
                      ),
                      if (isDealOfDay) ...[
                        TextField(
                          controller: dealRankController,
                          keyboardType: TextInputType.number,
                          decoration: const InputDecoration(
                            labelText: 'Deal display rank',
                            helperText: 'Lower numbers show first',
                          ),
                        ),
                        const SizedBox(height: 10),
                      ],
                      SwitchListTile(
                        value: subscribeSaveEnabled,
                        title: const Text('Subscribe & Save'),
                        subtitle: const Text(
                            'Let customers set up repeat orders for this item.'),
                        activeColor: FarmColors.success,
                        onChanged: (value) =>
                            setSheetState(() => subscribeSaveEnabled = value),
                      ),
                      if (subscribeSaveEnabled) ...[
                        TextField(
                          controller: subscribeSavePercentController,
                          keyboardType: const TextInputType.numberWithOptions(
                              decimal: true),
                          decoration: const InputDecoration(
                              labelText: 'Subscribe & Save discount %'),
                        ),
                        const SizedBox(height: 10),
                      ],
                      TextField(
                        controller: unitController,
                        decoration: const InputDecoration(
                          labelText: 'Unit',
                          hintText: 'each, bundle, dozen, lb...',
                        ),
                      ),
                      const SizedBox(height: 10),
                      Container(
                        width: double.infinity,
                        padding: const EdgeInsets.all(12),
                        decoration: BoxDecoration(
                          color: FarmColors.cream,
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(color: FarmColors.lightGreen),
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            const Text(
                              'Product Image',
                              style: TextStyle(fontWeight: FontWeight.bold),
                            ),
                            const SizedBox(height: 10),
                            productImagePreviewFromUrl(
                              imageUrl: imageController.text,
                            ),
                            const SizedBox(height: 10),
                            TextField(
                              controller: imageController,
                              onChanged: (_) => setSheetState(() {}),
                              decoration: const InputDecoration(
                                labelText: 'Image URL',
                                helperText:
                                    'Paste a hosted image URL from Supabase Storage or another trusted source.',
                              ),
                            ),
                            const SizedBox(height: 6),
                            Wrap(
                              spacing: 8,
                              runSpacing: 8,
                              children: [
                                TextButton.icon(
                                  icon: const Icon(Icons.clear),
                                  label: const Text('Clear Image'),
                                  onPressed: () {
                                    imageController.clear();
                                    setSheetState(() {});
                                  },
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 10),
                      TextField(
                        controller: descriptionController,
                        maxLines: 3,
                        decoration:
                            const InputDecoration(labelText: 'Description'),
                      ),
                      const SizedBox(height: 14),
                      PrimaryFarmButton(
                        label: 'Submit for Admin Approval',
                        onPressed: () async {
                          final messenger = ScaffoldMessenger.of(context);
                          try {
                            await createFarmerProduct(
                              farmer: profile,
                              name: nameController.text.trim(),
                              price: double.tryParse(
                                      priceController.text.trim()) ??
                                  0,
                              stockQuantity:
                                  int.tryParse(stockController.text.trim()) ??
                                      0,
                              category: selectedCategory,
                              isOrganic: isOrganic,
                              isLocal: isLocal,
                              unit: unitController.text.trim(),
                              imageUrl: imageController.text.trim().isEmpty
                                  ? null
                                  : imageController.text.trim(),
                              description: descriptionController.text.trim(),
                              isDiscountActive: isDiscountActive,
                              originalPrice: double.tryParse(
                                  originalPriceController.text.trim()),
                              discountPrice: double.tryParse(
                                  discountPriceController.text.trim()),
                              discountPercent: double.tryParse(
                                  discountPercentController.text.trim()),
                              discountLabel:
                                  discountLabelController.text.trim().isEmpty
                                      ? null
                                      : discountLabelController.text.trim(),
                              readySoon: readySoon,
                              estimatedReadyDate: estimatedReadyDateController
                                      .text
                                      .trim()
                                      .isEmpty
                                  ? null
                                  : estimatedReadyDateController.text.trim(),
                              expectedStockQuantity: int.tryParse(
                                  expectedStockController.text.trim()),
                              isDealOfDay: isDealOfDay,
                              dealRank:
                                  int.tryParse(dealRankController.text.trim()),
                              subscribeSaveEnabled: subscribeSaveEnabled,
                              subscribeSaveDiscountPercent: double.tryParse(
                                  subscribeSavePercentController.text.trim()),
                            );

                            if (sheetContext.mounted) {
                              Navigator.pop(sheetContext);
                              messenger.showSnackBar(
                                const SnackBar(
                                  content: Text(
                                      'Product submitted for admin approval.'),
                                ),
                              );
                            }

                            onChanged();
                          } catch (error) {
                            if (sheetContext.mounted) {
                              messenger.showSnackBar(
                                SnackBar(
                                  content: Text(
                                    error
                                        .toString()
                                        .replaceFirst('Exception: ', ''),
                                  ),
                                ),
                              );
                            }
                          }
                        },
                      ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    );

    nameController.dispose();
    priceController.dispose();
    stockController.dispose();
    unitController.dispose();
    descriptionController.dispose();
    imageController.dispose();
    originalPriceController.dispose();
    discountPriceController.dispose();
    discountPercentController.dispose();
    discountLabelController.dispose();
    estimatedReadyDateController.dispose();
    expectedStockController.dispose();
    subscribeSavePercentController.dispose();
    dealRankController.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FarmPage(
      child: ListView(
        padding: const EdgeInsets.fromLTRB(18, 18, 18, 96),
        children: [
          Row(
            children: [
              if (Navigator.of(context).canPop())
                IconButton(
                  tooltip: 'Back',
                  onPressed: () => Navigator.of(context).maybePop(),
                  icon: const Icon(
                    Icons.arrow_back_rounded,
                    color: FarmColors.deepGreen,
                  ),
                ),
              const Expanded(
                child: Text(
                  'My Products',
                  style: TextStyle(
                    color: FarmColors.ink,
                    fontSize: 24,
                    fontWeight: FontWeight.w900,
                    letterSpacing: -.4,
                  ),
                ),
              ),
              FilledButton(
                onPressed: () => openProductForm(context),
                style: FilledButton.styleFrom(
                  shape: const CircleBorder(),
                  padding: const EdgeInsets.all(11),
                ),
                child: const Icon(Icons.add_rounded),
              ),
            ],
          ),
          const SizedBox(height: 4),
          Text(
            profile.farmName.trim().isEmpty
                ? 'Your shop listings'
                : '${profile.farmName} listings',
            style: const TextStyle(
              color: FarmColors.mutedText,
              fontSize: 10,
              fontWeight: FontWeight.w700,
            ),
          ),
          const SizedBox(height: 14),
          FutureBuilder<List<Product>>(
            key: ValueKey('farmer-products-$refreshKey'),
            future: fetchFarmerProducts(profile.id),
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const SizedBox(
                    height: 420, child: SkeletonList(count: 3));
              }
              final products = snapshot.data ?? [];
              if (products.isEmpty) {
                return const FarmEmptyState(
                  icon: Icons.eco_outlined,
                  title: 'No products yet',
                  message:
                      'Approved farmers can submit listings for admin approval.',
                );
              }
              return Column(
                children: products
                    .map((product) => Padding(
                          padding: const EdgeInsets.only(bottom: 12),
                          child: FarmerProductListingCard(product: product),
                        ))
                    .toList(),
              );
            },
          ),
        ],
      ),
    );
  }
}


