class _PremiumFarmerHeroAction extends StatelessWidget {
  final IconData icon;
  final String label;
  final VoidCallback? onTap;
  final bool light;

  const _PremiumFarmerHeroAction({
    required this.icon,
    required this.label,
    required this.onTap,
    this.light = false,
  });

  @override
  Widget build(BuildContext context) {
    final enabled = onTap != null;
    final foreground = light
        ? (enabled ? FarmColors.deepGreen : FarmColors.mutedText)
        : Colors.white.withOpacity(enabled ? 0.95 : 0.42);

    return Material(
      color: light
          ? const Color(0xFFF5F8F2)
          : Colors.white.withOpacity(enabled ? 0.12 : 0.06),
      borderRadius: BorderRadius.circular(light ? 14 : 16),
      child: InkWell(
        borderRadius: BorderRadius.circular(light ? 14 : 16),
        onTap: onTap,
        child: Container(
          constraints: BoxConstraints(minHeight: light ? 39 : 44),
          padding: EdgeInsets.symmetric(
            horizontal: light ? 8 : 10,
            vertical: light ? 8 : 10,
          ),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(light ? 14 : 16),
            border: Border.all(
              color: light
                  ? const Color(0xFFDDE6DA)
                  : Colors.white.withOpacity(enabled ? 0.18 : 0.08),
            ),
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(icon, size: light ? 14 : 16, color: foreground),
              const SizedBox(width: 5),
              Flexible(
                child: Text(
                  label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(
                    color: foreground,
                    fontSize: light ? 9.6 : 10.8,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}


class _FarmerCoreActionsCard extends StatelessWidget {
  final int activeSupplyCount;
  final int supplyReviewCount;
  final int demandCount;
  final int upcomingCollectionCount;
  final double pendingPayout;
  final double heldPayout;
  final VoidCallback onOpenSupply;
  final VoidCallback onOpenDemand;
  final VoidCallback onOpenCollections;
  final VoidCallback onOpenPayments;

  const _FarmerCoreActionsCard({
    required this.activeSupplyCount,
    required this.supplyReviewCount,
    required this.demandCount,
    required this.upcomingCollectionCount,
    required this.pendingPayout,
    required this.heldPayout,
    required this.onOpenSupply,
    required this.onOpenDemand,
    required this.onOpenCollections,
    required this.onOpenPayments,
  });

  @override
  Widget build(BuildContext context) {
    final paymentTotal = pendingPayout + heldPayout;

    if (hpjUseMobileAppPresentation(context)) {
      return Container(
        padding: const EdgeInsets.fromLTRB(14, 13, 14, 14),
        decoration: BoxDecoration(
          color: const Color(0xFFFFFEFB),
          borderRadius: BorderRadius.circular(22),
          border: Border.all(color: const Color(0xFFDDE6DA)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Run your farm',
                        style: TextStyle(
                          color: FarmColors.deepGreen,
                          fontSize: 15.5,
                          fontWeight: FontWeight.w900,
                          letterSpacing: -0.25,
                        ),
                      ),
                      SizedBox(height: 2),
                      Text(
                        'Supply, demand, collections and payments.',
                        style: TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 9.5,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ),
                Icon(
                  Icons.arrow_forward_rounded,
                  color: FarmColors.mutedText,
                  size: 18,
                ),
              ],
            ),
            const SizedBox(height: 11),
            SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              physics: const BouncingScrollPhysics(),
              child: Row(
                children: [
                  SizedBox(
                    width: 108,
                    child: _PremiumFarmerActionTile(
                      icon: Icons.grass_rounded,
                      title: 'My Supply',
                      value: '$activeSupplyCount',
                      helper: supplyReviewCount > 0
