class _FarmerOperationsSnapshot {
  final List<FarmerOrderSummary> orders;
  final List<FarmerCollectionScheduleItem> collections;
  final List<FarmerPayout> payouts;

  const _FarmerOperationsSnapshot({
    required this.orders,
    required this.collections,
    required this.payouts,
  });
}

Future<_FarmerOperationsSnapshot> fetchFarmerOperationsSnapshot(
  FarmerProfile profile,
) async {
  var orders = <FarmerOrderSummary>[];
  var collections = <FarmerCollectionScheduleItem>[];
  var payouts = <FarmerPayout>[];

  try {
    orders = await fetchFarmerOrderSummaries(profile.id);
  } catch (error) {
    farmDebugLog('Farmer Operations — orders unavailable: $error');
  }

  try {
    collections = await fetchFarmerCollectionSchedule();
  } catch (error) {
    farmDebugLog('Farmer Operations — collections unavailable: $error');
  }

  try {
    payouts = await fetchFarmerPayouts(farmerId: profile.id);
  } catch (error) {
    farmDebugLog('Farmer Operations — payouts unavailable: $error');
  }

  return _FarmerOperationsSnapshot(
    orders: orders,
    collections: collections,
    payouts: payouts,
  );
}

class FarmerOperationsScreen extends StatelessWidget {
  final FarmerProfile profile;
  final int refreshKey;

  const FarmerOperationsScreen({
    super.key,
    required this.profile,
    required this.refreshKey,
  });

  void _open(BuildContext context, Widget screen) {
    Navigator.of(context).push(
      MaterialPageRoute<void>(builder: (_) => screen),
    );
  }

  @override
  Widget build(BuildContext context) {
    return FarmPage(
      child: FutureBuilder<_FarmerOperationsSnapshot>(
        key: ValueKey('farmer-operations-$refreshKey'),
        future: fetchFarmerOperationsSnapshot(profile),
        builder: (context, snapshot) {
          final data = snapshot.data ??
              const _FarmerOperationsSnapshot(
                orders: <FarmerOrderSummary>[],
                collections: <FarmerCollectionScheduleItem>[],
                payouts: <FarmerPayout>[],
              );

          final now = DateTime.now();
          final today = DateTime(now.year, now.month, now.day);

          final upcomingCollections = data.collections
              .where(
                (item) =>
                    !item.collectionDate.isBefore(today) &&
                    item.stopStatus != 'cancelled' &&
                    item.stopStatus != 'completed',
              )
              .toList();

          final completedCollections = data.collections
              .where(
                (item) =>
                    item.stopStatus == 'completed' ||
                    item.stopStatus == 'collected' ||
                    item.receivingStatus == 'completed',
              )
              .length;

          final pendingPayout = data.payouts
              .where((item) => item.payoutStatus == 'pending')
              .fold<double>(0, (sum, item) => sum + item.netAmount);

          final releasedPayout = data.payouts
              .where((item) => item.payoutStatus == 'released')
              .fold<double>(0, (sum, item) => sum + item.netAmount);

          if (hpjUseMobileAppPresentation(context)) {
            return _HpjFarmerOperationsMobileMvp(
              profile: profile,
              refreshKey: refreshKey,
              data: data,
              upcomingCollections: upcomingCollections,
              completedCollections: completedCollections,
              pendingPayout: pendingPayout,
              releasedPayout: releasedPayout,
            );
          }

          return ListView(
            physics: const AlwaysScrollableScrollPhysics(),
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 120),
            children: [
              _PremiumFarmerOperationsHero(
                farmName: profile.farmName,
                orders: data.orders.length,
                upcomingCollections: upcomingCollections.length,
                pendingPayout: pendingPayout,
                releasedPayout: releasedPayout,
              ),
              if (snapshot.connectionState == ConnectionState.waiting &&
                  snapshot.data == null) ...[
                const SizedBox(height: 10),
                const LinearProgressIndicator(minHeight: 2),
              ],
              const SizedBox(height: 18),
              const Text(
                'Run farm operations',
                style: TextStyle(
                  color: FarmColors.ink,
                  fontSize: 18,
                  fontWeight: FontWeight.w900,
                ),
              ),
              const SizedBox(height: 4),
              const Text(
                'Follow produce from order through collection, receiving and payment.',
                style: TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 10.5,
                  height: 1.35,
                  fontWeight: FontWeight.w600,
                ),
              ),
              const SizedBox(height: 11),
              LayoutBuilder(
                builder: (context, constraints) {
                  final wide = constraints.maxWidth >= 760;
                  final gap = 10.0;
                  final cardWidth =
                      wide ? (constraints.maxWidth - (gap * 3)) / 4 : (constraints.maxWidth - gap) / 2;

                  final actions = <Widget>[
                    _PremiumFarmerOperationsAction(
                      icon: Icons.receipt_long_outlined,
                      title: 'Orders',
                      value: '${data.orders.length}',
                      subtitle: 'Recent farm order lines',
                      onTap: () => _open(
                        context,
                        FarmerOrdersScreen(
                          profile: profile,
                          refreshKey: refreshKey,
                        ),
                      ),
                    ),
                    _PremiumFarmerOperationsAction(
                      icon: Icons.local_shipping_outlined,
                      title: 'Collections',
                      value: '${upcomingCollections.length}',
                      subtitle: 'Upcoming • $completedCollections completed',
                      onTap: () => _open(
                        context,
                        FarmerCollectionScheduleScreen(profile: profile),
                      ),
                    ),
                    _PremiumFarmerOperationsAction(
                      icon: Icons.payments_outlined,
                      title: 'Payments',
                      value: pendingPayout > 0
                          ? formatJmd(pendingPayout)
                          : 'Up to date',
                      subtitle: pendingPayout > 0
                          ? 'Pending release'
                          : '${formatJmd(releasedPayout)} released',
                      onTap: () => _open(
                        context,
                        FarmerEarningsScreen(
                          profile: profile,
                          refreshKey: refreshKey,
                        ),
                      ),
                    ),
                    _PremiumFarmerOperationsAction(
                      icon: Icons.description_outlined,
                      title: 'Activity',
                      value: 'PDF',
                      subtitle: 'Supply, collection & payout record',
                      onTap: () => _open(
                        context,
                        _FarmerActivityStatementScreen(profile: profile),
                      ),
                    ),
                  ];

                  return Wrap(
                    spacing: gap,
                    runSpacing: gap,
                    children: actions
                        .map(
                          (item) => SizedBox(
                            width: cardWidth,
                            child: item,
                          ),
                        )
                        .toList(),
                  );
                },
              ),
              const SizedBox(height: 14),
              Container(
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: const Color(0xFFF5F7F2),
                  borderRadius: BorderRadius.circular(18),
                  border: Border.all(color: FarmColors.line),
                ),
                child: const Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(
                      Icons.route_outlined,
                      color: FarmColors.primary,
                      size: 20,
                    ),
                    SizedBox(width: 10),
                    Expanded(
                      child: Text(
                        'My Supply is where you report what you can grow or harvest. '
                        'Operations begins when HPJ starts moving that supply through '
                        'orders, collections, receiving and farmer payments.',
                        style: TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 10.2,
                          height: 1.4,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

class _HpjFarmerOperationsMobileMvp extends StatelessWidget {
  final FarmerProfile profile;
  final int refreshKey;
  final _FarmerOperationsSnapshot data;
  final List<FarmerCollectionScheduleItem> upcomingCollections;
  final int completedCollections;
  final double pendingPayout;
  final double releasedPayout;

  const _HpjFarmerOperationsMobileMvp({
    required this.profile,
    required this.refreshKey,
    required this.data,
    required this.upcomingCollections,
    required this.completedCollections,
    required this.pendingPayout,
    required this.releasedPayout,
  });

  void _open(BuildContext context, Widget screen) {
    Navigator.of(context).push(
      MaterialPageRoute<void>(builder: (_) => screen),
    );
  }

  int get pendingReceiving => data.collections
      .where(
        (item) =>
            (item.stopStatus == 'completed' || item.stopStatus == 'collected') &&
            item.receivingStatus != 'completed',
      )
      .length;

  List<_HpjFarmerOperationEvent> _events() {
    final events = <_HpjFarmerOperationEvent>[];

    if (data.orders.isNotEmpty) {
      final order = data.orders.first;
      events.add(
        _HpjFarmerOperationEvent(
          icon: Icons.receipt_long_outlined,
          title: 'Order line created',
          subtitle: '${order.productName} • Qty ${order.quantity}',
          dateLabel: 'Recent',
          status: 'Recorded',
          statusColor: const Color(0xFF006B3D),
          statusBackground: const Color(0xFFE4F5E7),
        ),
      );
    }

    if (upcomingCollections.isNotEmpty) {
      final next = upcomingCollections.first;
      events.add(
        _HpjFarmerOperationEvent(
          icon: Icons.local_shipping_outlined,
          title: 'Pickup scheduled',
          subtitle: next.productName,
          dateLabel: _farmerPartnerDate(next.collectionDate),
          status: 'Scheduled',
          statusColor: const Color(0xFF2467C8),
          statusBackground: const Color(0xFFE7F0FF),
        ),
      );
    }

    final pending = data.payouts
        .where((item) => item.payoutStatus == 'pending')
        .toList(growable: false);
    if (pending.isNotEmpty) {
      final payout = pending.first;
      events.add(
        _HpjFarmerOperationEvent(
          icon: Icons.account_balance_wallet_outlined,
          title: 'Payout pending',
          subtitle: formatJmd(payout.netAmount),
          dateLabel: payout.createdAt == null
              ? 'Pending'
              : _farmerPartnerDate(payout.createdAt!),
          status: 'Pending',
          statusColor: const Color(0xFFA96800),
          statusBackground: const Color(0xFFFFF1D5),
        ),
      );
    }

    final completed = data.collections
        .where(
          (item) =>
              item.stopStatus == 'completed' ||
              item.stopStatus == 'collected' ||
              item.receivingStatus == 'completed',
        )
        .toList(growable: false);
    if (completed.isNotEmpty) {
      final item = completed.first;
      events.add(
        _HpjFarmerOperationEvent(
          icon: Icons.inventory_2_outlined,
          title: 'Collection completed',
          subtitle: item.productName,
          dateLabel: _farmerPartnerDate(item.collectionDate),
          status: 'Completed',
          statusColor: const Color(0xFF006B3D),
          statusBackground: const Color(0xFFE4F5E7),
        ),
      );
    }

    if (events.isEmpty) {
      events.add(
        const _HpjFarmerOperationEvent(
          icon: Icons.history_rounded,
          title: 'No recent operations yet',
          subtitle: 'New orders, collections and payouts will appear here.',
          dateLabel: '',
          status: 'Ready',
          statusColor: Color(0xFF006B3D),
          statusBackground: Color(0xFFE4F5E7),
        ),
      );
    }

    return events.take(4).toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    final nextCollection =
        upcomingCollections.isEmpty ? null : upcomingCollections.first;
    final events = _events();

    Widget quickStat({
      required IconData icon,
      required String value,
      required String label,
      required VoidCallback onTap,
    }) {
      return Expanded(
        child: Material(
          color: Colors.white,
          borderRadius: BorderRadius.circular(17),
          child: InkWell(
            onTap: onTap,
            borderRadius: BorderRadius.circular(17),
            child: Container(
              height: 88,
              padding: const EdgeInsets.all(10),
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(17),
                border: Border.all(
                  color: const Color(0xFFDDE7DD),
                ),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Icon(
                    icon,
