            quickStat(
              icon: Icons.receipt_long_outlined,
              value: '${data.orders.length}',
              label: 'Orders',
              onTap: () => _open(
                context,
                FarmerOrdersScreen(
                  profile: profile,
                  refreshKey: refreshKey,
                ),
              ),
            ),
            const SizedBox(width: 8),
            quickStat(
              icon: Icons.local_shipping_outlined,
              value: '${upcomingCollections.length}',
              label: 'Pickups',
              onTap: () => _open(
                context,
                FarmerCollectionScheduleScreen(profile: profile),
              ),
            ),
            const SizedBox(width: 8),
            quickStat(
              icon: Icons.account_balance_wallet_outlined,
              value: formatJmd(pendingPayout),
              label: 'Pending',
              onTap: () => _open(
                context,
                FarmerEarningsScreen(
                  profile: profile,
                  refreshKey: refreshKey,
                ),
              ),
            ),
          ],
        ),

        const SizedBox(height: 14),

        _HpjFarmerNextCollectionCard(
          item: nextCollection,
          onTap: () => _open(
            context,
            FarmerCollectionScheduleScreen(profile: profile),
          ),
        ),

        const SizedBox(height: 14),
        const Text(
          'Manage',
          style: TextStyle(
            color: FarmColors.ink,
            fontSize: 17,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 9),

        actionCard(
          icon: Icons.receipt_long_outlined,
          title: 'Orders',
          value: '${data.orders.length}',
          onTap: () => _open(
            context,
            FarmerOrdersScreen(
              profile: profile,
              refreshKey: refreshKey,
            ),
          ),
        ),
        const SizedBox(height: 8),
        actionCard(
          icon: Icons.local_shipping_outlined,
          title: 'Collections',
          value: '${upcomingCollections.length}',
          onTap: () => _open(
            context,
            FarmerCollectionScheduleScreen(profile: profile),
          ),
        ),
        const SizedBox(height: 8),
        actionCard(
          icon: Icons.account_balance_wallet_outlined,
          title: 'Payments',
          value: formatJmd(pendingPayout),
          onTap: () => _open(
            context,
            FarmerEarningsScreen(
              profile: profile,
              refreshKey: refreshKey,
            ),
          ),
        ),

        if (events.isNotEmpty) ...[
          const SizedBox(height: 14),
          _HpjFarmerRecentOperationsCard(
            events: events.take(3).toList(growable: false),
            onViewAll: () => _open(
              context,
              _FarmerActivityStatementScreen(profile: profile),
            ),
          ),
        ],
      ],
    );
  }
}

class _HpjFarmerOperationsHeroMobile extends StatelessWidget {
  final int orderCount;
  final int collectionCount;
  final double pendingPayout;

  const _HpjFarmerOperationsHeroMobile({
    required this.orderCount,
    required this.collectionCount,
    required this.pendingPayout,
  });

  Widget _metric({
    required IconData icon,
    required String value,
    required String label,
  }) {
    return Expanded(
      child: Container(
        height: 102,
        padding: const EdgeInsets.fromLTRB(10, 9, 8, 8),
        decoration: BoxDecoration(
          color: Colors.white.withOpacity(.105),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: Colors.white.withOpacity(.22)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              width: 31,
              height: 31,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: Colors.white.withOpacity(.12),
                borderRadius: BorderRadius.circular(10),
              ),
              child: Icon(icon, color: Colors.white, size: 17),
            ),
            const SizedBox(height: 8),
            FittedBox(
              fit: BoxFit.scaleDown,
              alignment: Alignment.centerLeft,
              child: Text(
                value,
                maxLines: 1,
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 15.2,
                  height: 1,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
            const SizedBox(height: 4),
            Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: Colors.white,
                fontSize: 10.2,
                height: 1,
                fontWeight: FontWeight.w900,
              ),
            ),
          ],
        ),
      ),
    );
  }

  String _compactJmd(double value) {
    if (value == value.roundToDouble()) {
      return 'J\$${value.toStringAsFixed(0)}';
    }
    return formatJmd(value);
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      height: 286,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(26),
        gradient: const LinearGradient(
          begin: Alignment.topLeft,
