class FarmerOrdersScreen extends StatefulWidget {
  final FarmerProfile profile;
  final int refreshKey;

  const FarmerOrdersScreen({
    super.key,
    required this.profile,
    required this.refreshKey,
  });

  @override
  State<FarmerOrdersScreen> createState() => _FarmerOrdersScreenState();
}

class _FarmerOrdersScreenState extends State<FarmerOrdersScreen> {
  final TextEditingController _searchController = TextEditingController();
  String _filter = 'all';
  int _localRefreshKey = 0;

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  Future<void> _refresh() async {
    setState(() => _localRefreshKey++);
  }

  List<FarmerOrderSummary> _visibleOrders(
    List<FarmerOrderSummary> orders,
  ) {
    final query = _searchController.text.trim().toLowerCase();

    return orders.where((order) {
      final matchesSearch = query.isEmpty ||
          order.productName.toLowerCase().contains(query) ||
          order.shortOrderId.toLowerCase().contains(query);

      if (!matchesSearch) return false;

      switch (_filter) {
        case 'earning':
          return order.farmerEarningAmount > 0;
        case 'unpaid':
          return order.farmerEarningAmount <= 0;
        default:
          return true;
      }
    }).toList(growable: false);
  }

  void _openOrderDetails(
    BuildContext context,
    FarmerOrderSummary order,
  ) {
    showModalBottomSheet<void>(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        final hasEarning = order.farmerEarningAmount > 0;

        Widget detailRow(
          IconData icon,
          String label,
          String value,
        ) {
          return Padding(
            padding: const EdgeInsets.symmetric(vertical: 8),
            child: Row(
              children: [
                Container(
                  width: 36,
                  height: 36,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: const Color(0xFFEAF5E9),
                    borderRadius: BorderRadius.circular(11),
                  ),
                  child: Icon(
                    icon,
                    color: FarmColors.primary,
                    size: 18,
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        label,
                        style: const TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 8.8,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      const SizedBox(height: 2),
                      Text(
                        value,
                        style: const TextStyle(
                          color: FarmColors.ink,
                          fontSize: 12,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          );
        }

        return Container(
          decoration: const BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
          ),
          child: SafeArea(
            top: false,
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(18, 12, 18, 24),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Center(
                    child: Container(
                      width: 42,
                      height: 4,
                      decoration: BoxDecoration(
                        color: FarmColors.line,
                        borderRadius: BorderRadius.circular(99),
                      ),
                    ),
                  ),
                  const SizedBox(height: 16),
                  Row(
                    children: [
                      HpjProductThumb(
                        productName: order.productName,
                        size: 70,
                        radius: 18,
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              order.productName,
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                color: FarmColors.ink,
                                fontSize: 20,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              'Order #${order.shortOrderId}',
                              style: const TextStyle(
                                color: FarmColors.mutedText,
                                fontSize: 10,
                                fontWeight: FontWeight.w700,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 14),
                  detailRow(
                    Icons.inventory_2_outlined,
                    'Quantity',
                    '${order.quantity}',
                  ),
                  detailRow(
                    Icons.receipt_long_outlined,
                    'Order value',
                    formatJmd(order.lineTotal),
                  ),
                  detailRow(
                    Icons.account_balance_wallet_outlined,
                    'Your earning',
                    hasEarning
                        ? formatJmd(order.farmerEarningAmount)
                        : 'Not recorded yet',
                  ),
                  const SizedBox(height: 8),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: hasEarning
                          ? const Color(0xFFEAF5E9)
                          : const Color(0xFFFFF6E7),
                      borderRadius: BorderRadius.circular(15),
                    ),
                    child: Row(
                      children: [
                        Icon(
                          hasEarning
                              ? Icons.check_circle_outline_rounded
                              : Icons.schedule_rounded,
                          color: hasEarning
                              ? FarmColors.primary
                              : const Color(0xFFB56A0D),
                          size: 20,
                        ),
                        const SizedBox(width: 9),
                        Expanded(
                          child: Text(
                            hasEarning
                                ? 'Farmer earning has been recorded.'
                                : 'HPJ has not recorded a farmer earning for this line yet.',
                            style: const TextStyle(
                              color: FarmColors.ink,
                              fontSize: 9.5,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 14),
                  SizedBox(
                    width: double.infinity,
                    child: FilledButton(
                      onPressed: () => Navigator.of(sheetContext).pop(),
                      child: const Text('Done'),
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _summaryTile({
    required String value,
    required String label,
    required IconData icon,
  }) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.fromLTRB(10, 10, 10, 9),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: const Color(0xFFDDE7DD)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(icon, color: FarmColors.primary, size: 18),
            const SizedBox(height: 8),
            FittedBox(
              fit: BoxFit.scaleDown,
              alignment: Alignment.centerLeft,
              child: Text(
                value,
                style: const TextStyle(
                  color: FarmColors.ink,
                  fontSize: 15,
                  fontWeight: FontWeight.w900,
                ),
              ),
