  }

  Widget _orderCard(FarmerOrderSummary order) {
    final hasEarning = order.farmerEarningAmount > 0;

    return Material(
      color: Colors.white,
      borderRadius: BorderRadius.circular(18),
      child: InkWell(
        onTap: () => _openOrderDetails(context, order),
        borderRadius: BorderRadius.circular(18),
        child: Container(
          padding: const EdgeInsets.all(11),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(18),
            border: Border.all(color: const Color(0xFFDDE7DD)),
          ),
          child: Row(
            children: [
              HpjProductThumb(
                productName: order.productName,
                size: 58,
                radius: 14,
              ),
              const SizedBox(width: 11),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      order.productName,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 13.5,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      'Order #${order.shortOrderId} • Qty ${order.quantity}',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 8.8,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 7),
                    Row(
                      children: [
                        Text(
                          formatJmd(order.lineTotal),
                          style: const TextStyle(
                            color: FarmColors.ink,
                            fontSize: 10.5,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        const SizedBox(width: 8),
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 7,
                            vertical: 4,
                          ),
                          decoration: BoxDecoration(
                            color: hasEarning
                                ? const Color(0xFFEAF5E9)
                                : const Color(0xFFFFF4DE),
                            borderRadius: BorderRadius.circular(999),
                          ),
                          child: Text(
                            hasEarning
                                ? 'Earn ${formatJmd(order.farmerEarningAmount)}'
                                : 'Pending earning',
                            style: TextStyle(
                              color: hasEarning
                                  ? FarmColors.deepGreen
                                  : const Color(0xFFB56A0D),
                              fontSize: 7.6,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
              const Icon(
                Icons.chevron_right_rounded,
                color: FarmColors.primary,
              ),
            ],
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return FarmPage(
      child: FutureBuilder<List<FarmerOrderSummary>>(
        key: ValueKey(
          'farmer-orders-${widget.refreshKey}-$_localRefreshKey',
        ),
        future: fetchFarmerOrderSummaries(widget.profile.id),
        builder: (context, snapshot) {
          final orders = snapshot.data ?? const <FarmerOrderSummary>[];
          final visible = _visibleOrders(orders);

          final totalSales = orders.fold<double>(
            0,
            (sum, order) => sum + order.lineTotal,
          );
          final farmerEarnings = orders.fold<double>(
            0,
            (sum, order) => sum + order.farmerEarningAmount,
          );

          return RefreshIndicator(
            onRefresh: _refresh,
            child: ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.fromLTRB(14, 14, 14, 110),
              children: [
                Row(
                  children: [
                    if (Navigator.of(context).canPop())
                      IconButton(
                        tooltip: 'Back',
                        onPressed: () => Navigator.of(context).maybePop(),
                        icon: const Icon(
                          Icons.arrow_back_rounded,
                          color: FarmColors.deepGreen,
                        ),
                      ),
                    const Expanded(
                      child: Text(
                        'Orders',
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontSize: 24,
                          fontWeight: FontWeight.w900,
                          letterSpacing: -.4,
                        ),
                      ),
                    ),
                    IconButton(
                      tooltip: 'Refresh orders',
                      onPressed: () => _refresh(),
                      icon: const Icon(
                        Icons.refresh_rounded,
                        color: FarmColors.primary,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 2),
                const Text(
                  'Tap any order for details.',
                  style: TextStyle(
                    color: FarmColors.mutedText,
                    fontSize: 10.5,
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 13),

                Row(
                  children: [
                    _summaryTile(
                      value: '${orders.length}',
                      label: 'Order lines',
                      icon: Icons.receipt_long_outlined,
                    ),
                    const SizedBox(width: 8),
                    _summaryTile(
                      value: formatJmd(totalSales),
                      label: 'Order value',
                      icon: Icons.shopping_bag_outlined,
                    ),
                    const SizedBox(width: 8),
                    _summaryTile(
                      value: formatJmd(farmerEarnings),
                      label: 'Earnings',
                      icon: Icons.account_balance_wallet_outlined,
                    ),
                  ],
                ),

                const SizedBox(height: 14),
                TextField(
                  controller: _searchController,
                  onChanged: (_) => setState(() {}),
                  decoration: InputDecoration(
                    hintText: 'Search crop or order',
                    prefixIcon: const Icon(Icons.search_rounded),
                    suffixIcon: _searchController.text.trim().isEmpty
                        ? null
                        : IconButton(
                            tooltip: 'Clear search',
                            onPressed: () {
                              _searchController.clear();
                              setState(() {});
                            },
                            icon: const Icon(Icons.close_rounded),
                          ),
                    filled: true,
                    fillColor: Colors.white,
                    isDense: true,
                    contentPadding: const EdgeInsets.symmetric(
                      horizontal: 12,
                      vertical: 12,
                    ),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(16),
                      borderSide: const BorderSide(
                        color: Color(0xFFDDE7DD),
                      ),
                    ),
                    enabledBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(16),
                      borderSide: const BorderSide(
                        color: Color(0xFFDDE7DD),
                      ),
                    ),
                  ),
                ),
                const SizedBox(height: 9),

                SingleChildScrollView(
                  scrollDirection: Axis.horizontal,
                  child: Row(
                    children: [
                      ChoiceChip(
                        selected: _filter == 'all',
                        onSelected: (_) =>
                            setState(() => _filter = 'all'),
                        label: Text('All ${orders.length}'),
                      ),
                      const SizedBox(width: 7),
                      ChoiceChip(
                        selected: _filter == 'earning',
                        onSelected: (_) =>
                            setState(() => _filter = 'earning'),
                        label: Text(
                          'With earnings ${orders.where((o) => o.farmerEarningAmount > 0).length}',
                        ),
                      ),
                      const SizedBox(width: 7),
                      ChoiceChip(
                        selected: _filter == 'unpaid',
                        onSelected: (_) =>
                            setState(() => _filter = 'unpaid'),
                        label: Text(
                          'Pending ${orders.where((o) => o.farmerEarningAmount <= 0).length}',
                        ),
                      ),
                    ],
                  ),
                ),

                if (snapshot.connectionState == ConnectionState.waiting &&
                    snapshot.data == null) ...[
                  const SizedBox(height: 10),
                  const LinearProgressIndicator(minHeight: 2),
                ],

                const SizedBox(height: 14),
                Row(
                  children: [
                    const Expanded(
                      child: Text(
                        'Order activity',
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontSize: 17,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                    Text(
                      '${visible.length}',
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 10,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 9),

                if (visible.isEmpty)
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 14,
                      vertical: 20,
                    ),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(18),
                      border: Border.all(
                        color: const Color(0xFFDDE7DD),
                      ),
                    ),
                    child: const Row(
                      children: [
                        Icon(
                          Icons.receipt_long_outlined,
                          color: FarmColors.primary,
                        ),
                        SizedBox(width: 10),
                        Expanded(
                          child: Text(
                            'No orders match this view.',
                            style: TextStyle(
                              color: FarmColors.mutedText,
                              fontSize: 10.5,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ),
                      ],
                    ),
                  )
                else
                  ...visible.take(40).map(
                    (order) => Padding(
                      padding: const EdgeInsets.only(bottom: 9),
                      child: _orderCard(order),
                    ),
                  ),
              ],
            ),
          );
        },
      ),
    );
  }
}

