class _PremiumFarmerPaymentsHero extends StatelessWidget {
  final String farmName;
  final double pending;
  final double released;
  final double held;
  final int payoutCount;

  const _PremiumFarmerPaymentsHero({
    required this.farmName,
    required this.pending,
    required this.released,
    required this.held,
    required this.payoutCount,
  });

  Widget _metric({
    required String value,
    required String label,
  }) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 10),
        decoration: BoxDecoration(
          color: const Color(0xFFF3F8F1),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: Colors.white.withOpacity(.16)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              value,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: FarmColors.ink,
                fontSize: 14,
                fontWeight: FontWeight.w900,
              ),
            ),
            const SizedBox(height: 3),
            Text(
              label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: TextStyle(
                color: FarmColors.mutedText,
                fontSize: 8.8,
                fontWeight: FontWeight.w800,
              ),
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(13),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(20),
        color: const Color(0xFFF8FBF6),
        border: Border.all(color: const Color(0xFFDDE6DA)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'FARM PAYMENTS',
            style: TextStyle(
              color: FarmColors.mutedText,
              fontSize: 10.5,
              fontWeight: FontWeight.w900,
              letterSpacing: .9,
            ),
          ),
          const SizedBox(height: 5),
          Text(
            pending > 0 ? formatJmd(pending) : 'No pending payout',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              color: FarmColors.ink,
              fontSize: 24,
              fontWeight: FontWeight.w900,
            ),
          ),
          const SizedBox(height: 4),
          Text(
            pending > 0
                ? 'Currently recorded as pending release through HPJ.'
                : 'Your currently loaded payout history has no pending amount.',
            style: TextStyle(
              color: FarmColors.mutedText,
              fontSize: 10.5,
              height: 1.35,
              fontWeight: FontWeight.w600,
            ),
          ),
          const SizedBox(height: 15),
          Row(
            children: [
              _metric(value: formatJmd(released), label: 'Released'),
              const SizedBox(width: 8),
              _metric(value: formatJmd(held), label: 'Held'),
              const SizedBox(width: 8),
              _metric(value: '$payoutCount', label: 'Records'),
            ],
          ),
        ],
      ),
    );
  }
}




