class FarmerAccountScreen extends StatelessWidget {
  final FarmerProfile profile;
  final Future<void> Function() onProfileChanged;

  const FarmerAccountScreen({
    super.key,
    required this.profile,
    required this.onProfileChanged,
  });

  void _open(BuildContext context, Widget screen) {
    Navigator.of(context).push(
      MaterialPageRoute<void>(builder: (_) => screen),
    );
  }

  Future<void> _editProfile(BuildContext context) async {
    final changed = await Navigator.of(context).push<bool>(
      MaterialPageRoute<bool>(
        builder: (_) => _FarmerProfileEditScreen(
          profile: profile,
        ),
      ),
    );

    if (changed == true) {
      await onProfileChanged();
    }
  }

  Future<void> _signOut(BuildContext context) async {
    await clearPrivateSessionStateForGuestBrowsing();

    if (!context.mounted) return;
    Navigator.of(context).pushAndRemoveUntil(
      MaterialPageRoute<void>(
        builder: (_) => const MainNavigation(),
      ),
      (_) => false,
    );
  }

  Future<void> _openTermsPrivacy(BuildContext context) async {
    await showModalBottomSheet<void>(
      context: context,
      useSafeArea: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => Container(
        padding: const EdgeInsets.fromLTRB(18, 12, 18, 22),
        decoration: const BoxDecoration(
          color: FarmColors.card,
          borderRadius: BorderRadius.vertical(top: Radius.circular(26)),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Container(
              width: 42,
              height: 4,
              decoration: BoxDecoration(
                color: FarmColors.line,
                borderRadius: BorderRadius.circular(999),
              ),
            ),
            const SizedBox(height: 14),
            const Align(
              alignment: Alignment.centerLeft,
              child: Text(
                'Terms & Privacy',
                style: TextStyle(
                  color: FarmColors.ink,
                  fontSize: 18,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
            const SizedBox(height: 10),
            ListTile(
              leading: const Icon(Icons.description_outlined),
              title: const Text('Terms of Service'),
              trailing: const Icon(Icons.chevron_right_rounded),
              onTap: () {
                Navigator.of(sheetContext).pop();
                _open(context, const TermsOfServiceScreen());
              },
            ),
            ListTile(
              leading: const Icon(Icons.privacy_tip_outlined),
              title: const Text('Privacy Policy'),
              trailing: const Icon(Icons.chevron_right_rounded),
              onTap: () {
                Navigator.of(sheetContext).pop();
                _open(context, const PrivacyPolicyScreen());
              },
            ),
          ],
        ),
      ),
    );
  }

  int _privateRecordScore() {
    final values = <String>[
      profile.farmName,
      profile.farmerName,
      profile.phone,
      profile.parish,
      profile.address,
      profile.bio,
      profile.payoutMethod,
      profile.payoutDetails,
    ];

    final complete =
        values.where((value) => value.trim().isNotEmpty).length;

    return ((complete / values.length) * 100).round();
  }

  @override
  Widget build(BuildContext context) {
    final nativeMobile = hpjUseMobileAppPresentation(context);
    final payoutReady =
        profile.payoutMethod.trim().isNotEmpty &&
        profile.payoutDetails.trim().isNotEmpty;

    final farmTitle = profile.farmName.trim().isEmpty
        ? profile.farmerName
        : profile.farmName;

    final statusColor = profile.isApproved
        ? FarmColors.success
        : profile.verificationStatus == 'rejected'
            ? FarmColors.danger
            : FarmColors.warning;

    final recordScore = _privateRecordScore();

    if (nativeMobile) {
      return FarmPage(
        child: FutureBuilder<FarmPublicProfileRecord?>(
          future: fetchFarmPublicProfile(
            profile.id,
            includeUnpublished: true,
          ),
          builder: (context, snapshot) {
            final publicProfile = snapshot.data;

            return _HpjFarmerAccountMobileMvp(
              profile: profile,
              farmTitle: farmTitle,
              statusLabel: profile.statusLabel,
              statusColor: statusColor,
              recordScore: recordScore,
              payoutReady: payoutReady,
              publicPageLive: publicProfile?.isPublished == true,
              hpjVerified: publicProfile?.hpjVerified == true,
              onEditProfile: () => _editProfile(context),
              onOpenFarmPage: () => _open(
                context,
                FarmerPublicProfileEditorScreen(farmer: profile),
              ),
              onOpenPayments: () => _open(
                context,
                FarmerEarningsScreen(profile: profile, refreshKey: 0),
              ),
              onOpenActivity: () => _open(
                context,
                _FarmerActivityStatementScreen(profile: profile),
              ),
              onOpenTrust: () => _open(context, const _HpjFarmerTrustCenterMvpScreen()),
              onOpenHelp: () => _open(
                context,
                const HpjAccountHelpInfoScreen(
                  supportSubject: 'Farmer support',
                ),
              ),
              onOpenTermsPrivacy: () => _openTermsPrivacy(context),
              onSignOut: () => _signOut(context),
              onOpenFreshReels: () => _open(
                context,
                FarmerFreshReelsHubScreen(profile: profile),
              ),
              onOpenSettings: () => _open(
                context,
                const _HpjFarmerSettingsMvpScreen(),
              ),
              onOpenStories: () => _open(
                context,
                HpjFarmerStoriesScreen(profile: profile),
              ),
              onOpenMealIntel: () => _open(
                context,
                const HpjFarmerMealIntelligenceScreen(),
              ),
              onOpenRelationships: () => _open(
                context,
                HpjFarmerRelationshipNetworkScreen(profile: profile),
              ),
              onOpenQuestions: () => _open(
                context,
                HpjFarmerQuestionsScreen(profile: profile),
              ),
            );
          },
        ),
      );
    }

    return FarmPage(
      child: ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        padding: const EdgeInsets.fromLTRB(18, 16, 18, 120),
        children: [
          FutureBuilder<FarmPublicProfileRecord?>(
            future: fetchFarmPublicProfile(
              profile.id,
              includeUnpublished: true,
            ),
            builder: (context, snapshot) {
              final publicProfile = snapshot.data;

              return _PremiumFarmerAccountHero(
                farmName: farmTitle,
                farmerName: profile.farmerName,
                parish: profile.parish,
                statusLabel: profile.statusLabel,
                statusColor: statusColor,
                recordScore: recordScore,
                payoutReady: payoutReady,
                publicPageLive: publicProfile?.isPublished == true,
                hpjVerified: publicProfile?.hpjVerified == true,
              );
            },
          ),
          const SizedBox(height: 14),

          LayoutBuilder(
            builder: (context, constraints) {
              final gap = 10.0;
              final width = (constraints.maxWidth - gap) / 2;

              final actions = <Widget>[
                _PremiumFarmerAccountQuickAction(
                  icon: Icons.badge_outlined,
                  title: 'Private details',
                  subtitle: 'Contact, location & payout',
                  onTap: () => _editProfile(context),
                ),
                _PremiumFarmerAccountQuickAction(
                  icon: Icons.storefront_outlined,
                  title: 'Farm Page',
                  subtitle: 'Story, images & public profile',
                  onTap: () => _open(
                    context,
                    FarmerPublicProfileEditorScreen(
                      farmer: profile,
                    ),
                  ),
                ),
                _PremiumFarmerAccountQuickAction(
                  icon: Icons.payments_outlined,
                  title: 'Payments',
                  subtitle: 'Pending, released & held',
                  onTap: () => _open(
                    context,
                    FarmerEarningsScreen(
                      profile: profile,
                      refreshKey: 0,
                    ),
                  ),
                ),
                _PremiumFarmerAccountQuickAction(
                  icon: Icons.description_outlined,
                  title: 'Activity',
                  subtitle: 'Farm record & PDF',
                  onTap: () => _open(
                    context,
                    _FarmerActivityStatementScreen(
                      profile: profile,
                    ),
                  ),
                ),
              ];

              return Wrap(
                spacing: gap,
                runSpacing: gap,
                children: actions
                    .map(
                      (item) => SizedBox(
                        width: width,
                        child: item,
                      ),
                    )
                    .toList(),
              );
            },
          ),
          const SizedBox(height: 14),

          _PremiumFarmerPrivateRecordNotice(
            payoutReady: payoutReady,
            recordScore: recordScore,
          ),
          const SizedBox(height: 14),

          FarmCard(
            padding: EdgeInsets.zero,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Padding(
                  padding: EdgeInsets.fromLTRB(15, 14, 15, 5),
                  child: AccountSectionHeading(
                    title: 'Farm & records',
                    subtitle:
                        'Manage the identity and records HPJ uses to work with your farm.',
                  ),
                ),
                AccountListTile(
                  icon: Icons.badge_outlined,
                  title: 'Farmer details',
                  subtitle: payoutReady
                      ? 'Private contact, farm location and payout details.'
                      : 'Payout setup needs attention.',
                  onTap: () => _editProfile(context),
                ),
                AccountListTile(
                  icon: Icons.storefront_outlined,
                  title: 'Public Farm Page',
                  subtitle:
                      'Manage your marketplace-safe story, cover image and farm photos.',
                  onTap: () => _open(
                    context,
                    FarmerPublicProfileEditorScreen(
                      farmer: profile,
                    ),
                  ),
                ),
                AccountListTile(
                  icon: Icons.description_outlined,
                  title: 'Activity Statement',
                  subtitle:
                      'Review supply, collections and payout history or export PDF.',
                  isLast: true,
                  onTap: () => _open(
                    context,
                    _FarmerActivityStatementScreen(
                      profile: profile,
                    ),
                  ),
                ),
              ],
            ),
          ),
          const SizedBox(height: 12),

          FarmCard(
            padding: EdgeInsets.zero,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Padding(
                  padding: EdgeInsets.fromLTRB(15, 14, 15, 5),
                  child: AccountSectionHeading(
                    title: 'Grow your HPJ presence',
                    subtitle:
                        'Media, alerts and preferences for your Farmer workspace.',
                  ),
                ),
                AccountListTile(
                  icon: Icons.play_circle_outline_rounded,
                  title: 'Fresh Reels',
                  subtitle:
                      'Submit farm videos and follow their approval status.',
                  onTap: () => _open(
                    context,
                    FarmerFreshReelsHubScreen(
                      profile: profile,
                    ),
                  ),
                ),
                AccountListTile(
                  icon: Icons.tune_rounded,
                  title: 'Settings & Preferences',
                  subtitle:
                      'Feed, Fresh Reels, alerts, privacy and password.',
                  isLast: true,
                  onTap: () => _open(
                    context,
                    const HpjSettingsPreferencesScreen(
                      audience: HpjPreferenceAudience.farmer,
                    ),
                  ),
                ),
              ],
            ),
          ),
          if (nativeMobile) ...[
            const SizedBox(height: 12),
            FarmCard(
              padding: EdgeInsets.zero,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Padding(
                    padding: EdgeInsets.fromLTRB(15, 14, 15, 5),
                    child: AccountSectionHeading(
                      title: 'Network & intelligence',
                      subtitle:
                          'Build relationships and use HPJ demand signals without cluttering your Home screen.',
                    ),
                  ),
                  HpjFarmerSocialFeatureGate(
                    feature: 'stories',
                    compact: true,
                    child: AccountListTile(
                      icon: Icons.auto_stories_outlined,
                      title: 'Farm Stories',
                      subtitle:
                          'Share planting, growing and harvest updates with customers.',
