class _HpjFarmerAccountMobileMvp extends StatelessWidget {
  final FarmerProfile profile;
  final String farmTitle;
  final String statusLabel;
  final Color statusColor;
  final int recordScore;
  final bool payoutReady;
  final bool publicPageLive;
  final bool hpjVerified;
  final VoidCallback onEditProfile;
  final VoidCallback onOpenFarmPage;
  final VoidCallback onOpenPayments;
  final VoidCallback onOpenActivity;
  final VoidCallback onOpenTrust;
  final VoidCallback onOpenHelp;
  final VoidCallback onOpenTermsPrivacy;
  final VoidCallback onSignOut;
  final VoidCallback onOpenFreshReels;
  final VoidCallback onOpenSettings;
  final VoidCallback onOpenStories;
  final VoidCallback onOpenMealIntel;
  final VoidCallback onOpenRelationships;
  final VoidCallback onOpenQuestions;

  const _HpjFarmerAccountMobileMvp({
    required this.profile,
    required this.farmTitle,
    required this.statusLabel,
    required this.statusColor,
    required this.recordScore,
    required this.payoutReady,
    required this.publicPageLive,
    required this.hpjVerified,
    required this.onEditProfile,
    required this.onOpenFarmPage,
    required this.onOpenPayments,
    required this.onOpenActivity,
    required this.onOpenTrust,
    required this.onOpenHelp,
    required this.onOpenTermsPrivacy,
    required this.onSignOut,
    required this.onOpenFreshReels,
    required this.onOpenSettings,
    required this.onOpenStories,
    required this.onOpenMealIntel,
    required this.onOpenRelationships,
    required this.onOpenQuestions,
  });

  @override
  Widget build(BuildContext context) {
    Widget menuTile({
      required IconData icon,
      required String title,
      required VoidCallback onTap,
      String? badge,
    }) {
      return Material(
        color: Colors.white,
        borderRadius: BorderRadius.circular(17),
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(17),
          child: Container(
            padding: const EdgeInsets.symmetric(
              horizontal: 12,
              vertical: 11,
            ),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(17),
              border: Border.all(color: const Color(0xFFDDE7DD)),
            ),
            child: Row(
              children: [
                Container(
                  width: 40,
                  height: 40,
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: const Color(0xFFEAF5E9),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Icon(
                    icon,
                    color: FarmColors.primary,
                    size: 20,
                  ),
                ),
                const SizedBox(width: 11),
                Expanded(
                  child: Text(
                    title,
                    style: const TextStyle(
                      color: FarmColors.ink,
                      fontSize: 12.5,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ),
                if (badge != null) ...[
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 8,
                      vertical: 4,
                    ),
                    decoration: BoxDecoration(
                      color: const Color(0xFFEAF5E9),
                      borderRadius: BorderRadius.circular(999),
                    ),
                    child: Text(
                      badge,
                      style: const TextStyle(
                        color: FarmColors.deepGreen,
                        fontSize: 8,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                  const SizedBox(width: 5),
                ],
                const Icon(
                  Icons.chevron_right_rounded,
                  color: FarmColors.mutedText,
                ),
              ],
            ),
          ),
        ),
      );
    }

    final farmName = farmTitle.trim().isEmpty ? 'Your Farm' : farmTitle.trim();

    return ListView(
      physics: const AlwaysScrollableScrollPhysics(),
      padding: const EdgeInsets.fromLTRB(14, 12, 14, 118),
      children: [
        Container(
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(22),
            border: Border.all(color: const Color(0xFFDDE7DD)),
          ),
          child: Row(
            children: [
              FutureBuilder<FarmPublicProfileRecord?>(
                future: fetchFarmPublicProfile(
                  profile.id,
                  includeUnpublished: true,
                ),
                builder: (context, snapshot) {
                  final logo = cleanHostedImageUrl(
                    snapshot.data?.logoImageUrl,
                  );

                  Widget fallback() {
                    final cleanName = farmName.trim();
                    final words = cleanName
                        .split(RegExp(r'\\s+'))
                        .where((word) => word.trim().isNotEmpty)
                        .toList(growable: false);

                    String initials = 'F';
                    if (words.length >= 2) {
                      initials =
                          '${words[0][0]}${words[1][0]}'.toUpperCase();
                    } else if (words.length == 1) {
                      final word = words.first;
                      initials = word.length >= 2
                          ? word.substring(0, 2).toUpperCase()
                          : word.substring(0, 1).toUpperCase();
                    }

                    return Container(
                      decoration: const BoxDecoration(
                        gradient: LinearGradient(
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                          colors: [
                            Color(0xFFEAF5E9),
                            Color(0xFFD7EBD4),
                          ],
                        ),
                      ),
                      alignment: Alignment.center,
                      child: Text(
                        initials,
                        style: const TextStyle(
                          color: FarmColors.deepGreen,
                          fontSize: 20,
                          letterSpacing: .6,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    );
                  }

                  return Container(
                    width: 60,
                    height: 60,
                    padding: const EdgeInsets.all(3),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      shape: BoxShape.circle,
                      border: Border.all(
                        color: const Color(0xFFDDE7DD),
                        width: 1.5,
                      ),
                      boxShadow: [
                        BoxShadow(
                          color: const Color(0xFF0B4A33).withOpacity(.10),
                          blurRadius: 10,
                          offset: const Offset(0, 3),
                        ),
                      ],
                    ),
                    child: ClipOval(
                      child: logo == null
                          ? fallback()
                          : Image.network(
                              logo,
                              fit: BoxFit.cover,
                              errorBuilder: (_, __, ___) => fallback(),
                            ),
                    ),
                  );
                },
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      farmName,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 19,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 4),
                    Text(
                      profile.parish.trim().isEmpty
                          ? profile.farmerName
                          : '${profile.farmerName} • ${profile.parish}',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 9.5,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 7),
                    Wrap(
                      spacing: 6,
                      runSpacing: 6,
                      children: [
                        _HpjStatusPill(
                          label: statusLabel,
                          active: profile.isApproved,
                          warning: !profile.isApproved,
                        ),
                        if (hpjVerified)
                          const _HpjStatusPill(
                            label: 'HPJ Verified',
                            active: true,
                            warning: false,
                          ),
                      ],
                    ),
                  ],
                ),
              ),
              IconButton(
                tooltip: 'Edit farm details',
                onPressed: onEditProfile,
                icon: const Icon(
                  Icons.edit_outlined,
                  color: FarmColors.primary,
                ),
              ),
            ],
          ),
        ),

        const SizedBox(height: 14),
        const Text(
          'Account',
          style: TextStyle(
            color: FarmColors.ink,
            fontSize: 17,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 9),

        menuTile(
          icon: Icons.person_outline_rounded,
          title: 'Private details',
          onTap: onEditProfile,
          badge: recordScore < 100 ? '$recordScore%' : 'Ready',
        ),
        const SizedBox(height: 8),
        menuTile(
          icon: Icons.storefront_outlined,
          title: 'Farm Page',
          onTap: onOpenFarmPage,
          badge: publicPageLive ? 'Live' : 'Draft',
        ),
        const SizedBox(height: 8),
        menuTile(
          icon: Icons.account_balance_wallet_outlined,
          title: 'Payments',
          onTap: onOpenPayments,
          badge: payoutReady ? 'Ready' : 'Set up',
        ),
        const SizedBox(height: 8),
        menuTile(
          icon: Icons.description_outlined,
          title: 'Activity',
          onTap: onOpenActivity,
        ),

        const SizedBox(height: 16),
        const Text(
          'Support',
          style: TextStyle(
            color: FarmColors.ink,
            fontSize: 17,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 9),

        menuTile(
          icon: Icons.shield_outlined,
          title: 'Trust Center',
          onTap: onOpenTrust,
        ),
        const SizedBox(height: 8),
        menuTile(
          icon: Icons.headset_mic_outlined,
          title: 'Help & Support',
          onTap: onOpenHelp,
        ),
        const SizedBox(height: 8),
        menuTile(
          icon: Icons.description_outlined,
          title: 'Terms & Privacy',
          onTap: onOpenTermsPrivacy,
        ),
        const SizedBox(height: 8),
        menuTile(
          icon: Icons.tune_rounded,
          title: 'Settings',
          onTap: onOpenSettings,
        ),

        const SizedBox(height: 14),
        HpjInviteGrowthShortcut(audience: 'farmer'),

        const SizedBox(height: 12),
        ExpansionTile(
          tilePadding: const EdgeInsets.symmetric(horizontal: 4),
          childrenPadding: EdgeInsets.zero,
          leading: const Icon(
            Icons.apps_rounded,
            color: FarmColors.primary,
          ),
          title: const Text(
            'More tools',
            style: TextStyle(
              color: FarmColors.ink,
              fontSize: 12.5,
              fontWeight: FontWeight.w900,
            ),
          ),
          children: [
            AccountListTile(
              icon: Icons.play_circle_outline_rounded,
              title: 'Fresh Reels',
              subtitle: 'Videos and approvals',
              onTap: onOpenFreshReels,
            ),
            AccountListTile(
              icon: Icons.auto_stories_outlined,
              title: 'Farm Stories',
              subtitle: 'Growing and harvest updates',
              onTap: onOpenStories,
            ),
            AccountListTile(
              icon: Icons.restaurant_menu_rounded,
              title: 'Meal Intelligence',
              subtitle: 'Ingredient demand signals',
              onTap: onOpenMealIntel,
            ),
            AccountListTile(
              icon: Icons.handshake_outlined,
              title: 'Relationships',
              subtitle: 'Repeat customer signals',
              onTap: onOpenRelationships,
            ),
            AccountListTile(
              icon: Icons.forum_outlined,
              title: 'Questions',
              subtitle: 'Answer crop questions',
              isLast: true,
              onTap: onOpenQuestions,
            ),
          ],
        ),

        const SizedBox(height: 8),
        TextButton.icon(
          onPressed: onSignOut,
          icon: const Icon(Icons.logout_rounded),
          label: const Text('Sign out'),
          style: TextButton.styleFrom(
            foregroundColor: const Color(0xFFB42318),
          ),
        ),
      ],
    );
  }

}

