String _farmerStatementDate(
  DateTime? value,
) {
  if (value == null) return '-';

  return '${value.year}-'
      '${value.month.toString().padLeft(2, '0')}-'
      '${value.day.toString().padLeft(2, '0')}';
}

String _farmerStatementStatus(
  String value,
) {
  final clean = value
      .trim()
      .replaceAll('_', ' ');

  if (clean.isEmpty) return '-';

  return clean
      .split(' ')
      .where((item) => item.isNotEmpty)
      .map(
        (item) =>
            '${item[0].toUpperCase()}${item.substring(1)}',
      )
      .join(' ');
}

Future<Uint8List> _buildFarmerActivityStatementPdf(
  FarmerProfile profile,
  _FarmerTodaySnapshot data,
) async {
  final pdf = pw.Document();

  pw.MemoryImage? logo;

  try {
    final bytes = await rootBundle.load(
      'lib/assets/images/logo.png',
    );

    logo = pw.MemoryImage(
      bytes.buffer.asUint8List(),
    );
  } catch (_) {
    logo = null;
  }

  final green =
      PdfColor.fromInt(0xFF1F6B3A);
  final softGreen =
      PdfColor.fromInt(0xFFEAF3EC);

  final released = data.payouts
      .where(
        (item) =>
            item.payoutStatus
                .trim()
                .toLowerCase() ==
            'released',
      )
      .fold<double>(
        0,
        (sum, item) =>
            sum + item.netAmount,
      );

  final completedCollections =
      data.collections
          .where(
            (item) =>
                item.stopStatus
                    .trim()
                    .toLowerCase() ==
                'completed',
          )
          .length;

  pw.Widget metric(
    String label,
    String value,
  ) {
    return pw.Expanded(
      child: pw.Container(
        padding: const pw.EdgeInsets.all(9),
        decoration: pw.BoxDecoration(
          color: softGreen,
          borderRadius:
              pw.BorderRadius.circular(6),
        ),
        child: pw.Column(
          crossAxisAlignment:
              pw.CrossAxisAlignment.start,
          children: [
            pw.Text(
              label,
              style: const pw.TextStyle(
                fontSize: 7.5,
                color: PdfColors.grey700,
              ),
            ),
            pw.SizedBox(height: 4),
            pw.Text(
              pdfSafe(value),
              style: pw.TextStyle(
                fontSize: 11,
                fontWeight:
                    pw.FontWeight.bold,
                color: green,
              ),
            ),
          ],
        ),
      ),
    );
  }

  pw.Widget sectionTitle(String value) {
    return pw.Container(
      width: double.infinity,
      padding:
          const pw.EdgeInsets.symmetric(
        vertical: 6,
        horizontal: 8,
      ),
      decoration: pw.BoxDecoration(
        color: softGreen,
        borderRadius:
            pw.BorderRadius.circular(5),
      ),
      child: pw.Text(
        value,
        style: pw.TextStyle(
          fontSize: 10,
          fontWeight: pw.FontWeight.bold,
          color: green,
        ),
      ),
    );
  }

  pw.Widget table({
    required List<String> headers,
    required List<List<String>> rows,
  }) {
    if (rows.isEmpty) {
      return pw.Padding(
        padding:
            const pw.EdgeInsets.symmetric(
          vertical: 8,
        ),
        child: pw.Text(
          'No records available.',
          style: const pw.TextStyle(
            fontSize: 8.5,
            color: PdfColors.grey600,
          ),
        ),
      );
    }

    return pw.TableHelper.fromTextArray(
      headers: headers,
      data: rows
          .map(
            (row) => row
                .map(pdfSafe)
                .toList(),
          )
          .toList(),
      headerDecoration: pw.BoxDecoration(
        color: PdfColors.grey200,
      ),
      headerStyle: pw.TextStyle(
        fontSize: 7.5,
        fontWeight: pw.FontWeight.bold,
      ),
      cellStyle:
          const pw.TextStyle(fontSize: 7.2),
      cellPadding:
          const pw.EdgeInsets.all(4),
      border: pw.TableBorder.all(
        color: PdfColors.grey300,
        width: 0.5,
      ),
    );
  }

  final supplies = List<FarmerSupplyForecast>.from(
    data.supplies,
  )
    ..sort(
      (a, b) =>
          (b.updatedAt ??
                  b.createdAt ??
                  DateTime(2000))
              .compareTo(
        a.updatedAt ??
            a.createdAt ??
            DateTime(2000),
      ),
    );

  final collections =
      List<FarmerCollectionScheduleItem>.from(
    data.collections,
  )
        ..sort(
          (a, b) => b.collectionDate
              .compareTo(a.collectionDate),
        );

  final payouts =
      List<FarmerPayout>.from(
    data.payouts,
  )
        ..sort(
          (a, b) =>
              (b.createdAt ??
                      DateTime(2000))
                  .compareTo(
            a.createdAt ??
                DateTime(2000),
          ),
        );

  pdf.addPage(
    pw.MultiPage(
      pageFormat: PdfPageFormat.a4,
      margin: const pw.EdgeInsets.fromLTRB(
        32,
        30,
        32,
        34,
      ),
      footer: (context) => pw.Column(
        children: [
          pw.Divider(
            color: PdfColors.grey300,
          ),
          pw.Row(
            mainAxisAlignment:
                pw.MainAxisAlignment
                    .spaceBetween,
            children: [
              pw.Text(
                'The Harvest Place Ja',
                style: const pw.TextStyle(
                  fontSize: 7,
                  color: PdfColors.grey600,
                ),
              ),
              pw.Text(
                'Page ${context.pageNumber} of ${context.pagesCount}',
                style: const pw.TextStyle(
                  fontSize: 7,
                  color: PdfColors.grey600,
                ),
              ),
            ],
          ),
        ],
      ),
      build: (context) => [
        pw.Row(
          crossAxisAlignment:
              pw.CrossAxisAlignment.center,
          children: [
            if (logo != null)
              pw.Container(
                width: 54,
                height: 54,
                child: pw.Image(
                  logo,
                  fit: pw.BoxFit.contain,
                ),
              ),
            if (logo != null)
              pw.SizedBox(width: 12),
            pw.Expanded(
              child: pw.Column(
                crossAxisAlignment:
                    pw.CrossAxisAlignment
                        .start,
                children: [
                  pw.Text(
                    'FARMER ACTIVITY STATEMENT',
                    style: pw.TextStyle(
                      color: green,
                      fontSize: 16,
                      fontWeight:
                          pw.FontWeight.bold,
                    ),
                  ),
                  pw.SizedBox(height: 3),
                  pw.Text(
                    pdfSafe(
                      profile.farmName
                              .trim()
                              .isEmpty
                          ? profile.farmerName
                          : profile.farmName,
                    ),
                    style: pw.TextStyle(
                      fontSize: 11,
                      fontWeight:
                          pw.FontWeight.bold,
                    ),
                  ),
                  pw.Text(
                    'Generated ${_farmerStatementDate(DateTime.now())}',
                    style:
                        const pw.TextStyle(
                      fontSize: 7.5,
                      color:
                          PdfColors.grey600,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),

        pw.SizedBox(height: 16),

        pw.Container(
          width: double.infinity,
          padding:
              const pw.EdgeInsets.all(10),
          decoration: pw.BoxDecoration(
            border: pw.Border.all(
              color: PdfColors.grey300,
            ),
            borderRadius:
                pw.BorderRadius.circular(6),
          ),
          child: pw.Column(
            crossAxisAlignment:
                pw.CrossAxisAlignment.start,
            children: [
              pw.Text(
                pdfSafe(
                  profile.farmerName,
                ),
                style: pw.TextStyle(
                  fontSize: 10,
                  fontWeight:
                      pw.FontWeight.bold,
                ),
              ),
              pw.SizedBox(height: 3),
              pw.Text(
                pdfSafe(
                  [
                    if (profile.parish
                        .trim()
                        .isNotEmpty)
                      profile.parish,
                    if (profile.phone
                        .trim()
                        .isNotEmpty)
                      profile.phone,
                  ].join(' | '),
                ),
                style: const pw.TextStyle(
                  fontSize: 8,
                ),
              ),
            ],
          ),
        ),

        pw.SizedBox(height: 12),

        pw.Row(
          children: [
            metric(
              'Supply reports',
              '${data.supplies.length}',
            ),
            pw.SizedBox(width: 7),
            metric(
              'Collections completed',
              '$completedCollections',
            ),
            pw.SizedBox(width: 7),
            metric(
              'Released payouts',
              formatJmd(released),
            ),
          ],
        ),

        pw.SizedBox(height: 18),
        sectionTitle(
          'SUPPLY HISTORY',
        ),
        pw.SizedBox(height: 6),
        table(
          headers: const [
            'Crop',
            'Expected',
            'Harvest date',
            'Status',
          ],
          rows: supplies
              .take(30)
              .map(
                (item) => [
                  item.cropName,
                  '${_farmerPartnerNumber(item.expectedQuantity ?? 0)} ${item.unit}',
                  _farmerStatementDate(
                    item.expectedHarvestDate,
                  ),
                  item.statusLabel,
                ],
              )
              .toList(),
        ),

        pw.SizedBox(height: 16),
        sectionTitle(
          'COLLECTION HISTORY',
        ),
        pw.SizedBox(height: 6),
        table(
          headers: const [
            'Date',
            'Produce',
            'Collected',
            'Status',
          ],
          rows: collections
              .take(30)
              .map(
                (item) => [
                  _farmerStatementDate(
                    item.collectionDate,
                  ),
                  item.productName,
                  '${_farmerPartnerNumber(item.collectedQuantity)} ${item.unit}',
                  _farmerStatementStatus(
                    item.stopStatus,
                  ),
                ],
              )
              .toList(),
        ),

        pw.SizedBox(height: 16),
        sectionTitle(
          'PAYOUT HISTORY',
        ),
        pw.SizedBox(height: 6),
        table(
          headers: const [
            'Date',
            'Produce',
            'Net amount',
            'Status',
          ],
          rows: payouts
              .take(30)
              .map(
                (item) => [
                  _farmerStatementDate(
                    item.createdAt,
                  ),
                  item.productName
                          .trim()
                          .isEmpty
                      ? 'Farmer payout'
                      : item.productName,
                  formatJmd(
                    item.netAmount,
                  ),
                  _farmerStatementStatus(
                    item.payoutStatus,
                  ),
                ],
              )
              .toList(),
        ),

        pw.SizedBox(height: 18),

        pw.Container(
          padding:
              const pw.EdgeInsets.all(9),
          decoration: pw.BoxDecoration(
            color: PdfColors.grey100,
            borderRadius:
                pw.BorderRadius.circular(5),
          ),
          child: pw.Text(
            'This statement is a record of activity held in The Harvest Place Ja system. '
            'It is not a bank statement, credit rating, tax certificate or guarantee of future sales.',
            style: const pw.TextStyle(
              fontSize: 7.4,
              color: PdfColors.grey700,
            ),
          ),
        ),
      ],
    ),
  );

  return pdf.save();
}

class _FarmerActivityStatementScreen
    extends StatefulWidget {
  final FarmerProfile profile;

  const _FarmerActivityStatementScreen({
    required this.profile,
  });

  @override
  State<_FarmerActivityStatementScreen>
      createState() =>
          _FarmerActivityStatementScreenState();
}

class _FarmerActivityStatementScreenState
    extends State<_FarmerActivityStatementScreen> {
  late Future<_FarmerTodaySnapshot> future;
  bool exporting = false;

  @override
  void initState() {
    super.initState();

    future = fetchFarmerTodaySnapshot(
      widget.profile,
    );
  }

  Future<void> _refresh() async {
    setState(() {
      future = fetchFarmerTodaySnapshot(
        widget.profile,
      );
    });

    await future;
  }

  Future<void> _printOrSave(
    _FarmerTodaySnapshot data,
  ) async {
    if (exporting) return;

    setState(() {
      exporting = true;
    });

    try {
      final bytes =
          await _buildFarmerActivityStatementPdf(
        widget.profile,
        data,
      );

      await Printing.layoutPdf(
        onLayout: (_) async => bytes,
        name:
            'HPJ_Farmer_Activity_Statement.pdf',
      );
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    } finally {
      if (mounted) {
        setState(() {
          exporting = false;
        });
      }
    }
  }

  Future<void> _share(
    _FarmerTodaySnapshot data,
  ) async {
    if (exporting) return;

    setState(() {
      exporting = true;
    });

    try {
      final bytes =
          await _buildFarmerActivityStatementPdf(
        widget.profile,
        data,
      );

      await Printing.sharePdf(
        bytes: bytes,
        filename:
            'HPJ_Farmer_Activity_Statement.pdf',
      );
    } catch (error) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            friendlyAppError(error),
          ),
        ),
      );
    } finally {
      if (mounted) {
        setState(() {
          exporting = false;
        });
      }
    }
  }

  Widget _statementHero(
    _FarmerTodaySnapshot data, {
    required double released,
    required double pending,
    required int completedCollections,
  }) {
    Widget metric(String value, String label, IconData icon) {
      return Expanded(
        child: Container(
          padding: const EdgeInsets.all(11),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: const Color(0xFFDDE7DD)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Icon(icon, color: FarmColors.primary, size: 18),
              const SizedBox(height: 7),
              FittedBox(
                fit: BoxFit.scaleDown,
                alignment: Alignment.centerLeft,
                child: Text(
                  value,
                  style: const TextStyle(
                    color: FarmColors.ink,
                    fontSize: 14,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              const SizedBox(height: 2),
              Text(
                label,
                style: const TextStyle(
                  color: FarmColors.mutedText,
                  fontSize: 8.4,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ],
          ),
        ),
      );
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Text(
          'Activity summary',
          style: TextStyle(
            color: FarmColors.ink,
            fontSize: 17,
            fontWeight: FontWeight.w900,
          ),
        ),
        const SizedBox(height: 9),
        Row(
          children: [
            metric(
              '${data.supplies.length}',
              'Crop reports',
              Icons.eco_outlined,
            ),
            const SizedBox(width: 8),
            metric(
              '$completedCollections',
              'Collections',
              Icons.local_shipping_outlined,
            ),
            const SizedBox(width: 8),
            metric(
              formatJmd(released),
              'Paid',
              Icons.payments_outlined,
            ),
          ],
        ),
        if (pending > 0) ...[
          const SizedBox(height: 8),
          Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(
              horizontal: 12,
              vertical: 10,
            ),
            decoration: BoxDecoration(
              color: const Color(0xFFFFF6E7),
              borderRadius: BorderRadius.circular(14),
            ),
            child: Text(
              '${formatJmd(pending)} pending',
              style: const TextStyle(
                color: Color(0xFF9B6500),
                fontSize: 10,
                fontWeight: FontWeight.w900,
              ),
            ),
          ),
        ],
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: FarmColors.background,
      appBar: AppBar(
        title: const Text('Activity Statement'),
      ),
      body: FutureBuilder<_FarmerTodaySnapshot>(
        future: future,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting &&
              snapshot.data == null) {
            return const Center(child: CircularProgressIndicator());
          }

          if (snapshot.hasError || snapshot.data == null) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(24),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Text(
                      'Your activity statement could not be loaded.',
                      textAlign: TextAlign.center,
                    ),
                    const SizedBox(height: 12),
                    OutlinedButton(
                      onPressed: _refresh,
                      child: const Text('Try Again'),
                    ),
                  ],
                ),
              ),
            );
          }

          final data = snapshot.data!;

          final released = data.payouts
              .where(
                (item) =>
                    item.payoutStatus.trim().toLowerCase() == 'released',
              )
              .fold<double>(0, (sum, item) => sum + item.netAmount);

          final pending = data.payouts
              .where(
                (item) =>
                    item.payoutStatus.trim().toLowerCase() == 'pending',
              )
              .fold<double>(0, (sum, item) => sum + item.netAmount);

          final completedCollections = data.collections
              .where(
                (item) =>
                    item.stopStatus.trim().toLowerCase() == 'completed' ||
                    item.stopStatus.trim().toLowerCase() == 'collected' ||
                    item.receivingStatus.trim().toLowerCase() == 'completed',
              )
              .length;

          return RefreshIndicator(
            onRefresh: _refresh,
            child: ListView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 32),
              children: [
                _statementHero(
                  data,
                  released: released,
                  pending: pending,
                  completedCollections: completedCollections,
                ),
                const SizedBox(height: 14),
                FarmCard(
                  padding: const EdgeInsets.all(15),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Row(
                        children: [
                          Icon(
                            Icons.picture_as_pdf_outlined,
                            color: FarmColors.deepGreen,
                          ),
                          SizedBox(width: 9),
                          Expanded(
                            child: Text(
                              'Export your farm record',
                              style: TextStyle(
                                color: FarmColors.ink,
                                fontSize: 15,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      const Text(
                        'Save or share the existing HPJ activity statement PDF '
                        'for your own records or discussions with HPJ.',
                        style: TextStyle(
                          color: FarmColors.mutedText,
                          fontSize: 9.7,
                          height: 1.4,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                      const SizedBox(height: 12),
                      SizedBox(
                        width: double.infinity,
                        child: ElevatedButton.icon(
                          onPressed:
                              exporting ? null : () => _printOrSave(data),
                          icon: const Icon(Icons.picture_as_pdf_outlined),
                          label: Text(
                            exporting ? 'Preparing...' : 'View / Save PDF',
                          ),
                        ),
                      ),
                      const SizedBox(height: 7),
                      SizedBox(
                        width: double.infinity,
                        child: OutlinedButton.icon(
                          onPressed: exporting ? null : () => _share(data),
                          icon: const Icon(Icons.share_outlined),
                          label: const Text('Share PDF'),
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 12),
                FarmCard(
                  padding: const EdgeInsets.all(14),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text(
                        'What this record includes',
                        style: TextStyle(
                          color: FarmColors.ink,
                          fontSize: 14,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(height: 10),
                      _FarmerPhase13RecordRow(
                        icon: Icons.agriculture_outlined,
                        title: 'Supply',
                        value: '${data.supplies.length} reports',
                      ),
                      const SizedBox(height: 8),
                      _FarmerPhase13RecordRow(
                        icon: Icons.local_shipping_outlined,
                        title: 'Collections',
                        value: '$completedCollections completed',
                      ),
                      const SizedBox(height: 8),
                      _FarmerPhase13RecordRow(
                        icon: Icons.payments_outlined,
                        title: 'Released payouts',
                        value: formatJmd(released),
                      ),
                    ],
                  ),
                ),
                const SizedBox(height: 12),
                Container(
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: const Color(0xFFF0F4EC),
                    borderRadius: BorderRadius.circular(15),
                    border: Border.all(color: const Color(0xFFDCE4D8)),
                  ),
                  child: const Text(
                    'This is an HPJ activity record, not a bank statement, '
                    'credit rating, tax certificate or guarantee of future sales.',
                    style: TextStyle(
                      color: FarmColors.mutedText,
                      fontSize: 9.4,
                      height: 1.35,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}

