class _FarmerMobileAccountPortalsCard extends StatelessWidget {
  final FarmerProfile profile;

  const _FarmerMobileAccountPortalsCard({
    required this.profile,
  });

  String get _name {
    final value = profile.farmerName.trim();
    if (value.isNotEmpty) return value;

    final user = supabase.auth.currentUser;
    final metadataName =
        user?.userMetadata?['full_name']?.toString().trim() ?? '';
    return metadataName.isEmpty ? 'HPJ Account' : metadataName;
  }

  String get _initial {
    final clean = _name.trim();
    return clean.isEmpty ? 'H' : clean.substring(0, 1).toUpperCase();
  }

  @override
  Widget build(BuildContext context) {
    return Material(
      color: const Color(0xFFFFFEFB),
      borderRadius: BorderRadius.circular(20),
      child: InkWell(
        borderRadius: BorderRadius.circular(20),
        onTap: () => unawaited(
          showHpjMobileAccountPortalSheet(
            context,
            currentPortal: 'farmer',
          ),
        ),
        child: Container(
          padding: const EdgeInsets.fromLTRB(13, 12, 11, 12),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(20),
            border: Border.all(color: const Color(0xFFE1E7DF)),
          ),
          child: Row(
            children: [
              CircleAvatar(
                radius: 21,
                backgroundColor: const Color(0xFFEAF3E7),
                child: Text(
                  _initial,
                  style: const TextStyle(
                    color: FarmColors.deepGreen,
                    fontWeight: FontWeight.w900,
                  ),
                ),
              ),
              const SizedBox(width: 11),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      _name,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: FarmColors.ink,
                        fontSize: 12.6,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 2),
                    const Text(
                      'Account & portals',
                      style: TextStyle(
                        color: FarmColors.mutedText,
                        fontSize: 10.5,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 8),
              const Icon(
                Icons.keyboard_arrow_down_rounded,
                color: FarmColors.green,
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _FarmerWorkspaceSwitchCard extends StatelessWidget {
  const _FarmerWorkspaceSwitchCard();

  @override
